int cnt[65];

inline char get(int x)
{
	if(x >= 0 && x < 26) return x + 'A';
	if(x >= 26 && x < 52) return x - 26 + 'a';
	return x - 52 + '0';
}

inline int query(vector<int> t)
{
	printf("? ");
	for(int i = 0; i < t.size(); i++) putchar(get(t[i]));
	puts("");
	fflush(stdout);
	int x; 
	scanf("%d", &x);
	return x;
}

inline vector<int> solve(int l, int r)
{
	if(l == r)
	{
		vector<int> t;
		for(int i = 0; i < cnt[l]; i++) t.push_back(l);
		return t;
	}
	int mid = (l + r) >> 1;
	vector<int> tl = solve(l, mid), tr = solve(mid + 1, r);
	vector<int> res;
	int x = 0, y = 0;
	while(x < tl.size() && y < tr.size())
	{
		vector<int> t(res);
		t.push_back(tl[x]); t.push_back(tr[y]);
		if(query(t)) res.push_back(tr[y ++]);
		else res.push_back(tl[x ++]);
	}
	while(x < tl.size()) res.push_back(tl[x ++]);
	while(y < tr.size()) res.push_back(tr[y ++]);
	return res;
}

int main()
{
