int Ask(string s) {
  auto it = cache.find(s);
  if (it != cache.end()) {
    return it->second;
  }
  cout << "? " + s << endl << flush;

  int ld;
  cin >> ld;
  return cache[s] = ld;
}

class Solver {
public:
  Solver() {
  }

  string Solve() {
    vector<string> ss;

    len = 0;
    for(int i=0; i<(int)chars.size(); ++i) {
      int charCnt = 128 - Ask(string(128, chars[i]));

      ss.emplace_back(charCnt, chars[i]);

      len += charCnt;
    }

    while(ss.size() > 1) {
      sort(ss.begin(), ss.end(), [](const string& l, const string& r) {
        return l.size() < r.size();
        });

      ss[1] = insert(ss[1], ss[0]);
      ss.erase(ss.begin());
    }

    return ss[0];
  }


private:
  string insert(string a, string b) {

    int pos = 0;
    for(int i=0; i<(int)b.size(); ++i) {

      while (true) {
        string s;
        int ld = Ask(s = a.substr(0, pos) + b[i] + a.substr(pos));

        pos++;
        if (ld == len - (int)a.size() - 1) {
          a = s;
          break;
        }
      }
    }

    return a;
  }

  int len;
};

signed main() {
  Solver s;
  cout << "! " << s.Solve() << endl;
  return 0;
}

