const int maxl = 128;
string subs[64];
int len;

// solve [l, r)
string dfs(int l, int r) {
    if (r - l == 1) {
        return subs[l];
    }
    int m = (l + r) / 2;
    string A = dfs(l, m);
    string B = dfs(m, r);
    int ap = 0, bp = 0;
    string cur;

    while (ap < A.size() || bp < B.size()) {
        if (ap < A.size()) {
            cur.pb(A[ap]);
            if (ask(cur) == len - cur.size()) {
                ap++;
                continue;
            } else {
                cur.pop_back();
            }
        }
        cur.pb(B[bp++]);
    }
    return cur;
}

int main() {
    string kinds;
    for (char c = 'a'; c <= 'z'; ++c) kinds.pb(c);
    for (char c = 'A'; c <= 'Z'; ++c) kinds.pb(c);
    for (char c = '0'; c <= '9'; ++c) kinds.pb(c);

    int sz = SZ(kinds);
    V<int> freq(sz);

    rep(i, SZ(kinds)) {
        string t(maxl, kinds[i]);
        int r = ask(t);
        freq[i] = maxl - r;
        len += freq[i];
        subs[i] = string(freq[i], kinds[i]);
    }

    string ans = dfs(0, sz);
    answer(ans);

    return 0;
}

