const int L 	= 128;
const int N 	= 130;
const int A		= 70;
const int INF 	= 0x3f3f3f3f;
int dp[N][N];

int med(string s, string t) {
	fill_n(dp[0], N * N, INF);
	for (int i = 0; i < N; ++i) {
		dp[i][0] = i;
		dp[0][i] = i;
	}
	for (int i = 1; i <= (int)s.size(); ++i) {
		for (int j = 1; j <= (int)t.size(); ++j) {
			dp[i][j] = min({dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + (s[i - 1] != t[j - 1])});
		}
	}
	return dp[s.size()][t.size()];
}

string secret;
int qcnt = 0;

int query(string s) {
	assert((int)s.size() <= L);
	++qcnt;
#ifdef LC
	return med(s, secret);
#else
