int n = 128;

int counter = 0;

int ask(const string &s) {
    ++counter;
    assert(counter < 850);
    cout << "? " << s << endl;
    int x;
    cin >> x;
    return x;
}

string unite(const string &s, const string &t) {
    string res = s;

    for (int i = 0, ps = 0; i < sz(t); ++i) {
        while (true) {
            string q = res.substr(0, ps);
            q += t[i];
            q += res.substr(ps, sz(res) - ps);
            if (ask(q) == n - sz(q)) {
                res = q;
                ++ps;
                break;
            } else {
                ++ps;
            }
        }
    }

    return res;
}

void solve() {

    vector<char> ch;

    for (char c = 'A'; c <= 'Z'; ++c) {
        ch.push_back(c);
    }
    for (char c = 'a'; c <= 'z'; ++c) {
        ch.push_back(c);
    }
    for (char c = '0'; c <= '9'; ++c) {
        ch.push_back(c);
    }

    int k = sz(ch);


    vector<int> cnt(k);
    for (int i = 0; i < k; ++i) {
        string s;
        for (int j = 0; j < n; ++j) {
            s += ch[i];
        }
        cnt[i] = ask(s);
    }

    vector<string> str;

    int sum = 0;
    for (int i = 0; i < k; ++i) {
        sum += cnt[i];
        if (cnt[i] == 0) {
            continue;
        }
        string s;
        for (int j = 0; j < cnt[i]; ++j) {
            s += ch[i];
        }
        str.push_back(s);
    }
    assert(sum == n);


    while (sz(str) > 1) {
        sort(all(str), [](const string &s, const string &t) {
            return sz(s) < sz(t);
        });

        string s = str[0];
        string t = str[1];
        reverse(all(str));
        str.pop_back();
        str.pop_back();

        str.push_back(unite(s, t));
    }

    cout << "! " << str[0] << endl;

}

