inline string merge (string a, string b) {
	int i = 0, j = 0, la = a.size(), lb = b.size();
	string res = string (); 
	while (i < la && j < lb) {
		string tmp = res + a[i];
		for (int k = j; k < lb; ++k) tmp += b[k];
		res += (ask (tmp) + tmp.size() == len) ? a[i++] : b[j++];
	} while (i < la) res += a[i++]; while (j < lb) res += b[j++];
	return res;
}
