{
    if ('a' <= c && c <= 'z')
        return c - 'a';
    if ('A' <= c && c <= 'Z')
        return c - 'A' + 26;
    return c - '0' + 26 * 2;
}

int qry(string s)
{
    cout << "? " << s << endl;
    int ans;
    cin >> ans;
    return ans;
}

const int N = 10;
int n;
const int m = 4;

bool issub(string s)
{
    return (qry(s) == n - s.size());
}

int q[m];

string rec(int l, int r)
{
    if (l == r)
    {
        string s = "";
        for (int i = 0; i < q[l]; ++i)
            s += itoc(l);
        return s;
    }
    int m = (l + r) / 2;
    string a = rec(l, m);
    string b = rec(m + 1, r);
    string s = "";
    while (!a.empty() && !b.empty())
    {
        if (issub(s + a[0] + b))
        {
            s += a[0];
            a.erase(a.begin());
        }
        else
        {
            s += b[0];
            b.erase(b.begin());
        }
    }
    s += a;
    s += b;
    return s;
}

void solv()
{
    for (int i = 0; i < m; ++i)
    {
        string s = "";
        for (int j = 0; j < N; ++j)
            s += itoc(i);
        q[i] = N - qry(s);
    }
    for (int i = 0; i < m; ++i)
        n += q[i];
    string ans = rec(0, m - 1);
    assert(qry(ans) == 0);
    cout << "! " << ans << endl;
}

