		int cnt = maxn - ask(buf);
		if(!cnt)
			continue;
		pL[tot] = tot ? pR[tot - 1] + 1 : 0;
		pR[tot] = pL[tot] + cnt - 1;
		for(int i = pL[tot]; i <= pR[tot]; ++i)
			out[i] = ch;
		++tot;
		sum += cnt;
	}
	for(char ch = 'A'; sum < maxn && ch <= 'Z'; ++ch) {
		for(int i = 0; i < maxn; ++i)
			buf[i] = ch;
