		sum += cnt;
	}
	for(char ch = '0'; sum < maxn && ch <= '9'; ++ch) {
		for(int i = 0; i < maxn; ++i)
			buf[i] = ch;
		buf[maxn] = '\0';
		int cnt = maxn - ask(buf);
		if(!cnt)
			continue;
		pL[tot] = tot ? pR[tot - 1] + 1 : 0;
		pR[tot] = pL[tot] + cnt - 1;
		for(int i = pL[tot]; i <= pR[tot]; ++i)
			out[i] = ch;
		++tot;
		sum += cnt;
	}
	assert(pR[tot - 1] == maxn - 1);
	solve(0, tot - 1);
	out[maxn] = '\0';
	close(out);
	return 0;
}

