        cnt[i] = 128 - query(string(128, resource[i]));
        len += cnt[i];
    }
    string result(len, '-');

    string invalid = getInvalidString(len);
    assert(query(invalid) == len);
    vector<int> ord(62);
    iota(ALL(ord), 0);
    sort(ALL(ord), [](int l, int r) { return cnt[l] < cnt[r]; });
    for (int i : ord) {
        stack<X> s;
        s.push(X(0, len, cnt[i]));
        while (s.size() > 0) {
            X cur = s.top();
            s.pop();
            if (cur.num == 0) continue;

            int rest = 0;
            for (int k : range(cur.l, cur.r)) {
                if (result[k] == '-') {
                    rest++;
                }
            }
            if (rest == cur.num) {
                for (int k : range(cur.l, cur.r)) {
                    if (result[k] == '-') {
                        result[k] = resource[i];
                    }
                }
                continue;
            }

            int m    = (cur.l + cur.r) / 2;
            string q = invalid;
            for (int k : range(cur.l, m)) {
                q[k] = resource[i];
            }
            int v = len - query(q);
            s.push(X(cur.l, m, v));
            s.push(X(m, cur.r, cur.num - v));
        }
    }
    if (query(result) != 0) {
        return -1;
    }
    return 0;
}

