	vector<int>num(256);
	for (auto i : box) {
		string s(1, i);
		num[i] = Ask(s);
	}

	int mx = 0, mn = MOD;
	for (auto i : box) {
		mx = max(mx, num[i]);
		mn = min(mn, num[i]);
	}
	if (mx == mn) {
		L = mx + 1;
	}
	else {
		L = mx;
	}
	for (auto i : box) {
		if (num[i] == mx) {
			num[i] = 0;
			continue;
		}
		string s(L, i);
		num[i] = L - Ask(s);
	}
	string ans(L, ' ');
	for (int i = 0; i < 62; i++) {
		for (int j = i + 1; j < 62; j++) {
			if (num[box[i]] > num[box[j]])swap(box[i], box[j]);
		}
	}
	char dummy = box[0];
	//for (auto i : box)cout << num[i] << endl;
