bool ok(const string& x)
{
	return s == SZ(x) + ask(x);
}

string go(int a, int b)
{
	if (b - a == 1)
		return pw(A[a], ile[A[a]]);
	int c = (a + b) / 2;
	string x = go(a, c), y = go(c, b), ret = "";
	int j = 0;

	FOR(i, 0, SZ(x))
	{
		if (j != SZ(y) and ok(ret + y[j] + x.substr(i, L)))
			ret += y[j];
		ret += x[i];
	}

	for (; j != SZ(y); j++)
		ret += y[j];

	return ret;
}

