inline void cal(char c,int l,int r,int tc){
	if(al==n||ed[l][r]||!tc)return;
	if(tc==r-l+1){ed[l][r]=1;for(int i=l;i<=r;++i)ans[i]=c;al+=tc;return;}
	const int mid=l+r>>1;
	if(ed[l][mid]){
		cal(c,mid+1,r,tc);
		ed[l][r]=ed[mid+1][r];
		return;
	}
	else if(ed[mid+1][r]){
		cal(c,l,mid,tc);
		ed[l][r]=ed[l][mid];
		return;
	}
	for(int i=1;i<=r;++i)s[i]='a';
	for(int i=l;i<=mid;++i)if(!ed[i][i])s[i]=c;
	int lc=m-getval(s,n);
	cal(c,l,mid,lc);cal(c,mid+1,r,tc-lc);
	if(ed[l][mid]&&ed[mid+1][r])ed[l][r]=1;
}
inline void dfs(int l,int r){
	if(l==r||ed[l][r])return;
	const int m=l+r>>1;
	dfs(l,m);dfs(m+1,r);
	if(ed[l][m]&&ed[m+1][r])ed[l][r]=1;
}
