int calcdist(const string& a, const string& b) {
	int alen = SZ(a), blen = SZ(b);
	vector<vector<int>> dp(alen + 1, vector<int>(blen + 1, INT_MAX));
	dp[0][0] = 0;
	REP(i, alen) REP(j, blen) if (dp[i][j] != INT_MAX) {
		if (i < alen) upd(dp[i + 1][j], dp[i][j] + 1);
		if (j < blen) upd(dp[i][j + 1], dp[i][j] + 1);
		if (i < alen && j < blen) upd(dp[i + 1][j + 1], dp[i][j] + (a[i] == b[j] ? 0 : 1));
	}
	return dp[alen][blen];
}

