		int ret; scanf("%d", &ret); return ret;
	} else {
		printf("%s\n", s.c_str());
		return calcdist(s, locans);
	}
}

void solve() {
	REP(i, NCHAR) cnt[i] = MAXLEN - query(string(MAXLEN, CHARS[i]));
	len = 0; REP(i, NCHAR) len += cnt[i];
	REP(j, len) ans[j] = '?'; ans[len] = '\0';
	int known = 0;
	REP(j, len) {
		string s(len, CHARS[1]); s[j] = CHARS[0];
		int cur = query(s);
		if (cur == len - cnt[1] - 1) ans[j] = CHARS[0], ++known;
	}
	FOR(i, 1, NCHAR) {
		REP(rep, cnt[i]) {
			vector<int> opt; REP(j, len) if (ans[j] == '?') opt.PB(j);
			int lo = 0, hi = SZ(opt);
			while (lo + 1 < hi) {
				int mi = lo + (hi - lo) / 2;
				string s(len, '?'); REP(j, len) s[j] = ans[j];
				REPSZ(k, opt) s[opt[k]] = k < mi ? CHARS[i] : CHARS[0];
				int cur = query(s);
				if (cur == len - known) lo = mi; else hi = mi;
			}
			int idx = opt[hi - 1];
			ans[idx] = CHARS[i], ++known;
		}
	}
}

void run() {
	solve();
	printf("! %s\n", ans); fflush(stdout);
}

void test() {
	local = true;
	cin >> locans;
	solve();
	printf("%s\n", ans);
}

int main() {
	run();
	//test();
	return 0;
}

