int try_s(std::string const& s) {
  int N = s.size();
  for(int i = 0; i < N; ++i) buf[i+1] = s[i];
  buf[N+1] = 0;
  return trybuf();
}

std::string merge(std::string const& s1, std::string s2) {
  int k = len - s1.size();
  std::string left = "", right = s1;
  int q = 0;
  while(right.size() > 0) {
    left += s2[q];
    int nk;
    while((nk = try_s(left + right)) < k) {
      if(q == s2.size()-1) return left+right;
      left += s2[++q];
      k = nk;
    }
    left.back() = right[0];
    right = right.substr(1);
  }
  return left + s2.substr(q);
}

std::vector<std::string> reduce(std::vector<std::string>const& v) {
  std::vector<std::string> res;
  for(int i = 0; i+1 < v.size(); i += 2) {
    res.push_back(merge(v[i], v[i+1]));
  }
  if(v.size()%2 == 1) res.push_back(v.back());
  return res;
}


