  dp[0][0] = 0;
  for (int i = 0; i <= a.size(); i++) {
    for (int j = 0; j <= b.size(); j++) {
      if (i > 0) 
        dp[i][j] = min(dp[i][j], dp[i - 1][j] + 1);

      if (j > 0) 
        dp[i][j] = min(dp[i][j], dp[i][j - 1] + 1);

      if (i > 0 && j > 0)
        dp[i][j] = min(dp[i][j], dp[i - 1][j - 1] + 1);

      if (i > 0 && j > 0 && a[i - 1] == b[j - 1])
        dp[i][j] = min(dp[i][j], dp[i - 1][j - 1]);
    }
  }


  return dp[a.size()][b.size()];
}

