int getnum(char c, int len) {
	int l = 0;
	int r = len;

	while (l != r) {
		int m = (l + r + 1) / 2;

		string s;

		for (int i = 0; i < m; i++) {
			s.push_back(c);
		}

		if (ask(s) == len - (int)s.size()) {
			l = m;
		}
		else {
			r = m - 1;
		}
	}

	return l;
}

