vector<int> all_diff, answer;

int divconq(vector<int> vert, int c, int sum = -1) {
	if(size(vert) == 0)
		return 0;
	vector<int> req = all_diff;
	for(int i : vert)
		req[i] = c;

	if(sum == -1)
		sum = ask(req);
	if(sum == 0)
		return sum;
	if(size(vert) == 1) {
		answer[vert[0]] = c;
		return sum;
	}
	vector<int> vert_l, vert_r;
	REP(i, size(vert))
		if(i % 2 == 0)
			vert_l.emplace_back(vert[i]);
		else
			vert_r.emplace_back(vert[i]);
	int left = divconq(vert_l, c);
	divconq(vert_r, c, sum - left);
	return sum;
}

