int len;

void findFreq() {
  for (int i = 0; i < sz(sig); i++)
    freq[i] = len - ask(string(len, sig[i]));
}

string merge(const string& s, const string& t) {
  if (!sz(s) || !sz(t)) return !sz(s) ? t : s;
  string ret = "";
  int i = 0, j = 0;
  while (i < sz(s) && j < sz(t)) {
    string x = ret + t[j] + s.substr(i, sz(s)-i);
    if (ask(x) == len - sz(x))
      ret.push_back(t[j]), j++;
    else
      ret.push_back(s[i]), i++;
  }
  if (i == sz(s))
    ret += t.substr(j, sz(t)-j);
  if (j == sz(t))
    ret += s.substr(i, sz(s)-i);
  return ret;
}

string merge(int l, int r) {
  int sm = 0;
  for (int i = l; i <= r; i++)
    sm += freq[i];
  if (!sm) return "";
  int nx = freq[l];
  for (int i = l+1; i <= r; i++) {
    if ((nx + freq[i]) * 2 > sm)
      return merge(merge(l, i-1), merge(i, r));
    nx += freq[i];
  }
  return string(freq[l], sig[l]);
}

