int edst(string s,string t){
	int n=s.size();
	int m=t.size();
	vv<int> dp(n+1,vector(m+1,(int)MOD)); dp[0][0]=0;
	rep(i,n+1)rep(j,m+1){
		if(i!=n) MN(dp[i+1][j],dp[i][j]+1);
		if(j!=m) MN(dp[i][j+1],dp[i][j]+1);
		if(i!=n && j!=m) MN(dp[i+1][j+1],dp[i][j]+(s[i]!=t[j]));
	}
	return dp[n][m];
}

