str merge(str S,str T)
{
	int lens=S.len;
	for(int i=1,las=0;i<=T.len;++i)
	{
		S.ins(T.s[i]);
		for(int j=S.len;j>las+1;--j)
			swap(S.s[j],S.s[j-1]);
		las++; int x=query(S);
		while(x!=lens+i)
		{
			swap(S.s[las],S.s[las+1]);
			++las,x=query(S);
		}
	}
	return S;
}
priority_queue<str>q;
signed main()
{
	for(int c='0';c<='1';++c)
	{
		str now;
		for(int i=1;i<=128;++i)
			now.ins(c);
		int match=query(now);
		if(!match) continue;
		str nx;
		for(int i=1;i<=match;++i)
			nx.ins(c);
		q.push(nx);
	}
	while(q.size()>1)
	{
		str fir=q.top(); q.pop();
		str sec=q.top(); q.pop();
		q.push(merge(fir,sec));
	}
	answer(q.top());
}
