const int maxLen = 850;

int total = 0;
vector<char> chars;
vector<string> parts;

int similarity(const string x) {
  return x.size() + total - ask(x);
}

string full(char c, int cnt) {
  string ans;
  ans.resize(cnt);
  for (int i = 0; i < cnt; i++) ans[i] = c;
  return ans;
}

bool cmp(string a, string b) {
  return a.size() > b.size();
}

string combine(const string le, const string ri, int l, int r) {
  string ans = "";

  for (int i = 0; i < l; i++) ans.pb(le[i]);
  for (int i = r; i >= 1; i--) ans.pb(ri[ri.size() - i]);

  return ans;
}

string merge(string le, string ri) {
  int l, r, pivot;
  string ans = "";

  l = 0;
  r = ri.size();
  pivot = similarity(combine(le, ri, l, r)); 

  while (l < le.size() || r > 0) {
    if (r == -1) break;

    if (l == le.size()) {
      ans.pb(ri[ri.size() - r]);
      r--;
      continue;
    }

    int aux = similarity(combine(le, ri, l + 1, r));
    if (pivot + 2 == aux) {
      ans.pb(le[l]);
      l++;
      pivot += 2;
    } else {
      ans.pb(ri[ri.size() - r]);
      r--;
      pivot -= 2;
    }
  }

  return ans;
}

int main()
{
  for (char c = 'a'; c <= 'z'; c++) chars.pb(c);
  for (char c = 'A'; c <= 'Z'; c++) chars.pb(c);
  for (char c = '0'; c <= '9'; c++) chars.pb(c);

  for (auto c: chars) {
    int cnt = maxLen - ask(full(c, maxLen));
    if (cnt == 0) continue;
    parts.pb(full(c, cnt));
    total += cnt;
  }

  while (parts.size() > 1) {
    sort(parts.begin(), parts.end(), cmp);
    string a = parts.back(); parts.pop_back();
    string b = parts.back(); parts.pop_back();
    parts.pb(merge(a, b));
  }

  cout << "! " << parts[0] << '\n';

  return 0;
}

