	if (b == (int)y.size()) {
		return dp[a][b] = (int)x.size() - a;
	}

	int res = go(a + 1, b);
	res = min(res, go(a, b + 1));

	if (x[a] != y[b]) {
		res = min(res, go(a + 1, b + 1));
	}

	res++;

	if (x[a] == y[b]) {
		res = min(res, go(a + 1, b + 1));
	}

	return dp[a][b] = res;
}

