	#endif
}

bool IsSubstr(string s) {
	return Ask(s) + SZ(s) == slen;
}

vector<string> merges;

void SortMerges() {
	sort(ALL(merges), [&](const string &lhs, const string &rhs) {
		return SZ(lhs) > SZ(rhs);
	});
}

int main() {
	#ifdef LOCAL
	cin >> hidden;
	#endif

	for (char ch = '0'; ch <= '9'; ++ch) { alpha += ch; }
	for (char ch = 'A'; ch <= 'Z'; ++ch) { alpha += ch; }
	for (char ch = 'a'; ch <= 'z'; ++ch) { alpha += ch; }
	cerr << alpha << "\n";

	const int A = SZ(alpha);

	vi ehh(A);
	for (int i = 0; i < A; ++i) {
		ehh[i] = Ask(string(2, alpha[i]));
	}

	int who_min = min_element(ALL(ehh)) - ehh.begin();
	int mindist = ehh[who_min];
	slen = mindist + 2;
	int pair_threshold = mindist;
	int dddd = Ask(string(1, alpha[who_min]));
	if (dddd == 0) {
		cout << "! " << alpha[who_min] << "\n";
		return 0;
	}
	if (dddd != slen - 1) {
		--slen;
		--pair_threshold;
	}

	debug() << imie(slen) << imie(mindist) << imie(pair_threshold);

	counts.resize(A);
	for (int i = 0; i < SZ(alpha); ++i) {
		char ch = alpha[i];
		if (ehh[i] == pair_threshold) {
			for (int len = 2; len <= slen; ++len) {
				if (IsSubstr(string(len, ch))) {
					counts[i] = len;
				} else {
					break;
				}
			}
		} else {
			if (IsSubstr(string(1, ch))) {
				counts[i] = 1;
			}
		}
	}

	for (int i = 0; i < A; ++i) {
		if (!counts[i]) { continue; }
		merges.push_back(string(counts[i], alpha[i]));
	}

	debug() << imie(merges);
	int maxqueries = nqueries;
	int incq = 0;
	cerr << nqueries << "\n";

	while (SZ(merges) > 1) {
		SortMerges();
		string a = merges.back();
		merges.pop_back();
		string b = merges.back();
		merges.pop_back();

		incq += SZ(a) + SZ(b) - 1;
		maxqueries += SZ(a) + SZ(b) - 1;

		//~ assert(maxqueries <= 850);

		string suf_a = a;
		string merged;
		for (char ch : b) {
			while (true) {
				if (suf_a.empty()) { break; }
				if (IsSubstr(merged + ch + suf_a)) {
					break;
				} else {
					assert(!suf_a.empty());
					merged += suf_a[0];
					suf_a.erase(suf_a.begin());
				}
			}
			merged += ch;
		}
		merged += suf_a;

		debug() << imie(a) << imie(b) << imie(merged) << imie(incq);
		merges.push_back(merged);
	}

	#ifdef LOCAL
	assert(Ask(merges[0]) == 0);
	#endif
	cout << "! " << merges[0] << endl;
	cerr << maxqueries << " " << incq << "\n";
	cerr << nqueries << "\n";
}

