				lesser[j][co++] += b4;
			}else{
				++ b4;
			}
		}
	}
	assert(co==62); 
	vector<pi> hmm;
	FOR(i,0,co-1) FOR(j,0,len[i]-1) lesser[i][j] += j, hmm.eb(lesser[i][j], i);
	string ans="";
