    while (true) {
      string s;
      int ld = Ask(s = a.substr(0, pos) + b[i] + a.substr(pos));
      pos++;
      if (ld == len - (int)a.size() - 1) {
        a = s;
        break;
      }
    }
  }
  return a;
}

