int dist(string a, string b) {
	if (mem_dist.count(mp(a, b))) return mem_dist[mp(a, b)];
	if (a.empty()) return le(b);
	if (b.empty()) return le(a);
	if (a[0] == b[0]) return dist(string(a.begin() + 1, a.end()), string(b.begin() + 1, b.end()));
