string merge(int l, int r) {
    if (l == r) return ss[l];
    int mid = (l + r) >> 1;
    string sl = merge(l, mid), sr = merge(mid + 1, r), s;
    for (int i = 0, j = 0, k = n - sl.size(); i <= (int)sl.size(); i++) {
        if (i == (int)sl.size()) {
            while (j < (int)sr.size()) s += sr[j++];
