string solve(int l, int r) {
    if (l == r) return string(ch[l], cnt[l]);
    int    mid = (l + r) >> 1;
    string a = solve(l, mid), b = solve(mid + 1, r), ret = "";
    int    n = a.size(), m = b.size();
    for (int i = 0, j = 0; i < n || j < m;) {
        if (i == n)
            ret += a[i];
        else if (j == m)
            ret += b[j];
        else {
            int v = ask(ret + b[j] + a.substr(i, n - i));
            if (v + n + j + 1 == len)
                ret += b[j++];
            else
                ret += a[i++];
        }
    }
    return ret;
}

