                       .count());
  constexpr int L = 128;
  constexpr auto comp = [&](const string& a, const string& b) {
    return a.size() > b.size();
  };
  priority_queue<string, vector<string>, decltype(comp)> pq(comp);
  auto ask = [](const string& s) {
    cout << "? " << s << endl;
    int dist;
    cin >> dist;
    return dist;
  };
  for (auto [start, end] : {pair{'a', 'z'}, {'A', 'Z'}, {'0', '9'}}) {
    for (char c = start; c <= end; ++c) {
      int dist = ask(string(L, c));
      if (L - dist > 0) {
        pq.emplace(L - dist, c);
      }
    }
  }
  while (pq.size() > 1) {
    string a = pq.top();
    pq.pop();
    string b = pq.top();
    pq.pop();
    for (int i = 0; !b.empty(); ++i) {
      a.insert(i, 1, b.front());
      int dist = ask(a);
      if (dist == L - (int)a.size()) {
        b.erase(0, 1);
      } else {
        a.erase(i, 1);
      }
    }
    pq.push(a);
  }
  cout << "! " << pq.top() << endl;
  return 0;
}

