int cnt;
struct Str{
	int len;
	char s[200];
	bool operator <(const Str &rhs)const{
		return len>rhs.len;
	}
}tmp;
char s[200];
priority_queue<Str>q;
void count(int lim,char ch){
	for(register int i=0;i<lim;i++){
		for(register int j=0;j<128;j++)s[j]=ch+i;
		printf("? %s\n",s);
		fflush(stdout);
		scanf("%d",&tmp.len);
		fflush(stdin);
		tmp.len=128-tmp.len;
		if(tmp.len){
			for(register int j=0;j<tmp.len;j++)tmp.s[j]=ch+i;
			q.push(tmp);
			//cout<<"q.push "<<tmp.len<<" "<<tmp.s<<endl;
		}
	}
}
void solve(){
	while(q.size()>1){
		Str s1=q.top();q.pop();
		Str s2=q.top();q.pop();
		//cout<<"s1:"<<s1.len<<" "<<s1.s<<endl;
		//cout<<"s2:"<<s2.len<<" "<<s2.s<<endl;
		for(register int i=0;i<s1.len;i++)s[i]=s1.s[i];
		s[s1.len]='\0';
		printf("? %s\n",s);
		fflush(stdout);
		int tot=0;
		scanf("%d",&tot);
		fflush(stdin);
		int i=0,j=0,k=0;
		while(i<s1.len&&j<s2.len){
			s[k]=s2.s[j];
			int now=k+1;
			for(register int l=i;l<s1.len;l++)s[now++]=s1.s[l];
			s[now]='\0';
			printf("? %s\n",s);
			fflush(stdout);
			scanf("%d",&cnt);
			fflush(stdin);
			if(cnt<tot){
				tot=cnt;
				j++;
			}
			else{
				s[k]=s1.s[i];
				i++;
			}
			k++;
		}
		if(i>=s1.len)for(;j<s2.len;j++,k++)s[k]=s2.s[j];
		else for(;i<s1.len;i++,k++)s[k]=s1.s[i];
		tmp.len=k;
		for(i=0;i<k;i++)tmp.s[i]=s[i];
		q.push(tmp);
	}
}
int main(){
	count(3,'0');
	count(26,'a');
	count(26,'A');
	solve();
	tmp=q.top();
	for(register int i=0;i<tmp.len;i++)s[i]=tmp.s[i];
	s[tmp.len]='\0';
	printf("! %s\n",s);
	fflush(stdout);
	return 0;
}

