int dp[2][128];
int edit_distance(char const*s1, char const*s2) {
  int i, j;
  dp[0][0] = 0;
  for(i = 1; s1[i-1]; ++i) dp[0][i] = i;
  for(j = 1; s2[j-1]; ++j) {
    dp[j%2][0] = j;
    for(i = 1; s1[i-1]; ++i) {
      dp[j%2][i] = std::min(std::min(dp[(j-1)%2][i], dp[j%2][i-1]) + 1,
        dp[(j-1)%2][i-1] + (s1[i-1] == s2[j-1]? 0: 1));
    }
  }
  return dp[(j-1)%2][i-1];
}


