char decode(int x){return x<=26?64+x:(x<=52?96-26+x:48+x-52-1);}
bool ask(int u,int i,int j)
{
  int len=diff;
  printf("? ");rep(k,s[u].size()){len--;printf("%c",decode(s[u][k]));}len--;printf("%c",decode(s[u<<1][i]));
  rep(k,s[u<<1|1].size()-j){len--;printf("%c",decode(s[u<<1|1][k+j]));}puts("");fflush(stdout);
  int res;if(scanf("%d",&res)!=0)return res==len;else return -1;
}
void solve(int u,int le,int ri)
{
  if(le==ri){s[u]=apr[le];return;}
  int mid=(le+ri)>>1;
  solve(u<<1,le,mid);solve(u<<1|1,mid+1,ri);
  for(int i=0,j=0;i<(int)s[u<<1].size()||j<(int)s[u<<1|1].size();)
  {
    if(i<(int)s[u<<1].size()&&(j==(int)s[u<<1|1].size()||ask(u,i,j))){s[u].push_back(s[u<<1][i]); i++;}
    else{s[u].push_back(s[u<<1|1][j]);j++;}
  }
}
