				int lnum = Ask(s);
				for (int j = 0; j < L; j++) {
					if (s[j] == dummy&&ans[j] != s[j])lnum--;
				}
				int nnum = cnxl.r - cnxl.l + sndnxl.r - sndnxl.l - lnum;
				if (cr.num + sndr.num == nnum) {
					cnxl.num = cr.num;
					sndnxl.num = sndr.num;
					Q.push(cnxl);
					Q.push(sndnxl);
				}
				else if (nnum == 0) {
					cnxr.num = cr.num;
					sndnxr.num = sndr.num;
					Q.push(cnxr);
					Q.push(sndnxr);
				}
				else {
					string t(L, dummy);
					for (int j = cnxl.l; j < cnxl.r; j++)t[j] = i;
					for (int j = sndnxr.l; j < sndnxr.r; j++)t[j] = i;
					int rnum = Ask(t);
					for (int j = 0; j < L; j++) {
						if (t[j] == dummy && ans[j] != t[j])rnum--;
					}
					int mnum = cnxl.r - cnxl.l + sndnxr.r - sndnxr.l - rnum;
					int rl=0, rr=0;
					if (nnum < mnum)rr = mnum - nnum;
					else rl = nnum - mnum;
					int add = sndr.num - (rr + rl);
					rr += add / 2, rl += add / 2;
					sndnxl.num = rl, sndnxr.num = rr;
					int ll = nnum - rl;
					int lr = cr.num - ll;
					cnxl.num = ll, cnxr.num = lr;
					Q.push(cnxl);
					Q.push(sndnxl);
					Q.push(cnxr);
					Q.push(sndnxr);
				}
				ed = true;
				break;
			}
			if (ed)continue;
			Range cnxl(cr.l, (cr.l + cr.r) / 2, 0);
			Range cnxr((cr.l + cr.r) / 2, cr.r, 0);
