ll dist(const string& a, const string& b) {
    vv(ll,cost,a.size()+1,b.size()+1,LINF);
    cost[0][0]=0;
    rep(a.size()+1)rep(j,b.size()+1){
        if(i<a.size())chmin(cost[i+1][j],cost[i][j]+1);
        if(j<b.size())chmin(cost[i][j+1],cost[i][j]+1);
        if(i<a.size()&&j<b.size())chmin(cost[i+1][j+1],cost[i][j]+(a[i]!=b[j]));
    }
    return cost.back().back();
}

