string merge(string s, string t){
    string ans=s;
    ll at=0;
    each(i,t){
        while(at<ans.size()){
            ans.insert(ans.begin()+at,i);
            ll q=query(ans);
            if(q+ans.size()==l){
                at++;
                goto br;
            }
            else{
                ans.erase(ans.begin()+at);
                at++;
            }
        }
        ans.push_back(i);
        at++;
    br:;
    }
    return ans;
}
