int edst(string s,string t){
	int n=s.size();
	int m=t.size();
	vv<int> dp(n+1,vector(m+1,0));
	rep(i,n+1)rep(j,m+1){
		if(i!=n) MX(dp[i+1][j],dp[i][j]);
		if(j!=m) MX(dp[i][j+1],dp[i][j]);
		if(i!=n && j!=m && s[i]==t[j]) MX(dp[i+1][j+1],dp[i][j]+1);
	}
	return dp[n][m];
}

