const int MAX = 100001;

vector<vector<int>> graph(MAX);

bool mark[MAX];
int t_in[MAX], t_out[MAX], up[21][MAX], dist[MAX];
int timer = 0, n, m;
int root;

void dfs(int v, int p, int K) {
    if (mark[v]) return;
    mark[v] = true;
    t_in[v] = timer; timer++;
    up[0][v] = p;
    for (int i = 1; i <= K; ++i) //у динамики новоселье
        up[i][v] = up[i - 1][up[i - 1][v]];
    for(auto x : graph[v]) {
        if (!mark[x])
            dfs(x, v, K);
    }
    t_out[v] = timer; timer++;
}

bool isAncestor (int a, int b) {
    return t_in[a] <= t_in[b] && t_out[b] <= t_out[a];
}

int LCA(int a, int b, int K) {
    for (int k = K - 1; k >= 0; k--)
        if (!isAncestor(up[k][a], b))
            a = up[k][a];
    return isAncestor(a, b) ? a : up[0][a];
}

