struct X {
    int l, r, num;
    X() {}
    X(int _l, int _r, int _num) {
        l   = _l;
        r   = _r;
        num = _num;
    }
};

string getInvalidString(int n) {
    string ret(n, '-');
    int min_i = distance(cnt, min_element(cnt, cnt + 62));
    string q(n, resource[(min_i + 1) % 62]);
    int def = n - query(q);
    for (int i : range(n)) {
        string s    = q;
        s[i]        = resource[min_i];
        int matched = n - query(s);
        if (matched > def) {
            ret[i] = q[i];
        }
        else {
            ret[i] = s[i];
        }
    }
    return ret;
