char base_c = 0;
int base;
int known[128];
string ans_s;

int len = 0;
void sol(char c) {
  assert(cnt[c] > 0);
  dump("sol", c, cnt[c]);
  while(cnt[c] > 0) {
    int unkonwn_total = 0;
    for(int i = 0; i < len; i++) {
      unkonwn_total += !known[i];
    }
    int ok = unkonwn_total;
    int ng = 0;
    while(ok - ng > 1) {
      int mid = (ok + ng) / 2;
      int done = 0;
      string t(len, base_c);
      for(int i = 0; i < len; i++) {
        if(!known[i]) {
          if(done < mid) {
            done++;
            t[i] = c;
          }
        } else {
          t[i] = ans_s[i];
        }
      }
      int diff = ask(t) - base;
      dump(diff);
      assert(diff <= 0);
      if(diff <= -1) ok = mid; else ng = mid;
    }

    int ok_i = -1;
    int un_c = 0;
    for(int i = 0; i < len; i++) {
      if(!known[i]) {
        un_c++;
        if(un_c == ok) {
          ok_i = i;
          break;
        }
      }
    }
    assert(ok_i >= 0 && ok_i < len);
    dump(ok_i);
    known[ok_i] = 1;
    ans_s[ok_i] = c;
    base--;
    cnt[c]--;
  }
}

int main() {
  sort(chars.begin(), chars.end());
  chars.erase(unique(chars.begin(), chars.end()), chars.end());
  assert(chars.size() == 26 + 26 + 10);
  // 62times ; 788 times left
  for(auto c: chars) {
    cnt[c] = 128 - ask(string(128, c));
    len += cnt[c];
  }

  int c1 = cnext(0);
  int c1c = cnt[chars[c1]];
  assert(c1c > 0);
  if(c1c == len) {
    ans(string(len, chars[c1]));
  }

  dump(len, c1);

  int c2 = cnext(c1+1);
  int c2c = cnt[chars[c2]];
  assert(c2c > 0);

  dump(c2);

  char zeroc = 0;
  for(auto c: chars) {
    if(cnt[c] == 0) zeroc = c;
  }

  if(zeroc == 0) {
    char t1 = 0, t2 = 0;
    for(auto c: chars) {
      if(t2 == 0 || cnt[t2] > cnt[c]) t2 = t1, t1 = c;
      if(t1 != 0 && t2 != 0 && cnt[t1] > cnt[t2]) swap(t1, t2);
    }

    assert(t1 != 0 && t2 != 0);
    assert(cnt[t1] < 3 && cnt[t2] < 3);

    c1c = cnt[t1];
    c2c = cnt[t2];

    string t = string(len, t1);
    random_device rnd;
    mt19937 mt(rnd());
    uniform_int_distribution<ll> rd(0, ll(-1));
    int last = 0;
    int base0 = len;

    int Z = c1c + c2c;
    while(last != -Z) {
      for(int i = 0; i < len; i++) {
        t[i]=(rd(mt)%2==0)?t1:t2;
      }
      last = ask(t) - base0;
      dump(last);
      if(last == Z) {
        last = -Z;
        swap(t1, t2);
        for(auto&e:t) if(e == t1) e = t2; else e = t1;
      }
    }

    for(int i = 0; i < len; i++) if(t[i] == t1) known[i] = 1;
    base_c = t1;
    base = len - c1c;
    ans_s = string(len, t1);
    dump(ask(string(len, t1)), len);

    sol(t2);

    for(int i = 0; i < len; i++) if(t[i] == t1) known[i] = 0;

    base_c = t2;
    base += c2c;
    dump("no zeroc");
  } else {
