string solve(string cs){
	if(cs.size()==1){
		int t=ask(string(L,cs[0]));
		// out(cs,t,1);
		return string(t,cs[0]);
	}
	int n=cs.size();
	string A=solve(cs.substr(0,n/2));
	string B=solve(cs.substr(n/2));
	string re=A;
	rrep(i,A.size()){
		while(B.size()){
			string s=re.substr(0,i+1)+B.back()+re.substr(i+1);
			if(ask(s)!=(int)s.size()) break;
			B.pop_back();
			re=s;
		}
	}
	re=B+re;
	// out(cs,re,1);
	return re;
}

