vector<string> strs;

string merge(int l, int r) {
	if (l == r) {
		return strs[l];
	}
	int mid = (l + r) >> 1;
	string sl = merge(l, mid);
	string sr = merge(mid + 1, r);
	string cur = "";
	int should = query(sl);
	int pr = 0, _pr = (signed) sr.size();
	for (int i = 0; i < (signed) sl.size(); i++) {
		while (pr < _pr && query(cur + sr[pr] + sl.substr(i)) == should - 1) {
			cur += sr[pr++];
			should--;
		}
		cur += sl[i];
	}
	while (pr < _pr) {
		cur += sr[pr++];
	}
	return cur;
}

