void Cut(ll L, ll R){
    ll MID=(L+R)/2;
    ll m=61;
    vec Search;
    rep(i,62) {
        if(SUM[i][R]==SUM[i][L]){
            REP(j,L+1,R) SUM[i][j]=SUM[i][R];
            m=i; 
        }
        else Search.pb(i);
    }
    if(Search.size()==1){
        REP(j,L,R) ans[j]=JUN[Search[0]];
        return;
    }
    if(Search.size()<62){
        ll X=SUM[m][N]-SUM[m][L];
        ll CC=MID-L;
        REP(j,1,Search.size()){
            ll A=Search[j];
            string ret;
            rep(k,N) {
                if(k<MID) ret.pb(JUN[A]);
                else ret.pb(JUN[m]);
            }
            ll Y=Query(ret);
            SUM[A][MID]=Y-X;
            CC-=(SUM[A][MID]-SUM[A][L]);
        }
        SUM[Search[0]][MID]=SUM[Search[0]][L]+CC;
        Cut(L,MID);
        Cut(MID,R);
        return;
    }

    ll Sum=FREQ[61];
    rep(j,61){
        string ret;
        rep(k,N){
