	ll n=x.size(), m=y.size();
	vector<vector<ll>> dp(n+1, vector<ll>(m+1,LLINF));
	dp[n][m]=0;
	FOR(i,0,n-1) dp[i][m]=n-i;
	FOR(j,0,m-1) dp[n][j]=m-j;
	DEC(i,n-1,0) DEC(j,m-1,0) {
		if(x[i] == y[j]) {
			dp[i][j]=dp[i+1][j+1];
		}else{
