}

void answer(string str){
    cout << "! " << str << endl;
    exit(0);
}

int query2(char c, int cnt){
    if(cnt == 0)return 0;
    string tmp = "";
    for(int i = 0;i < ans_str.size();i++){
        if(ans_str[i] == c || ans_str[i] == 0){
            cnt--;
        }
        tmp.push_back(c);
        if(cnt == 0)break;
    }
    return query(tmp);
}

void set_char(char c, int pos){
    for(int i = 0;i < ans_str.size();i++){
        if(ans_str[i] == c || ans_str[i] == 0)pos--;
        if(pos == 0){
            ans_str[i] = c;

//            cout << i << "xx " << c << endl;
            return;
        }
    }
}

int main(){
    int l = 0;
    set<int> cnts;
    for(auto c:chars){
        string all_c(128, c);
        cnt[c] = query(all_c);
        l += cnt[c];
    }
    int unknown = l;
    ans_str.resize(l);
    for(auto c:chars){
        int bottom = 0;
        for(int i = 0;i < cnt[c];i++){
            int top = unknown;
            while(top - bottom > 1){
                int mid = (top + bottom) / 2;
                if(query2(c, mid) == i)bottom = mid;
                else top = mid;
            }
            set_char(c, top);
            bottom = top;
        }
        return 0;
        unknown -= cnt[c];
    }
    string S(ans_str.begin(), ans_str.end());
    answer(S);
    return 0;
}

