bool check(string s){
    int ans = ask(s);
    if(ans+(int)s.size()==L) return true;
    return false;
}
struct node{
    string s;
    bool friend operator < (const node &p1,const node &p2){
        return p1.s.size()<p2.s.size();
    }
};
node merge(node a,node b){
    string s = a.s;
    int pos = 0;
    for(char c: b.s){
        while(1){
            string t = s.substr(0,pos) + c + s.substr(pos);
            pos++;
            if(check(t)){
                s = t;
                break;
            }
        }
    }
    return (node){s};
}
