    for (int i = 0, j = 0, k = n - sl.size(); i <= (int)sl.size(); i++) {
        if (i == (int)sl.size()) {
            while (j < (int)sr.size()) s += sr[j++];
            break;
        }
        while (j < (int)sr.size() && ask(s + sr[j] + sl.substr(i)) == k - 1)
            s += sr[j++], --k;
        s += sl[i];
    }
    return s;
}

