bool solve2(ll n, string s) { //条件判定
    if (query(s) == n - (ll)s.size()) return true; //ここに条件を入れる
    else return false;
}


vector<char> c;
void solve(){
    vector<ll> cnt(62);
    string ans;
    queue<char> q;
    ll n = 0;
    REP(i, 62){
        string now;
        REP(j, 128)now.push_back(c[i]);
        ll res = 128 - query(now);
        cnt[i] = res;
        n += res;
        REP(j, res) q.push(c[i]);
    }
    while(!q.empty()){//128
        ll anssize = ans.size();
        char add = q.front();
        q.pop();
        //nibutan
        ll ng = (ll)ans.size() + 1; //最大値ならs.size()
        ll ok = 0; // 最大値なら0
        while (abs(ok - ng) > 1) {//7
            ll mid = (ok + ng) / 2;
            string addstr;
            FOR(i, mid, ans.size()){//128
                if (ans[i] == add) addstr.push_back(add);
            }
            if (solve2(n, ans.substr(0, mid) + addstr + add)) ok = mid;//128^2
            else ng = mid;
        }
        ans = ans.substr(0, ok) + add + ans.substr(ok, anssize - ok);
    }
    cout << "! " << ans << endl;
}
