string merge(int a, int b)
{
	string ret = "";
	int ca = 0, cb = 0;
	for (int i = 0; i < str[a].size() + str[b].size(); i++)
	{
		if (ca < str[a].size())
		{
			ret += str[a][ca];
			int tmp = ask(ret);
			if (tmp < len - i || cb >= str[b].size()) ca++;
			else
			{
				ret[ret.size() - 1] = str[b][cb];
				cb++;
			}
		}
		else
		{
			ret += str[b][cb];
			cb++;
		}
	}
	return ret;
}

#define lch(x) (x << 1)
#define rch(x) (x << 1 | 1)

void build(int l, int r, int o)
{
	if (l == r)
	{
		str[o] = ss[l];
		return;
	}
	int mid = l + r >> 1;
	build(l, mid, lch(o));
	build(mid + 1, r, rch(o));
	str[o] = merge(lch(o), rch(o));
}

