void solve(int l,int r)
{
  int mid=(l+r)/2,sum=0,num=0,j=-1,letter[sz],len=0,rem[761]={0};
  if(r-l==1)
  {
    rep(i,sz)if(edit[i][r]!=edit[i][l]){pw[l]=charaset[i];return;}
  }
  rep(i,sz)
  {
    if(edit[i][l]==edit[i][r])
    {
      edit[i][mid]=edit[i][l];
      sum-=edit[i][l];
      j=i;
    }
    else{rem[len++]=i;}
  }
  tmp=(char*)realloc(word,sizeof(int)*N);
  if(!tmp){free(word);err(EXIT_FAILURE,"fault");}
  word=tmp;
  rep(i,N)word[i]=charaset[0];
  if(j<0)
  {
    rep(i,len)
    {
      if(!rem[i])continue;
      rep(k,mid)word[k]=charaset[rem[i]];
      letter[rem[i]]=query(word)-N+edit[0][N];
      sum+=letter[rem[i]];
      num++;
    }
    assert((mid+sum)%(num+1)==0);
    int ret=(mid+sum)/(num+1);
    edit[0][mid]=edit[0][0]+ret;
    rep(i,sz-1)
    {
      if(edit[i+1][l]==edit[i+1][r]){continue;}
      edit[i+1][mid]=edit[i+1][0]-letter[i+1]+ret;
    }
  }
  else
  {
    sum+=edit[j][l];
    rep(i,len)
    {
      if(rem[i]==rem[len-1])
      {
        letter[rem[i]]=(len+1)*edit[j][mid]-sum-mid;
        continue;
      }
      rep(k,N)word[k]=charaset[j];
      rep(k,mid)word[k]=charaset[rem[i]];
      letter[rem[i]]=query(word)-N+edit[j][N];
      sum+=letter[rem[i]];
    }
    rep(i,len){edit[rem[i]][mid]=edit[rem[i]][0]-letter[rem[i]]+edit[j][mid];}
  }
  solve(l,mid);
  solve(mid,r);
}
