    int  mid = (l + r) >> 1;
    auto a   = solve(l, mid);
    auto b   = solve(mid + 1, r);
    if (a.size() == 0)
        return b;
    else if (b.size() == 0)
        return a;
    int    n = a.size(), m = b.size();
    string ret = "";
