int n,cnt[62];
const char alphabet[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
int qry(char s[])
{
  printf("%s%s\n","? ",s);
  int v=0;if(~scanf("%d",&v))return v;else return -1;
}
int subsequence(char s[]){return strlen(s)+qry(s)==n;}
char* combine(char a[],char b[])
{
  char *ret="-";int i=0,j=0,s1=strlen(a),s2=strlen(b);
  if(!s1||!s2)return strcat(a,b);
  for(;i<s1||j<s2;)
  {
    char *str="-";strcpy(str,a);memmove(str+i+2,b+j,s2-j);
    if(i<s1&&(j==s2||subsequence(str)))ret=strcat(ret,a[i++]);
    else ret=strcat(ret,b[j++]);
  }
  return ret;
}
char* solve(int l,int r)
{
  if(l==r){char str[cnt[l]];memset(str,alphabet[l],sizeof(str));return str;}
  int mid=(l+r)>>1;
  return combine(solve(l,mid),solve(mid+1,r));
}
int main()
{
  for(int i=0;i<62;i++){char str[128];memset(str,alphabet[i],sizeof(str));cnt[i]=128-qry(str),n+=cnt[i];}
  char *ans=solve(0,61);
  return printf("%s%s\n","! ",ans),0;
}

