int LevenshteinDistance(const std::string& s, const std::string& t) {
	std::vector<std::vector<int>> d(s.size() + 1, std::vector<int>(t.size() + 1, 0));
	for (int i = 0; i <= s.size(); ++i) d[i][0] = i;
	for (int j = 0; j <= t.size(); ++j) d[0][j] = j;
	for (int i = 1; i <= s.size(); ++i) {
		for (int j = 1; j <= t.size(); ++j) {
			int cost = (s[i - 1] == t[j - 1]) ? 0 : 1; // 置換コスト
			d[i][j] = std::min({ d[i - 1][j - 0] + 1, // 挿入コスト
								 d[i - 0][j - 1] + 1, // 削除コスト
								 d[i - 1][j - 1] + cost });
		}
	}
	return d[s.size()][t.size()];
}

struct BIT {
	int N;
	using TYPE = int;
	std::vector<TYPE> bit;
	BIT() : N(0) {}
	BIT(int n) : N(n), bit(N + 1, 0) {}
	BIT(int n, TYPE init) : N(n), bit(N + 1, init) {}

	// bit[i] += w;
	void add(int i, TYPE w) {
		for (int x = ++i; x <= N; x += x & -x) bit[x] += w;
	}
	// return sum [0, i);
	TYPE sum(int i) {
		TYPE res = 0;
		for (int x = i; x > 0; x -= x & -x) res += bit[x];
		return res;
	}
	// return sum [i, j);
	TYPE sum(int i, int j) {
		return sum(j) - sum(i);
	}
	const TYPE& operator[](const int& i) const {
		return bit[i];
	}
};

