std::string ch;
std::string ans;
const int sz = 62;
int cnta;
int L, n;
BIT bit;

void update(int i, char c) {
	ans[i] = c;
	bit.add(i, -1);
}

void rec(int l, int r, V<int> cnt) {
	if (n <= l) return;
	int len = r - l;
	V<int> p;
	REP(i, sz) if (cnt[i]) p.emplace_back(i);
	if (p.empty()) return;
	if (p.size() == 1) {
		FOR(i, l, r) {
			update(i, ch[p[0]]);
		}
		return;
	}
	if (len == 2) {
		std::string ts = std::string(l, 'a') + (char)(ch[p[0]]) + (char)(ch[p[1]]) + std::string(std::max(0, n - l - 2), 'a');
		ts.resize(n);
		int t = n - query(ts);
		if (cnta < t) {
			update(l, ch[p[0]]);
			update(l + 1, ch[p[1]]);
		}
		else {
			update(l, ch[p[1]]);
			update(l + 1, ch[p[0]]);
		}
		return;
	}
	V<int> cntl(sz, 0);
	int sum = 0;
	REP(i, p.size()) {
		std::string ts = std::string(l, 'a') + std::string(len / 2, ch[p[i]]) + std::string(std::max(0, n - l - len / 2), 'a');
		ts.resize(n);
		cntl[p[i]] = n - query(ts);
		sum += cntl[p[i]];
	}
	sum -= cnta * p.size();
	sum -= len / 2;
	int parta = -sum / (p.size() - 1);
	REP(i, p.size()) {
		cntl[p[i]] = cntl[p[i]] - cnta + parta;
	}
	rec(l, l + len / 2, cntl);
	REP(i, sz) cnt[i] -= cntl[i];
	rec(l + len / 2, r, cnt);
}


signed main() {
	INIT;

#ifdef DEBUG
	trues = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
#endif

	FOR(c, 'a', 'z' + 1) ch += (char)c;
	FOR(c, 'A', 'Z' + 1) ch += (char)c;
	FOR(c, '0', '9' + 1) ch += (char)c;

	L = 128;
	n = [&] {
		cnta = L - query(std::string(L, 'a'));
		int re = query(std::string(cnta, 'a'));
		return cnta + re;
	}();
	ans.resize(n, ' ');

	while (n <= L) L /= 2;
	if (L == 0) {
		for (auto c : ch) {
			if (query(std::string(1, c)) == 0) end(std::string(1, c));
		}
	}
	else L *= 2;

	bit = BIT(L);
	REP(i, n) bit.add(i, 1);

	V<int> cnt(sz, 0);
	REP(i, sz) {
		char c = ch[i];
		cnt[i] = n - query(std::string(n, c));
	}

	rec(0, L, cnt);

	end(ans);

	return 0;
}

