        dif[i] = query(vector<char>(1, vc[i]));
    }
    int m = *min_element(dif.begin(), dif.end());
    int M = *max_element(dif.begin(), dif.end());
    int L = (m < M ? M : M+1);
    auto cmp = [](const vector<char>& a, const vector<char>& b){ return a.size() > b.size(); };
    priority_queue<vector<char>, vector<vector<char>>, decltype(cmp)> qu(cmp);
    for(int i=0;i<vc.size();i++){
        if(dif[i] == L) continue;
        vector<char> cur(1, vc[i]);
        int pre = dif[i];
        while(true){
            cur.push_back(vc[i]);
            int q = query(cur);
            if(q >= pre) break;
            pre = q;
        }
        cur.pop_back();
        qu.push(cur);
    }
    while(qu.size() >= 2){
        auto a = qu.top(); qu.pop();
        auto b = qu.top(); qu.pop();
        int idx = 0;
        int cur = L - a.size();
        for(int i=0;i<b.size();i++){
