inline int ask(const string &s)
{
	cout<<"? "<<s<<endl;
	fflush(stdout);
	int res;
	scanf("%d",&res);
	return res;
}

inline void answer(const string &s)
{
	cout<<"! "<<s<<endl;
	fflush(stdout);
}

int beg;
string solve(string &s,string &t)
{
	string res(128, 'a');
	int lst = beg, len = 0;

	int i=0, j=0;
	while(i<(int)s.size() && j<(int)t.size())
	{
		if(s[i]=='a')
		{
			res[len] = t[j];
			int now = ask(res);
			if(now>=lst)
				res[len] = s[i++], lst = ask(res);
			else ++j, lst = now;
		}
		else
		{
			res[len] = s[i];
			int now = ask(res);
			if(now>=lst)
				res[len] = t[j++], lst = ask(res);
			else ++i, lst = now; 
		}
		++len;
	}
	while(i<(int)s.size()) res[len++] = s[i++];
	while(j<(int)t.size()) res[len++] = t[j++];

	res.resize(len);
	return res;
}

