int main(void)
{	
	for(char i='a'; i<='z'; ++i)
	{
		string t(128,i);
		s.push_back(string(128-ask(t), i));
	}
	for(char i='A'; i<='Z'; ++i)
	{
		string t(128,i);
		s.push_back(string(128-ask(t), i));
	}
	for(char i='0'; i<='9'; ++i)
	{
		string t(128,i);
		s.push_back(string(128-ask(t), i));
	}

	beg = 128 - s[0].size();
	while((int)s.size() > 1)
	{
		int mx = 0;
		for(int i=0; i<(int)s.size(); ++i)
			if(s[i].size() > s[mx].size())
				mx = i;
		swap(s[mx], s.back());

		vector<string> t;
		for(int i=0; i<(int)s.size(); i+=2)
			t.push_back(solve(s[i], s[i+1]));
		if(s.size()%2) t.push_back(s.back());

		s=t;
	}
	answer(s[0]);
	return 0;
}

