inline int getval(int id,int len){
	putchar('?');putchar(' ');
	for(int i=1;i<=len;++i)putchar(s[id][i]);puts("");
	fflush(stdout);
	int x;scanf("%d",&x);return x;
}
inline void solve(int g,int l,int r){
	if(l==r){
		for(int i=1;i<=tl[l];++i)s[g][i]=se[l];
		len[g]=tl[l];
		return;
	}
	int lc=g<<1,rc=g<<1|1,mid=l+r>>1;
	solve(lc,l,mid);solve(rc,mid+1,r);
	if(!len[lc]&&!len[rc])return;
	len[g]=len[lc]+len[rc];
	for(int i=1,j=1,k=1;i<=len[g];++i){
		if(j>len[lc]){s[g][i]=s[rc][k];++k;}
		else if(k>len[rc]){s[g][i]=s[lc][j];++j;}
		else{
			s[g][i]=s[rc][k];
			for(int o=j,p=i+1;o<=len[lc];++o,++p)s[g][p]=s[lc][o];
			if(n-getval(g,i+len[lc]-j+1)!=i+len[lc]-j+1)s[g][i]=s[lc][j],++j;
			else ++k;
		}
	}
}
