	if(!ls.size()) return rs;
	if(!rs.size()) return ls;
	int now=0,all=ls.size();
	vector<int> nw;
	while(now<rs.size()&&ask(nw=getv(ls,0,rs[now]))==all+1) ls=nw,all++,now++;
