int query(string s) {
    assert(1 <= s.size() && s.size() <= 128);
    assert(memo.size() <= 849);
    if (memo.count(s)) return memo[s];

    int u;
    if (expect == "") {
        cout << "? " << s << endl;
        cin >> u;
    } else {
        int ln = int(expect.size());
        int rn = int(s.size());
        VV<int> dp(ln + 1, V<int>(rn + 1, TEN(9)));
        for (int i = 0; i <= ln; i++) {
            dp[i][0] = i;
        }
        for (int i = 0; i <= rn; i++) {
            dp[0][i] = i;
        }
        for (int i = 1; i <= ln; i++) {
            for (int j = 1; j <= rn; j++) {
                dp[i][j] = min(dp[i][j], dp[i - 1][j] + 1);
                dp[i][j] = min(dp[i][j], dp[i][j - 1] + 1);
                dp[i][j] = min(dp[i][j], dp[i - 1][j - 1] + (expect[i - 1] == s[j - 1] ? 0 : 1));
            }
        }
        u = dp[ln][rn];
    }

    if (u == 0) {
        answer(s);
    }
    return memo[s] = u;
}








