int q[m];

string rec(int l, int r)
{
    if (l == r)
    {
        string s = "";
        for (int i = 0; i < q[l]; ++i)
            s += itoc(l);
        return s;
    }
    int m = (l + r) / 2;
    string a = rec(l, m);
    string b = rec(m + 1, r);
    string s = "";
    while (!a.empty() && !b.empty())
    {
        if (issub(s + a[0] + b))
        {
            s += a[0];
            a.erase(a.begin());
        }
        else
        {
            s += b[0];
            b.erase(b.begin());
        }
    }
    s += a;
    s += b;
    return s;
}

