{
    for (int i = 0; i < m; ++i)
    {
        string s = "";
        for (int j = 0; j < N; ++j)
            s += itoc(i);
        q[i] = N - qry(s);
    }
    for (int i = 0; i < m; ++i)
        n += q[i];
    string ans = rec(0, m - 1);
    cout << "! " << ans << endl;
}

