	string C = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
	int N = 62, L = 0;
	vector<int> ans_single(N);
	for(int i = 0; i < N; i++)
		ans_single[i] = ask(C.substr(i, 1));
	L = 130;
	for(int i = 0; i < N; i++) L = min(L, ans_single[i]+1);
	vector<int> cnt(N, 0);
	for(int i = 0; i < N; i++) if(L == ans_single[i]+1) cnt[i] = 1;
	int last = N-1;
	while(cnt[last] == 0) last--;
	cnt[last] = L;
	for(int i = 0; i < last; i++) if(cnt[i]) {
		string s;
		s += C[i];
		while(true) {
			s += C[i];
			int a = ask(s);
			if(a == L-cnt[i]-1) cnt[i]++;
			else break;
		}
		cnt[last] -= cnt[i];
	}
	vector< pair<int, string> > parts;
	for(int i = 0; i < N; i++) if(cnt[i]) {
		string s;
		for(int j = 0; j < cnt[i]; j++) s += C[i];
		parts.push_back({cnt[i], s});
