string qry(int l, int r)
{
    if (l == r)
    {
        string s = "";
        for (int i = 0; i < q[l]; ++i)
            s += itoc(i);
        return s;
    }
    int m = (l + r) / 2;
    string a = qry(l, m);
    string b = qry(m + 1, r);
    string s = "";
    int i = 0, j = 0;
    while (i + j < a.size() + b.size())
    {
        if (i == a.size())
        {
            s += b[j++];
            continue;
        }
        if (j == b.size())
        {
            s += a[i++];
            continue;
        }
        if (qry(s + a[i]) == n - (s.size() + 1))
            s += a[i++];
        else
            s += b[j++];
    }
    return s;
}

