const int L = 128;
const int N_CHARS = 62;
const string CHARS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

int LEN;

int query(string str) {
    cout << "? " << str << endl;
    int result;
    cin >> result;
    return result;
}

string interleave(string a, string b) {
    int n = int(a.size()), m = int(b.size());
    string result;
    int i = 0, j = 0;

    while (i < n && j < m) {
        string candidate = result;
        candidate += b[j];
        candidate += a.substr(i);

        if (query(candidate) == LEN - int(candidate.size()))
            result += b[j++];
        else
            result += a[i++];
    }

    while (i < n)
        result += a[i++];

    while (j < m)
        result += b[j++];

    return result;
}

int main() {
    ios::sync_with_stdio(false);

    assert(int(CHARS.size()) == N_CHARS);
    vector<string> strings;
    LEN = 0;

    for (int c = 0; c < N_CHARS; c++) {
        int freq = L - query(string(L, CHARS[c]));
        LEN += freq;

        if (freq > 0)
            strings.emplace_back(freq, CHARS[c]);
    }

    while (strings.size() > 1) {
        sort(strings.begin(), strings.end(), [](const string &x, const string &y) {
            return x.size() > y.size();
        });
        string a = strings.back(); strings.pop_back();
        string b = strings.back(); strings.pop_back();
        strings.push_back(interleave(a, b));
    }

    cout << "! " << strings.front() << endl;
}

