string solve(int l,int r) {
	if(l==r) {
		string ret;
		for(int i=0;i<cnt[l];i++) ret+=c[l];
		return ret;
	}
	int mid=(l+r)>>1;
	string ls=solve(l,mid),rs=solve(mid+1,r);
	int p1=0,p2=0;
	string ret;
	while(p1<sz(ls)&&p2<sz(rs)) {
		string s=ret+ls[p1]+rs[p2];
