  }

  return ans;
}

int n;
string merge (const string &s, const string &t) {
  vector<int> blocks ((int) s.size() + 1, 0);

  int len = s.size();
  for (int i = 0; i <= (int) s.size(); i++) {
    while (true) {
      blocks[i]++;
      len++;
      if (len > (int) t.size() + (int) s.size()) {
        blocks[i]--;
        len--;
        break;
      }
      int cur = query(build(s, t, blocks));
      if (cur != n - len) {
        blocks[i]--;
        len--;
        break;
      }
    }
  }
  return build(s, t, blocks);
}

