string rec(int l, int r)
{
    if (l == r)
    {
        string s = "";
        for (int i = 0; i < q[l]; ++i)
            s += itoc(l);
        return s;
    }
    int m = (l + r) / 2;
    string a = rec(l, m);
    string b = rec(m + 1, r);
    string s = "";
    int i = 0, j = 0;
    while (i + j < a.size() + b.size())
    {
        if (i == a.size())
