template<class T> inline bool UpdateMin(T& a, T b) {
  if (a > b) { a = b; return 1; } return 0;
}

template<class T> inline bool UpdateMax(T& a, T b) {
  if (a < b) { a = b; return 1; } return 0;
}

int EditDistance(const string& s, const string& t) {
  int n = s.length();
  int m = t.length();
  vector<vector<int>> dp(n + 1, vector<int>(m + 1, 1E9));
  for (int i = 0; i <= n; i++) {
    for (int j = 0; j <= m; j++) {
      if (i == 0 && j == 0) {dp[i][j] = 0; }
      else if (i == 0) { dp[i][j] = j; }
      else if (j == 0) { dp[i][j] = i; }
      else if (s[i - 1] == t[j - 1]) { dp[i][j] = dp[i - 1][j - 1]; }
      else {
        UpdateMin(dp[i][j], dp[i - 1][j - 1] + 1);
        UpdateMin(dp[i][j], dp[i - 1][j] + 1);
        UpdateMin(dp[i][j], dp[i][j - 1] + 1);
      } 
    }
  }
  return dp[n][m];
}

