vector<int> solve(int l,int r){
	if(l==r){
		vector<int> ret(0);
		for(int i=1;i<=cnt[l];i++) ret.pb(l);
		return ret;
	}
	int mid=(l+r)/2;
	vector<int> ls=solve(l,mid),rs=solve(mid+1,r);
	if(!ls.size()) return rs;
	if(!rs.size()) return ls;
	int now=0,all=ls.size();
	vector<int> nw;
	while(now<rs.size()&&ask(nw=getv(ls,0,rs[now]))==all+1) ls=nw,all++,now++;
	for(int i=0;i<ls.size()-1;i++)
		while(now<rs.size()&&ask(nw=getv(ls,i+1,rs[now]))==all+1) ls=nw,all++,now++;
	while(now<rs.size()) ls.pb(rs[now]),now++;
	return ls;
}

