		merges.pop_back();
		string b = merges.back();
		merges.pop_back();

		incq += SZ(a) + SZ(b) - 1;
		maxqueries += SZ(a) + SZ(b) - 1;

		string suf_a = a;
		string merged;
		for (char ch : b) {
			while (true) {
				if (suf_a.empty()) { break; }
				if (IsSubstr(merged + ch + suf_a)) {
					break;
				} else {
					assert(!suf_a.empty());
					merged += suf_a[0];
					suf_a.erase(suf_a.begin());
				}
			}
			merged += ch;
		}
		merged += suf_a;

		debug() << imie(a) << imie(b) << imie(merged) << imie(incq);
		merges.push_back(merged);
	}

	cout << "! " << merges[0] << endl;
	cerr << maxqueries << "\n";
	cerr << nqueries << "\n";
}

