	FOR(i, 0, 26)
		A.pb('a' + i);
	FOR(i, 0, 26)
		A.pb('A' + i);

	for (char c : A)
		ile[c] = L - ask(pw(c, L)), s += ile[c];

	assert(s <= L);

	ans(go(0, SZ(A)));
}

