            int ok = left, ng = ans.length() + 1;
            while (ng - ok > 1){
                int md = (ok + ng) / 2;
                string s = ans.substr(0, md) + string(1, letters[i]);
                int c = ask(s);
                if (c + s.length() == len) ok = md;
                else ng = md;
            }
            ans = ans.substr(0, ok) + string(1, letters[i]) + ans.substr(ok);
            left = ok;
        }
    }
    answer(ans);

    return 0;
}

