void hoge(int cur) {
	char tar=C[cur];
	int lef=num[cur];
	vector<int> cand(ret.size()+1,0);
	int start=0;
	while(start<cand.size() && lef) {
		//cerr<<cur<<" "<<start<<" "<<lef<<" "<<tar<<" "<<ret.size()<<endl;
		int mi=cand.size()-start;
		int i,j;
		for(i=10;i>=0;i--) if(mi>1<<i) {
			vector<int> A(ret.size()+1,0);
			for(j=start;j<start+(mi-(1<<i));j++) A[j]=1;
			string T;
			FOR(j,ret.size()) {
				if(A[j]) T+=tar;
				T+=ret[j];
			}
			int r=ask(hoge(ret,A,tar));
			if(r<L-ret.size()+(mi-(1<<i))) mi-=1<<i;
		}
		//cerr<<"mi"<<mi<<endl;
		start+=mi-1;
		int now=0;
		for(i=10;i>=0;i--) if(now+(1<<i)<=lef) {
			vector<int> A(ret.size()+1,0);
			A[start]=now+(1<<i);
			int r=ask(hoge(ret,A,tar));
			if(r==L-ret.size()-(now+(1<<i))) now+=1<<i;

		}
		cand[start]=now;
		start++;
		lef-=now;
	}

	ret=hoge(ret,cand,tar);
	//cerr<<"!!"<<ret<<" "<<tar<<endl;
}

