const int maxl = 128;
string subs[64];
int len;

// solve [l, r)
string dfs(int l, int r) {
    if (r - l == 1) {
        return subs[l];
    }
    int m = (l + r) / 2;
    string A = dfs(l, m);
    string B = dfs(m, r);
    int ap = 0, bp = 0;
    string cur;

    while (ap < A.size() || bp < B.size()) {
        if (ap < A.size()) {
            string cand = cur + A[ap] + B.substr(bp);
            if (ask(cand) == len - cand.size()) {
                cur.pb(A[ap++]);
                continue;
            }
        }
        cur.pb(B[bp++]);
    }
    return cur;
}

