int tot;
priority_queue<pair<int, string>> pq;
void prec(char c) {
	string s(L, c);
	int len = L - query(s);
	if(len > 0) {
		s.resize(len);
		tot += len;
		pq.emplace(len, s);
	}
}

void merge(string a, string b) {
	if(a.size() < b.size()) swap(a, b);

	for(int i = (int)a.size(); i >= 0 and !b.empty(); i--) {
		while(!b.empty()) {
			string tmp = a.substr(0, i) + b.back();
			if(i < (int)a.size()) tmp += a.substr(i);
			if(query(tmp) == tot - (int)tmp.size()) {
				a = tmp;
				b.pop_back();
			}
			else break;
		}
	}
	pq.emplace((int)a.size(), a);
}

