	for(char c = '0'; c <= '9'; c++) prec(c);

	while(pq.size() > 1) {
		string a = pq.top().second; pq.pop();
		string b = pq.top().second; pq.pop();
		merge(a, b);
	}

	printf("%s\n", pq.top().second.c_str());
	fflush(stdout);
}

