vector<char> merge(vector<char> &A,vector<char> &B)
{
	vector<char> ret;ret.clear();
	vector<char> ask;
	int n=SZ(A),m=SZ(B),i=0,j=0;
	for(;i<n&&j<m;)
	{
		ask.clear();
		for(auto p:ret)ask.emplace_back(p);
		ask.emplace_back(A[i]);
		for(int k=j;k<m;k++)ask.emplace_back(B[k]);
		int len=query(ask);
		if(n-len==SZ(ret)+m-j+1)ret.emplace_back(A[i++]);
		else ret.emplace_back(B[j++]);
	}
	for(;i<n;i++)ret.emplace_back(A[i]);
	for(;j<m;j++)ret.emplace_back(B[j]);
	return ret;
}
