  for (int i = 0; i < l; i++) ans.pb(le[i]);
  for (int i = r; i >= 1; i--) ans.pb(ri[ri.size() - i]);

  return ans;
}

string merge(string le, string ri) {
  int l, r, pivot;
  string ans = "";

  l = 0;
  r = ri.size();
  pivot = similarity(combine(le, ri, l, r)); 

  while (l < le.size() || r > 0) {
    if (r == -1) break;

    if (l == le.size()) {
      ans.pb(ri[ri.size() - r]);
      r--;
      continue;
    }

    int aux = similarity(combine(le, ri, l + 1, r));
    if (pivot + 2 == aux) {
      ans.pb(le[l]);
      l++;
      pivot += 2;
    } else {
      ans.pb(ri[ri.size() - r]);
      r--;
      pivot -= 2;
    }
  }

  return ans;
}

