string merge(string s, string t) {
  string ans;
  int cur = query(t.c_str());
  while (s.size() && t.size()) {
    string here = ans + s[0] + t;
    int qhere = query(here.c_str());
    if (qhere < cur) cur = qhere, ans += s[0], s = s.substr(1);
    else ans += t[0], t = t.substr(1);
  }
  return ans + s + t;
}

