	vector<int>num(256);
	for (auto i : box) {
		string s(1, i);
		num[i] = Ask(s);
	}

	int mx = 0, mn = MOD;
	for (auto i : box) {
		mx = max(mx, num[i]);
		mn = min(mn, num[i]);
	}
	if (mx == mn) {
		L = mx + 1;
	}
	else {
		L = mx;
	}
	for (auto i : box) {
		string s(L, i);
		num[i] = L - Ask(s);
		break;
	}

	string ans(L, ' ');
	char dummy = 'a';
	if (num['a']) {
		vector<int>bag(L);
		mn = MOD;
		for (int i = 0; i < L; i++) {
			string s(L, 'b');
			s[i] = 'a';
			bag[i] = Ask(s);
			mn = min(mn, bag[i]);
		}
		for (int i = 0; i < L; i++) {
			if (mn == bag[i]) {
				ans[i] = 'a';
			}
		}
	}
	for (auto i : box) {
		if (i == dummy)continue;
		string st(L, i);
		num[i] = L - Ask(st);
		queue<Range>Q;
		Q.push(Range(0, L, num[i]));
		while (!Q.empty()) {
			auto cr = Q.front();
	//		cout << i << " fst " << cr.l << " " << cr.r << " " << cr.num << endl;
			Q.pop();
			if (cr.num == 0)continue;
			if (cr.l >= cr.r)continue;
			int space = 0;
			for (int j = cr.l; j < cr.r; j++) {
				if (ans[j] == ' ')space++;
			}
			if (cr.num == space) {
				for (int j = cr.l; j < cr.r; j++) {
					if (ans[j] == ' ')ans[j] = i;
				}
				continue;
			}
			bool ed = false;
			while (!Q.empty()) {
			//	break;
				auto sndr = Q.front();
			//	cout << i << " snd " << sndr.l << " " << sndr.r << " " << sndr.num << endl;
				Q.pop();
				if (sndr.num == 0)continue;
				int sndspace = 0;
				for (int j = sndr.l; j < sndr.r; j++) {
					if (ans[j] == ' ')sndspace++;
				}
				if (sndr.num == sndspace) {
					for (int j = sndr.l; j < sndr.r; j++) {
						if (ans[j] == ' ')ans[j] = i;
					}
					continue;
				}
				Range cnxl(cr.l, (cr.l + cr.r) / 2, 0);
				Range cnxr((cr.l + cr.r) / 2, cr.r, 0);
				Range sndnxl(sndr.l, (sndr.l + sndr.r) / 2, 0);
				Range sndnxr((sndr.l + sndr.r) / 2, sndr.r, 0);
				string s(L, dummy);
				for (int j = cnxl.l; j < cnxl.r; j++)s[j] = i;
				for (int j = sndnxl.l; j < sndnxl.r; j++)s[j] = i;
				for (int j = 0; j < L; j++) {
					if (ans[j] != ' ')s[j] = ans[j];
				}
				int lnum = Ask(s);
				for (int j = 0; j < L; j++) {
					if (s[j] != i&&ans[j] != s[j])lnum--;
				}
				int nnum = cnxl.r - cnxl.l + sndnxl.r - sndnxl.l - lnum;
				for (int j = cnxl.l; j < cnxl.r; j++)nnum -= s[j] == ans[j];
				for (int j = sndnxl.l; j < sndnxl.r; j++)nnum -= s[j] == ans[j];
			//	int nnum = sndnxl.r - sndnxl.l - lnum;

				if (cr.num + sndr.num == nnum) {
					cnxl.num = cr.num;
					sndnxl.num = sndr.num;
					Q.push(cnxl);
					Q.push(sndnxl);
				}
				else if (nnum == 0) {
					cnxr.num = cr.num;
					sndnxr.num = sndr.num;
					Q.push(cnxr);
					Q.push(sndnxr);
				}
				else {
					string t(L, dummy);
					for (int j = cnxl.l; j < cnxl.r; j++)t[j] = i;
					for (int j = 0; j < L; j++) {
						if (ans[j] != ' ')t[j] = ans[j];
					}
					int rnum = Ask(t);
					for (int j = 0; j < L; j++) {
						if (t[j] != i && ans[j] != t[j])rnum--;
					}
					int mnum = cnxl.r - cnxl.l  - rnum;
					for (int j = cnxl.l; j < cnxl.r; j++)mnum -= t[j] == ans[j];
					int ll = mnum, lr = cr.num - ll, rl = nnum-mnum , rr = sndr.num - rl;
					sndnxl.num = rl, sndnxr.num = rr;
					cnxl.num = ll, cnxr.num = lr;
					Q.push(cnxl);
					Q.push(cnxr);
					Q.push(sndnxl);
					Q.push(sndnxr);
				}
				ed = true;
				break;
			}
			if (ed)continue;
			Range cnxl(cr.l, (cr.l + cr.r) / 2, 0);
			Range cnxr((cr.l + cr.r) / 2, cr.r, 0);
			string s(L, dummy);
			for (int j = cnxl.l; j < cnxl.r; j++)s[j] = i;
			for (int j = 0; j < L; j++) {
				if (ans[j] != ' ')s[j] = ans[j];
			}
			int lnum = Ask(s);
			for (int j = 0; j < L; j++) {
				if (s[j] != i&&ans[j] != s[j])lnum--;
			}
			cnxl.num = cnxl.r - cnxl.l - lnum;
			for (int j = cnxl.l; j < cnxl.r; j++)cnxl.num -= s[j] == ans[j];
			cnxr.num = cr.num - cnxl.num;
		//	cout << cnxl.num << " " << cnxr.num << endl;
			Q.push(cnxl);
			Q.push(cnxr);
		}
	}
	cout << "! " << ans << endl;
	if(DEBUG)cout << cnt << endl;
}

