int main(){
	cin.tie(0);cout.tie(0);ios::sync_with_stdio(false);

	ll L = 128;
	string index = "";
	for(char c = 'a';c <= 'z';c++)index += c;
	for(char c = 'A';c <= 'Z';c++)index += c;
	for(char c = '0';c <= '9';c++)index += c;

	priority_queue<P, vector<P>, greater<> > pq;
	ll string_length = 0;
	REP(i, index.size()){
		ll num = L - query(string(L, index[i]));
		pq.push(MP(num, string(num, index[i])));
		string_length += num;
	}

	while(pq.size() > 1){
		auto a = pq.top();pq.pop();
		auto b = pq.top();pq.pop();

		string now = a.SE;
		ll pla = 0;
		ll cou = 0;

		while(cou < b.FI){
			string tmp = now;
			tmp.insert(pla, 1, b.SE[cou]);
			ll ret = query(tmp);
			if(ret == string_length - tmp.size()){
				now = tmp;
				cou++;
			}
			pla++;
		}
		pq.push(MP(now.size(), now));
	}

	cout << "! " << pq.top().SE << endl;
	//cout << "query " << query_cou << endl;

	return 0;
}

