int num['z'+1][129][129];

int main() {
  std::cin.tie(0); std::ios::sync_with_stdio(false);
  buf[0] = '?';
  buf[129] = 0;
  len = 0;
  std::vector<char> v;
  for(char c: ch) if(c != 0) {
    for(int i = 0; i <= 128; ++i) std::fill_n(num[c][i], 129, 0);
    for(int j = 0; j < 128; ++j) buf[j+1] = c;
    int l = 128 - trybuf();
    len += l;
    if(l > 0) { 
      v.push_back(c);
      num[c][0][128] = l;
    }
  }
  if(len < 128) for(char c: v) num[c][0][len] = num[c][0][128];
  buf[len+1] = 0;
  for(int w = 128; w > 1; w/= 2) if(w/2 < len) {
    if(w >= len) {
      int m = w/2;
      int sum = 0;
      for(int i = 1; i < v.size(); ++i) {
        int k = len - try_anb(v[0], m, v[i]) - num[v[i]][0][len];
        num[v[i]][0][m] = -k;
        sum -= k;
      }
      assert( (m-sum)%v.size() == 0);
      int na = (m-sum)/v.size();
      for(char c: v) { 
        num[c][0][m] += na;
        num[c][m][len] = num[c][0][len] -  num[c][0][m];
      }
    } else {
      int m = w/2;
      for(int l = 0; l+m < len; l += w) {
        int ww = std::min(w, len-l);
        std::vector<char> vv;
        for(char c: v) if(num[c][l][l+ww] > 0) vv.push_back(c);
        int sum = 0;
        for(int i = 1; i < vv.size(); ++i) {
          int k = len - try_anb(vv[0], l+m, vv[i]) - num[vv[0]][0][l] - num[vv[i]][l+ww][len];
          k = num[vv[i]][l][l+ww] - k;
          num[vv[i]][l][l+m] = k;
          sum += k;
        }
        assert( (m-sum)%vv.size() == 0);
        int na = (m-sum)/vv.size();
        for(char c: vv) {
          num[c][l][l+m] += na;
          num[c][l+m][l+ww] = num[c][l][l+ww] - num[c][l][l+m];
          num[c][0][l+m] = num[c][0][l] + num[c][l][m];
          num[c][l+m][len] = num[c][l+m][l+ww] + num[c][l+ww][len];
        }
      }
    }
  }
  for(int i = 0; i < len; ++i) {
    for(char c: v) if(num[c][i][i+1] > 0) {
      buf[i+1] = c; break;
    }
  }
  trybuf();

  return 0;
}

