int main() {
	for (int i = 0; i < 62; i++) {
		C[i] = 128 - QUERY(string(128, L[i]));
	}
	int length = 0;
	for (int i = 0; i < 62; i++) {
		length += C[i];
	}
	res = string(length, '#');
	for (int i = 0; i < length; i++) {
		string K = string(length, L[1]);
		K[i] = L[0];
		if (QUERY(K) < QUERY(string(length, L[1]))) {
			res[i] = L[0];
		}
		else if (QUERY(K) > QUERY(string(length, L[1]))) {
			res[i] = L[1];
		}
	}
	for (int i = 2; i < 62; i++) {
		for (int j = 0; j < C[i]; j++) {
			int l = 0, r = length;
			while (l + 1!= r) {
				int m = (l + r) / 2;
				string P, Q;
				P = Q = res;
				for (int k = 0; k < m; k++) {
					if (P[k] == '#')P[k] = L[i];
				}
				for (int k = 0; k < length; k++) {
					if (P[k] == '#')P[k] = L[0];
					if (Q[k] == '#')Q[k] = L[0];
				}
				if (QUERY(P) < QUERY(Q)) {
					r = m;
				}
				else {
					l = m;
				}
			}
			res[l] = L[i];
		}
	}
	cout << "! " << res << endl;
}

