string Merge(string A,string B){
	string cur;
	int j=0;
	if (B=="") return A;
	for (int i=0;i<A.size();i++){
		while (j<B.size()){
			string tt=cur;
			tt+=B[j];
			for (int k=i;k<A.size();k++){
				tt+=A[k];
			}
			if (ask(tt)==len-tt.size()){
				cur+=B[j];
				j++;
			}
			else{
				break;
			}
		}
		cur+=A[i];
	}
	while (j<B.size()){
		cur+=B[j];j++;
	}
	return cur;
