string Solve(int l,int r){
	string cur;
	while (!cnt[l] && l<=r) l++;
	if (l>r) return cur;
	if (l==r){
		for (int i=0;i<cnt[l];i++){
			cur+=c[l];
		}
		return cur;
	}
	int tot=0;
	for (int i=l;i<=r;i++) tot+=cnt[i];
	int cc=0,mid;
	for (int i=l;i<=r;i++){
		cc+=cnt[i];
		if (cc*2>=tot){
			mid=i;
			break;
		}
	} 
	string A=Solve(l,mid);
	string B=Solve(mid+1,r);
	return Merge(A,B);
}
