string getInvalidString(int n) {
    vector<int> ord(62);
    iota(ALL(ord), 0);
    sort(ALL(ord), [](int l, int r) { return cnt[l] < cnt[r]; });
    string q(n, resource[ord[0]]);
    if (cnt[ord[0]] == 0) {
        return q;
    }
    int def = cnt[ord[0]];
    for (int i : range(n)) {
        auto s      = q;
        q[i]        = resource[ord[2]];
        int matched = n - query(s);
        if (matched < def) {
            fix.emplace_back(i, resource[ord[0]]);
            cerr << "fixed: " << i << endl;
        }
    }
    return q;
}
int main() {
    init();
    /* write here */

    // 文字数特定 62クエリ
    for (int i : range(62)) {
        cnt[i] = 128 - query(string(128, resource[i]));
        len += cnt[i];
    }
    string result(len, '-');

    string invalid = getInvalidString(len);
    cerr << "times=" << times << endl;
    cerr << "len=" << len << endl;
    assert(query(invalid) == len - (int)fix.size());
    vector<int> ord(62);
    iota(ALL(ord), 0);
    sort(ALL(ord), [](int l, int r) { return cnt[l] < cnt[r]; });
    for (auto &it : fix) result[it.first] = it.second;
    for (int i : ord) {
        stack<X> s;
        if (fix.size() > 0 && resource[i] == fix[0].second) continue;
        s.push(X(0, len, cnt[i]));
        while (s.size() > 0) {
            X cur = s.top();
            s.pop();
            if (cur.num == 0) continue;

            int rest = 0;
            for (int k : range(cur.l, cur.r)) {
                if (result[k] == '-') {
                    rest++;
                }
            }
            if (rest == cur.num) {
                for (int k : range(cur.l, cur.r)) {
                    if (result[k] == '-') {
                        result[k] = resource[i];
                    }
                }
                continue;
            }

            int m    = (cur.l + cur.r) / 2;
            string q = invalid;
            for (int k : range(cur.l, m)) {
                q[k] = resource[i];
            }
            for (auto &it : fix) q[it.first] = it.second;
            int v = len - query(q) - (int)fix.size();
            s.push(X(cur.l, m, v));
            s.push(X(m, cur.r, cur.num - v));
        }
    }
    query(result);
    return 0;
}

