	int mx = 0, mn = MOD;
	for (auto i : box) {
		mx = max(mx, num[i]);
		mn = min(mn, num[i]);
	}
	if (mx == mn) {
		L = mx + 1;
	}
	else {
		L = mx;
	}
	for (auto i : box) {
		if (num[i] == mx) {
			num[i] = 0;
			continue;
		}
		string s(L, i);
		num[i] = L - Ask(s);
	}
	string ans(L, ' ');
	for (int i = 0; i < 62; i++) {
		for (int j = i + 1; j < 62; j++) {
			if (num[box[i]] < num[box[j]])swap(box[i], box[j]);
		}
	}
	char dummy = box[0];
	//for (auto i : box)cout << num[i] << endl;
	if (num[box[0]]) {
		vector<int>bag(L);
		mn = MOD;
		for (int i = 0; i < L; i++) {
			string s;
			if (box[0] == 'a')s.resize(L, 'b');
			else s.resize(L, 'a');
			s[i] = box[0];
			bag[i] = Ask(s);
			mn = min(mn, bag[i]);
		}
		for (int i = 0; i < L; i++) {
			if (mn == bag[i]) {
				ans[i] = box[0];
			}
		}
	}
	for (auto i : box) {
		if (i == dummy)continue;
		queue<Range>Q;
		Q.push(Range(0, L, num[i]));
		while (!Q.empty()) {
			auto cr = Q.front();
			Q.pop();
			if (cr.num == 0)continue;
			if (cr.l >= cr.r)continue;
			int space = 0;
			for (int j = cr.l; j < cr.r; j++) {
				if (ans[j] == ' ')space++;
			}
			if (cr.num == space) {
				for (int j = cr.l; j < cr.r; j++) {
					if (ans[j] == ' ')ans[j] = i;
				}
				continue;
			}
			int mid = cr.l;
			int lspace = 0;
			for (int j = cr.l; j < cr.r; j++) {
				if (ans[j] == ' ')lspace++;
				if (space / 2 == lspace) {
					mid = j+1;
					break;
				}
			}
			Range cnxl(cr.l, mid, 0);
			Range cnxr(mid, cr.r, 0);
			string s(L, dummy);
			for (int j = cnxl.l; j < cnxl.r; j++)s[j] = i;
			for (int j = 0; j < L; j++) {
				if (ans[j] != ' ')s[j] = ans[j];
			}
			int lnum = L-Ask(s);
			cnxl.num = lnum;
			for (int j = 0; j < L; j++)cnxl.num -= s[j] == ans[j];
			cnxr.num = cr.num - cnxl.num;
			Q.push(cnxl);
			Q.push(cnxr);
		}
	}
	cout << "! " << ans << endl;
	if(DEBUG)cout << cnt << endl;
}

