int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cout << fixed << setprecision(10);
  for (int i = 0; i < 10; i++)
    c[i] = '0' + i;
  for (int i = 0; i < 26; i++)
    c[i + 10] = 'a' + i, c[i + 36] = 'A' + i;
  int ll = l, hl = 0;
  for (int i = 0; i < n; i++) {
    string s;
    s.push_back(c[i]);
    int cl = query(s);
    ll = min(ll, cl);
    hl = max(hl, cl);
  }
  if (ll == hl)
    l = ll + 1;
  else
    l = hl;
  for (int i = 0; i < n; i++) {
    vector<int> v;
    rep(v, i, l);
    nc[i] = l - query(v);
  }
  vector<int> res;
  for (int i = 0; i < n; i++) {
    if (!nc[i])
      continue;
    if (sz(res) == 0) {
      rep(res, i, nc[i]);
      continue;
    }
    vector<int> pos;
    int lp = sz(res);
    for (int j = 0; j < nc[i]; j++) {
      int lw = 0, hi = lp + 1;
      while (lw + 1 < hi) {
        int mid = (lw + hi) / 2;
        vector<int> qh;
        pre(res, qh, mid);
        rep(qh, i, j + 1);
        if (l - query(qh) == mid + j + 1)
          lw = mid;
        else
          hi = mid;
      }
      pos.push_back(lw);
      lp = lw;
    }
    for (int j : pos)
      res.insert(res.begin() + j, i);
  }
  answer(res);
}

