			} else r = m;
		}
		SL -= l;
		return string(l, c);
	} else {
		int m = (l + r) / 2;
		string A = go(l, m);
		string B = go(m, r);
		// reverse(A.begin(), A.end());
		// reverse(B.begin(), B.end());
		string C;
		while (!A.empty() && !B.empty()) {
			if (ask(C + A.substr(0, 1) + B) == L - le((C + A.substr(0, 1) + B))) {
				C += A[0];
				A.erase(A.begin());
			} else {
				C += B[0];
				B.erase(B.begin());
			}
		}
		C += A + B;
		// assert(ask(C) == L - le(C));
		return C;
	}
}
string merge(string A, string B) {
	string C;
	while (!A.empty() && !B.empty()) {
		if (ask(C + A.substr(0, 1) + B) == L - le((C + A.substr(0, 1) + B))) {
			C += A[0];
			A.erase(A.begin());
		} else {
			C += B[0];
			B.erase(B.begin());
		}
	}
	C += A + B;
	return C;
}
