#include <bits/stdc++.h>
using namespace std;

int N;
string alphabet;

void output(char msg, deque <char> d) {
	printf("%c ", msg);
	for (auto it : d)
		printf("%c" , it);
	puts("");
	fflush(stdout);
}

int ask(deque <char> d) {
	output('?', d);
	int dist;
	scanf("%d", &dist);
	return dist;
}

bool subsequence(deque <char> d) {
	return d.size() + ask(d) == N;		
}

void add_range(char l, char r) {
	for (char c = l; c <= r; c++)
		alphabet += c;
}

deque <char> multiple(int k, char c) {
	return deque <char> (k, c);
}

deque <char> solve(int lo, int hi) {
	if (hi - lo == 1) 
		return multiple(N - ask(multiple(N, alphabet[lo])), alphabet[lo]);
	int mid = (lo + hi) / 2;
	deque <char> lft = solve(lo, mid);
	deque <char> rig = solve(mid, hi);
	deque <char> sofar;
	while (!rig.empty()) {
		deque <char> tmp = sofar;
		tmp.push_back(rig.front());
		for (auto it : lft)
			tmp.push_back(it);
		if (lft.empty() || subsequence(tmp)) {
			sofar.push_back(rig.front());
			rig.pop_front();
		}
		else {
			sofar.push_back(lft.front());
			lft.pop_front();
		}
	}
	for (auto it : lft)
		sofar.push_back(it);
	return sofar;
}

void find_length() {
	N = 128;
	for (auto it : alphabet)
		N = min(N, ask({it}) + 1);
}

int main() {
	add_range('a', 'z');
	add_range('A', 'Z');
	add_range('0', '9');
	find_length(); 
	output('!', solve(0, alphabet.size()));
	return 0;
}

