    REP(i, s.length() + 1) REP(j, t.length() + 1) {
        if(j == 0) dp[i][j] = i;
        else if(i == 0) dp[i][j] = j;
        else {
            int cost = 1;
            if(s[i - 1] == t[j - 1]) cost = 0;
            dp[i][j] = min({dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + cost});
        }
    }
    return dp[(int)s.length()][(int)t.length()];
}

