    vector<int> dif(vc.size());
    for(int i=0;i<vc.size();i++){
        dif[i] = query(vector<char>(1, vc[i]));
    }
    int m = *min_element(dif.begin(), dif.end());
    int M = *max_element(dif.begin(), dif.end());
    int L = (m < M ? M : M+1);
    auto cmp = [](const vector<char>& a, const vector<char>& b){ return a.size() > b.size(); };
    priority_queue<vector<char>, vector<vector<char>>, decltype(cmp)> qu(cmp);
    for(int i=0;i<vc.size();i++){
        if(dif[i] == L) continue;
        vector<char> cur(1, vc[i]);
        int pre = dif[i];
        while(true){
            cur.push_back(vc[i]);
            int q = query(cur);
            if(q >= pre) break;
            pre = q;
        }
        cur.pop_back();
        qu.push(cur);
    }
    while(qu.size() >= 2){
        auto a = qu.top(); qu.pop();
        auto b = qu.top(); qu.pop();
        int idx = 0;
        int cur = L - a.size();
        for(int i=0;i<b.size();i++){
            a.push_back(b[i]);
            for(int j=a.size()-2;j>=idx;j--) swap(a[j], a[j+1]);
            while(true){
                int q = query(a);
                ++idx;
                if(q < cur){ cur = q; break; }
                swap(a[idx-1], a[idx]);
            }
        }
        qu.push(a);
    }
    auto res = qu.top();
    cout << "! ";
    for(auto& c : res) cout << char(c);
    cout << endl;
    cout.flush();
    if(is_debug){
        cout << query_cnt << endl;
        cout << ans << endl;
    }
}

