    // }
    REP(i,5) letters += i + '0';
    random_shuffle(ALL(letters));

    int n = letters.length(), ma = -1, len = -1;
    VI cnt(n, -1);
    REP(i,n){
        string s(1, letters[i]);
        int c = ask(s);
        if (ma == -1) ma = c;
        else if (c == ma + 1){
            ma = c;
            len = ma;
            cnt[i] = 0;
            REP(j,i) cnt[j] = 1;
            break;
        }else if (c == ma - 1){
            len = ma;
            cnt[i] = 1;
            REP(j,i) cnt[j] = 0;
            break;
        }
    }
    if (len == -1){
        len = ma + 1;
        REP(i,n) cnt[i] = 1;
    }
    int sum = 0;
    REP(i,n){
        if (cnt[i] == 0) continue;
        if (cnt[i] == -1) cnt[i] = 0;
        while (cnt[i] < L - sum){
            string s(cnt[i] + 1, letters[i]);
            int c = ask(s);
            if (c + cnt[i] + 1 > len) break;
            cnt[i]++;
