      return it->second;
    }

    cout << "? " + s << endl;

    int ld;
      cout << flush;
      cin >> ld;
    q++;
    return cache[s] = ld;
  }

  unordered_map<string, int> cache;

  int q = 0;
};

class Solver {
public:
  Solver(Judge &jd) : jd(jd) {

  }

  string Solve() {
    vector<string> ss;

    len = 0;
    F0R(i, chars.size()) {
      int charCnt = 128 - jd.Ask(string(128, chars[i]));

      ss.emplace_back(charCnt, chars[i]);

      len += charCnt;
    }

    while(ss.size() > 1) {
      sort(rng(ss), [](const string& l, const string& r) {
        return l.size() < r.size();
        });

      ss[1] = insert(ss[1], ss[0]);
      ss.erase(ss.begin());
    }

    return ss[0];
  }


private:
  string insert(string a, string b) {

    int pos = 0;
    F0R(i, b.size()) {

      while (true) {
        string s;
        int ld = jd.Ask(s = a.substr(0, pos) + b[i] + a.substr(pos));

        pos++;
        if (ld == len - a.size() - 1) {
          a = s;
          break;
        }
      }
    }

    return a;
  }

  int len;
  Judge& jd;
};


