struct node{
    string s;
    bool friend operator < (const node &p1,const node &p2){
        if(p1.s.size()!=p2.s.size()) return p1.s.size()<p2.s.size();
        else return p1.s<p2.s;
    }
};
node merge(node a,node b){
    string s = a.s;
    int pos = 0;
    for(char c: b.s){
        while(1){
            string t = s.substr(0,pos) + c + s.substr(pos);
            pos++;
            if(check(t)){
                s = t;
                break;
            }
        }
    }
    return (node){s};
}
