	{
		printf("? "); for(int i=1; i<=N; i++) {printf("%c",decode(le));} puts(""); fflush(stdout);
		int res; scanf("%d",&res);
		for(int i=1; i<=N-res; i++) {s[u].push_back(le);}
		return;
