	int mid = (le+ri)>>1;
	solve(u<<1,le,mid); solve(u<<1|1,mid+1,ri);
	for(int i=0,j=0; i<s[u<<1].size()||j<s[u<<1|1].size();)
	{
		if(i+1<s[u<<1].size()&&(j+1==s[u<<1|1].size()||ask(u,i,j))) {s[u].push_back(s[u<<1][i]); i++;}
		else {s[u].push_back(s[u<<1|1][j]); j++;}
	}
}

