inline std::string merge(std::string A, std::string B) {
  int i = 0, j = 0, sA = A.size(), sB = B.size();
  std::string str = "";
  while (i < sA && j < sB) {
    std::string tmp = str + A[i];
    for (int k = j; k < sB; ++k)
      tmp += B[k];
    int x = query(tmp);
    if (x + tmp.size() == len)
      str += A[i++];
    else
      str += B[j++];
  }
  while (i < sA) str += A[i++];
  while (j < sB) str += B[j++];
  return str;
}

