int med(string s) {
	static string t = "ACBBCBBBABBAACABBBAAAACBBAB";
//	static string t = "Atcod3rIsGreat";
	int n = s.size(), m = t.size();
	vector< vector<int> > f(n, vector<int>(m, n + m + 1));
	auto get = [&](int x, int y) {
		if(x == -1) return y + 1;
		else if(y == -1) return x + 1;
		else return f[x][y];
	};
	for(int i = 0; i < n; ++i)
