int ldist(string s1, string s2) {
  size_t j, k;
  size_t m;
  size_t len1 = s1.size();
  size_t len2 = s2.size();
  vector<vector<size_t>> d(len1+1, vector<size_t>(len2+1));
  for (j=0; j<=len1; j++) d[j][0] = j;
  for (k=0; k<=len2; k++) d[0][k] = k;

  for (j=1; j<=len1; j++) {
    for (k=1; k<=len2; k++) {
      m = min(d[j-1][k]+1, d[j][k-1]+1);
      d[j][k] = min(m, d[j-1][k-1]+((s1[j-1] == s2[k-1])?0:1));
    }
  }
  return d[len1][len2];
}

