string merge_query(string s, string t)
{
	int i = 0, j = 0;
	string ans;
	while (i<s.size()&&j<t.size())
	{
		string S = s.substr(0, i+1)+t.substr(j);
		if (query(S)==n-S.size())
		{
			ans.PB(s[i]);
			i++;
		}
		else
		{
			ans.PB(t[j]);
			j++;
		}
	}
	while (i<s.size()) ans.PB(s[i++]);
	while (j<t.size()) ans.PB(t[j++]);
	return ans;
}
