string solve(int l, int r){
    if(l == r){
        string s = "";
        char c = letters[l];
        for(int i=0; i<quant[l]; i++) s += c;
        return s;
    }else{
        string a = solve(l, (l+r)/2);
        string b = solve((l+r)/2+1, r);
        string c = "";
        unsigned int i=0, j=0;
        while(i < a.size() or j < b.size()){
            if(i == a.size()){
                c = c + b[j];
                j++;
            }else if(j == b.size()){
                c = c + a[i];
                i++;
            }else{
                string d = c + a[i] + b.substr(j);
                if(ask(d) > l - (int)d.size()){
                    c += b[j];
                    j++;
                }else{
                    c += a[i];
                    i++;
                }
            }
        }
        return c;
    }
}

