int med(string s) {
	static string t = "ACBBCBBBABBAACABBBAAA";
	int n = s.size(), m = t.size();
	vector< vector<int> > f(n, vector<int>(m, n + m + 1));
	auto get = [&](int x, int y) {
		if(x == -1) return y + 1;
		else if(y == -1) return x + 1;
		else return f[x][y];
	};
	for(int i = 0; i < n; ++i)
		for(int j = 0; j < m; ++j) {
			chmin(f[i][j], get(i - 1, j) + 1);
			chmin(f[i][j], get(i, j - 1) + 1);
			if(s[i] == t[j]) chmin(f[i][j], get(i - 1, j - 1));
			else chmin(f[i][j], get(i - 1, j - 1) + 1);
		}
	return f.back().back();
}

