str Merge(str a, str b){
	swap(a, b);
	int n = a.size(), m = b.size();
	for(int i = 0; i <= n; i++) ins[i] = "";
	int p = 0;
	for(int i = 0; i < m; i++){

		while(true){
			ins[p] += b[i];
			str Q = ins[0];
			for(int j = 1; j <= n; j++){
				Q += a[j - 1];
				Q += ins[j];
			}
			if((p == n) || (ask(Q) == L - Q.size())) break;
			else {
				ins[p].pop_back();
				p ++;
			}
		}
	}
	str re = ins[0];
	for(int j = 1; j <= n; j++){
		re += a[j - 1];
		re += ins[j];
	}
	assert(((int)re.size()) == n + m);
	return re;
}

