        return vec[l];
    int mid = (l + r) >> 1;
    string sl = Merge(l,mid),sr = Merge(mid + 1,r);
    string s = "";
    int lenl = sl.length(),lenr = sr.length();
    for(int i = 0,j = 0,k = n - lenl;i <= lenl;i++){
