using namespace std;
const int L = 128, lim = 62;
int res, len, cnt[lim + 5];
char Fix(int k)
{
	if (k < 26)
		return 'a' + k;
	if (k < 52)
		return 'A' + k - 26;
	return '0' + k - 52;
}
bool Query(vector<char> X, int pos, char ch)
{
	X.insert(X.begin() + pos, ch);
	putchar('?'), putchar(' ');
	for (int i = 0; i < (int)X.size(); i++)
		putchar(X[i]);
	putchar(10);
	fflush(stdout);
	scanf("%d", &res);
	return res == len - (int)X.size();
}
vector<char> Solve(int l, int r)
{
	if (l == r)
		return vector<char>(cnt[l], Fix(l));
	int mid = (l + r) >> 1;
	vector<char> L = Solve(l, mid);
	vector<char> R = Solve(mid + 1, r);
	int p = 0;
	for (int i = 0; i <= (int)L.size(); i++)
		while (p < (int)R.size() && Query(L, i, R[p]))
			L.insert(L.begin() + i, R[p]), i++, p++;
	return L;
}
int main()
{
	for (int i = 0; i < lim; i++)
	{
		putchar('?'), putchar(' ');
		for (int j = 0; j < L; j++)
			putchar(Fix(i));
		putchar(10);
		fflush(stdout);
		scanf("%d", &res);
		cnt[i] = L - res, len += cnt[i];
	}
	vector<char> X = Solve(0, lim - 1);
	putchar('!'), putchar(' ');
	for (int i = 0; i < (int)X.size(); i++)
		putchar(X[i]);
	putchar(10);
}

