#define rep(i, n) for(UL i = 0; i < (n); i++)

struct Problem {
public:

	UL dist(string& S, string& T) {
		UL ans = S.size();
		rep(i, S.size()) if (S[i] == T[i]) ans--;
		return ans;
	}

	const string C = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
	static const UL KN = 62;
	UL CN[62];
	UL L;
	UL unknowns;
	string ans;
	UL Query = 0;

	void Solve2(char c, UL n, UL r = ~0u, UL s = 0) {
		if (r == ~0u) { r = unknowns; }
		if (n == 0) return;
		if (r == 1) { ans[ans.find('?', s)] = c; unknowns--; return; }
		UL m = r >> 1;
		UL t = s; rep(i, m) t = ans.find('?', t) + 1;
		string tmp = ans;
		for (UL i = 0; i < L; i++) {
			if (tmp[i] == '?') {
				if (s <= i && i < t) tmp[i] = c;
				else tmp[i] = 'a';
			}
		}

		Query++;
		if (Query >= 850) exit(0);

		printf("? %s\n", tmp.c_str()); fflush(stdout);
		UL res; scanf("%d", &res);
		res = unknowns - res;
		Solve2(c, res, m, s);
		Solve2(c, n - res, r - m, t);
	}

	void Solve() {
		rep(i, KN) {
			printf("? ");
			rep(j, 128) printf("%c", C[i]);
			printf("\n"); fflush(stdout);
			UL res; scanf("%d", &res);
			CN[i] = 128 - res;
			L += 128 - res;
		}
		ans.assign(L, '?');
		unknowns = L;

		rep(i, L) {
			printf("? ");
			rep(j, L) printf((j == i) ? "b" : "a");
			printf("\n"); fflush(stdout);
			UL res; scanf("%d", &res);
			if (res > L - CN[0]) { ans[i] = 'a'; unknowns--; }
			else if (res < L - CN[0]) { ans[i] = 'b'; unknowns--; }
		}

		Query = KN + L;

		for (UL i = 2; i < KN; i++) {
			Solve2(C[i], CN[i]);
		}

		printf("! %s\n", ans.c_str());
		fflush(stdout);
	}
};

int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}

