inline void solve(int u,int l,int r){
	if (l==r){
		For(i,1,cnt) if (tot[u][i]) ans[l]=s[i];
		return;
	}
	int mid=l+r>>1,S=0,S2=0,L=0;
	For(i,1,cnt) if (tot[u][i]){
		L=i;break;
	}
	vector<int>ans(cnt+1);
	ans[L]=tot[u][L],S=tot[u][L],S2=1;
	For(i,1,cnt) if (tot[u][i]&&i!=L){
		string s;
		For(j,1,mid) s=s+::s[L];
		For(j,1,n-mid) s=s+::s[i];
		ans[i]=(n-Query(s))-pre[u][L]-suf[u][i],S+=ans[i],++S2;
	}
	tot[u<<1][L]=(S-(r-mid))/S2;
	For(i,1,cnt) if (tot[u][i]) tot[u<<1^1][i]=ans[i]-tot[u<<1][L];
	For(i,L+1,cnt) if (tot[u][i]) tot[u<<1][i]=tot[u][i]-tot[u<<1^1][i];
	For(i,1,cnt){
		suf[u<<1][i]=suf[u][i]+tot[u<<1^1][i];
		suf[u<<1^1][i]=suf[u][i];
		pre[u<<1^1][i]=pre[u][i]+tot[u<<1][i];
		pre[u<<1][i]=pre[u][i];
	}
	solve(u<<1,l,mid),solve(u<<1^1,mid+1,r);
}
