void solve(int l, int r)
{
  int mid=(l+r)/2,sum=0,num=0,j=-1,letter[sz],len=0,*a,*rem;
  if(l+1==r)
  {
    rep(i,sz)if(edit[i][r]!=edit[i][l]){pw[l]=charaset[i];return;}
  }
  rep(i,sz)
  {
    if(edit[i][l]==edit[i][r])
    {
      edit[i][mid]=edit[i][l];
      sum-=edit[i][l];
      j=i;
    }
    else
    {
      a=(int*)realloc(rem,sizeof(int)*++len);
      if(!a){free(rem);err(EXIT_FAILURE,"fault");}
      rem=a;
      rem[len-1]=i;
    }
  }
  tmp=(char*)realloc(word,sizeof(int)*N);
  if(!tmp){free(word);err(EXIT_FAILURE,"fault");}
  word=tmp;
  rep(i,N)word[i]='a';
  if(j==-1)
  {
    rep(i,len)
    {
      if(i==0)continue;
      rep(k,mid)word[k]=charaset[i];
      letter[i]=query(word)-N+edit[0][N];
      sum+=letter[i];
      num++;
    }
    assert((mid+sum)%(num+1)==0);
    int ret=(mid+sum)/(num+1);
    edit[0][mid]=edit[0][0]+ret;
    rep(i,sz-1)
    {
      if(edit[i+1][l]==edit[i+1][r]){continue;}
      edit[i+1][mid]=edit[i+1][0]-letter[i+1]+ret;
    }
  }
  else
  {
    sum+=edit[j][l];
    rep(i,len)
    {
      if(i==rem[len-1])
      {
        letter[i]=(len+1)*edit[j][mid]-sum-mid;
        continue;
      }
      rep(i,N)word[i]=charaset[j];
      rep(k,mid)word[k]=charaset[i];
      letter[i]=query(word)-N+edit[j][N];
      sum+=letter[i];
    }
    rep(i,len){edit[i][mid]=edit[i][0]-letter[i]+edit[j][mid];}
  }
  solve(l,mid);
  solve(mid,r);
}

