	vector<char> vec, vec2;
	for (int i = 0; i < 26; i++) vec.push_back('A' + i);
	for (int i = 0; i < 26; i++) vec.push_back('a' + i);
	for (int i = 0; i < 10; i++) vec.push_back('0' + i);

	// 文字数の計算
	int ret[62], TotalLen = 0; vector<pair<int, int>> prio;
	for (int i = 0; i < vec.size(); i++) {
		string str = "";
		for (int j = 0; j < 128; j++) str += vec[i];
		int val = query(str);
		ret[i] = 128 - val;
		TotalLen += ret[i];
	}

	// 前準備
	vector<pair<int, int>> ord;
	for (int i = 2; i < 62; i++) {
		for (int j = 0; j < ret[i]; j++) ord.push_back(make_pair(i, j));
	}

	// A, B の位置を当てる
	for (int i = 0; i < 128; i++) ans[i] = 0;
	int CurVal = TotalLen - ret[1];
	for (int i = 1; i <= TotalLen ; i++) {
		string str = "";
		for (int j = 0; j < i; j++) str += vec[0];
		for (int j = i; j < TotalLen; j++) str += vec[1];
		int NexVal = query(str);
		if (CurVal > NexVal) ans[i - 1] = vec[0];
		if (CurVal < NexVal) ans[i - 1] = vec[1];
		CurVal = NexVal;
	}

	// その他の文字の位置を当てる
	for (pair<int, int> i : ord) {
		int Rmost = 0; for (int j = 0; j < TotalLen; j++) { if (ans[j] == vec[i.first]) Rmost = j; }
		vector<int> Cand; for (int j = Rmost + 1; j < TotalLen; j++) { if (ans[j] == 0) Cand.push_back(j); }
		int sz = 0; for (int j = 0; j <= 7; j++) { if ((1 << j) >= Cand.size()) { sz = j; break; } }

		int vx = 0;
		for (int j = sz - 1; j >= 0; j--) {
			int pos = Cand[min((int)Cand.size() - 1, vx + (1 << j))];
			string D = "";
			for (int k = 0; k < pos; k++) D += "A";
			for (int k = pos; k < TotalLen; k++) D += vec[i.first];
			int CandVal = query(D);
			int Exp = ret[i.first];
			for (int k = 0; k < pos; k++) { if (ans[k] == 'A') Exp += 1; }
			for (int k = 0; k < pos; k++) { if (ans[k] == vec[i.first]) Exp -= 1; }
			if (CandVal == TotalLen - Exp) { vx += (1 << j); }
		}
		ans[Cand[vx]] = vec[i.first];
	}

	string Answer = "";
	for (int i = 0; i < TotalLen; i++) Answer += ans[i];
	return Answer;
}

