    rep(i, m) if (cnt[i][r] != cnt[i][l]) {
      ans[l] = cha[i];
      return;
    }
  }
  int mid = (l + r) / 2;
  int sum = 0, num = 0;
  vector<int> c(m);
  int j = -1;
  vector<int> rem;
  REP(i, 0, m) {
    if (cnt[i][l] == cnt[i][r]) {
      cnt[i][mid] = cnt[i][l];
      sum -= cnt[i][l];
      j = i;
    } else
      rem.push_back(i);
  }
  if (j == -1) {
    for (auto i : rem) {
