    int ret = (mid + sum) / (num + 1);
    cnt[25][mid] = cnt[25][0] + ret;
    REP(i, 0, m) {
      if (i == 25 || cnt[i][l] == cnt[i][r]) {
        continue;
      }
      cnt[i][mid] = cnt[i][0] - c[i] + ret;
    }
  } else {
    sum += cnt[j][l];
    for (auto i : rem) {
      if (i == rem.back()) {
        c[i] = (rem.size() + 1) * cnt[j][mid] - sum - mid;
        continue;
