void recurse(int l, int r, vector<pair<char, int> > freq)
{
	if(freq.size() == 1) //base case
	{
		for(int i = l; i <= r; i++)
			ans[i] = freq[0].first;
		return;
	}
	char ch = freq.back().first;
	string base = get(l, r, ch, ch);
	int val = query(base);
	int m = (l + r) / 2;
	vector<pair<char, int> > lfreq, rfreq;
	int leftLen = m - l + 1, taken = 0;
	for(int i = 0; i + 1 < freq.size(); i++)
	{
		char cur = freq[i].first;
		string str = get(l, r, cur, ch);
		int curVal = query(str);
		int fr = abs(val - curVal);
		if(fr > 0)
			lfreq.push_back({cur, fr});
		if(freq[i].second - fr > 0)
			rfreq.push_back({cur, freq[i].second - fr});
		taken += fr;
	}
	if(taken < leftLen)
		lfreq.push_back({ch, leftLen - taken});
	int k = leftLen - taken;
	int lastFreq = freq.back().second;
	if(k < lastFreq)
		rfreq.push_back({ch, lastFreq - k});
	recurse(l, m, lfreq);
	recurse(m + 1, r, rfreq);
}

