	}
	while(S.size()>1)
	{
		sort(S.begin(),S.end(),cmp);
		string a=S[0],b=S[1],res;
		S.erase(S.begin()),S.erase(S.begin());
		while(a.size()&&b.size())
			if(check(res+a[0]+b))res+=a[0],a.erase(a.begin());
			else res+=b[0],b.erase(b.begin());
		res+=a,res+=b;
		S.push_back(res);
	}
	cout<<"! "<<S[0]<<endl;
}

