const int L = 128;

string f(const string& alphabet, const vector<int>& freq, int l, int r) {
	if (r == l + 1) {
		return string(freq[l], alphabet[l]);
	}
	int m = (l + r) / 2;
	auto le = f(alphabet, freq, l, m);
	auto ri = f(alphabet, freq, m, r);
	// cerr << "[" << l << ", " << r << "): '" << le << "', '" << ri << "'\n";
	int len = accumulate(all(freq), 0);
	string s = le;
	int i = le.size();
	int j = (int)ri.size() - 1;
	for (j = (int)ri.size() - 1; j >= 0; --j) {
		while (i > 0) {
			s.insert(s.begin() + i, ri[j]);
			if (ask(s) == len - (int)s.size()) {
				break;
			} else {
				s.erase(s.begin() + i);
				--i;
			}
		}
		if (i == 0) {
			break;
		}
	}
	s = ri.substr(0, j + 1) + s;
	return s;
}

