inline vector<int> solve(int l, int r)
{
	if(l == r)
	{
		vector<int> t;
		for(int i = 0; i < cnt[l]; i++) t.push_back(l);
		return t;
	}
	int mid = (l + r) >> 1;
	vector<int> tl = solve(l, mid), tr = solve(mid + 1, r);
	vector<int> res;
	int x = 0, y = 0;
	while(x < tl.size() && y < tr.size())
	{
		vector<int> t(res);
		t.push_back(tl[x]); t.push_back(tr[y]);
		if(query(t) != n - t.size()) res.push_back(tr[y ++]);
		else res.push_back(tl[x ++]);
	}
	while(x < tl.size()) res.push_back(tl[x ++]);
	while(y < tr.size()) res.push_back(tr[y ++]);
	return res;
}

