int ask(string s) {
#ifdef LOCAL
	string ans = "Atcod3rIsGreat";
	int L1 = s.length(), L2 = ans.length();
	vector< vector<int> > dp(L1+1, vector<int>(L2+1, L1+L2));
	dp[0][0] = 0;
	for(int i = 0; i <= L1; i++) for(int j = 0; j <= L2; j++) {
		if(i < L1) dp[i+1][j] = min(dp[i+1][j], dp[i][j]+1);
		if(j < L2) dp[i][j+1] = min(dp[i][j+1], dp[i][j]+1);
		if(i < L1 && j < L2) dp[i+1][j+1] = min(dp[i+1][j+1], dp[i][j] + (s[i] != ans[j]));
	}
	return dp[L1][L2];
#else
	cout << "? " << s << endl;
	int a;
	cin >> a;
	return a;
#endif
}

