  {
    if(len==0){len=diff[i];rep(j,diff[i])pw[j]=letters[i];}
    else
    {
      l=0;
      rep(k,diff[i])
      {
        r=len;
        while(l<r)
        {
          mid=(l+r+1)/2;
          rep(j,mid)query[j]=pw[j];
          rep(j,diff[i]-k)query[mid+j]=letters[i];
          query[mid+diff[i]-k]=0;
          if(ask()==total-mid-diff[i]+k)l=mid;else r=mid-1;
        }
        len++;rep(j,len-l){pw[len-j]=pw[len-j-1];}pw[l]=letters[i];
      }
    }
  }
  pw[len]=0;printf("! %s\n",pw);return fflush(stdout),0;
}

