int edi(vector<char> a, vector<char> b)
{
	int as=a.size();
	int bs=b.size();
	vector<vi> dp(as+1, vi(bs+1, 0));
	for (int i=0; i<=as; i++)
	{
		for (int j=0; j<=bs; j++)
		{
			if (!i && !j)
				continue;
			if (!i || !j)
			{
				dp[i][j]=i+j;
				continue;
			}
			if (a[i-1]==b[j-1])
				dp[i][j]=min(dp[i-1][j-1], min(dp[i-1][j], dp[i][j-1])+1);
			else
				dp[i][j]=min(dp[i-1][j-1], min(dp[i-1][j], dp[i][j-1]))+1;
		}
	}

	return dp[as][bs];
}

