	assert(chars.size() == 62);
	std::vector<std::string> cur_que;
	for (int i = 0; i < 62; ++i) {
		std::string x(MAX_L, chars[i]);
		int v = MAX_L - query(x);
		n += v;
		if (v) cur_que.emplace_back(std::string(v, chars[i]));
	}
	while (cur_que.size() > 1) {
		std::sort(cur_que.begin(), cur_que.end());
		std::string a = cur_que[0], b = cur_que[1];
		cur_que.erase(cur_que.begin(), cur_que.begin() + 2);
		while (a.size() > 0 && b.size() > 0) {
			if (check(ans + a[0] + b)) {
				ans += a[0];
				a.erase(a.begin());
			} else {
				ans += b[0];
				b.erase(b.begin());
			}
