    std::cin.tie(nullptr);
    char alpha[62];
    for (int i = 0; i < 26; ++i)
        alpha[i] = 'a' + i;
    for (int i = 0; i < 26; ++i)
        alpha[26 + i] = 'A' + i;
    for (int i = 0; i < 10; ++i)
        alpha[52 + i] = '0' + i;
    std::random_shuffle(alpha, alpha + 62, [&](int n) {return rnd() % n;});
    int cnt[62];
    for (int i = 0; i < 62; ++i)
        cnt[i] = L - query(std::string(L, alpha[i]));
    int n = std::accumulate(cnt, cnt + 62, 0);
    std::string s(n, alpha[1]);
    int q = query(s);
    std::vector<int> suf(n + 1);
    std::vector<bool> a(n);
    for (int i = 0; i < n; ++i) {
        s[i] = alpha[0];
        if (query(s) == q - 1) {
            suf[i] = 1;
            --q;
            a[i] = true;
        } else {
            s[i] = alpha[1];
        }
    }
    for (int i = n - 1; i >= 0; --i)
        suf[i] += suf[i + 1];
    std::string ans(n, alpha[0]);
    for (int i = 1; i < 62; ++i) {
        int x = 0;
        for (int v = 0; v < cnt[i]; ++v) {
            int c = 0;
            for (int i = x; i < n; ++i)
                c += !a[i];
            int l = 0, r = c - 1;
            while (l < r) {
                int m = (l + r + 1) / 2;
                int p = x;
                for (int i = x, j = m; i < n; ++i) {
                    if (j && !a[i]) {
                        p = i + 1;
                        --j;
                    }
                }
                if (query(std::string(p, alpha[i]) + std::string(n - p, alpha[0])) == n - v - suf[p]) {
                    l = m;
                } else {
                    r = m - 1;
                }
            }
            int p = x;
            for (int i = x, j = l; i < n; ++i) {
                if (!a[i]) {
                    if (j) {
                        --j;
                    } else {
                        p = i;
                        break;
                    }
                }
            }
            a[p] = true;
            ans[p] = alpha[i];
            x = p + 1;
        }
    }
    std::cout << "! " << ans << std::endl;
    return 0;
}

