const int m = 62;
int cnt[62][200], n;
string ans, cha;

void solve(int l, int r) {
  if (l + 1 == r) {
    rep(i, m) if (cnt[i][r] != cnt[i][l]) {
      ans[l] = cha[i];
      return;
    }
  }
  int mid = (l + r) / 2;
  int sum = 0, num = 0;
  vector<int> c(m);
  int j = -1;
  vector<int> rem;
  REP(i, 0, m) {
    if (cnt[i][l] == cnt[i][r]) {
      cnt[i][mid] = cnt[i][l];
      sum -= cnt[i][l];
      j = i;
    } else
      rem.push_back(i);
  }
  for (auto i : rem) {
    if (i == 25) continue;
    string s(n, 'z');
    REP(k, 0, mid) s[k] = cha[i];
    c[i] = query(s) - n + cnt[25][n];
    sum += c[i];
    num++;
  }
  assert((mid + sum) % (num + 1) == 0);
  int ret = (mid + sum) / (num + 1);
  cnt[25][mid] = cnt[25][0] + ret;
  REP(i, 0, m) {
    if (i == 25 || cnt[i][l] == cnt[i][r]) {
      continue;
    }
    cnt[i][mid] = cnt[i][0] - c[i] + ret;
  }
  solve(l, mid);
  solve(mid, r);
}

