const int m = 62;
int cnt[62][200], n;
string ans, cha;

void solve(int l, int r){
    if(l+1==r){
        rep(i,m)if(cnt[i][r]!=cnt[i][l]){
            ans[l]=cha[i];
            return;
        }
    }
    int mid=(l+r)/2;
    int sum = 0, num = 0;
    vector<int> c(m);
    int j = -1;
    vector<int> rem;
    REP(i,0,m){
        if(cnt[i][l]==cnt[i][r]){
            cnt[i][mid]=cnt[i][l];
            sum -= cnt[i][l];
            j=i;
        }
        else rem.push_back(i);
    }
    if(j == -1){
        for(auto i : rem){
            if(i == 0)continue;
            string s(n, 'a');
            REP(k,0,mid)s[k]=cha[i];
            c[i] = query(s) - n + cnt[0][n];
            sum += c[i];
            num++;
        }
        assert((mid+sum)%(num+1)==0);
        int ret = (mid + sum)/(num + 1);
        cnt[0][mid]=cnt[0][0]+ret;
        REP(i,1,m){
            if(cnt[i][l]==cnt[i][r]){
                continue;
            }
            cnt[i][mid]=cnt[i][0]-c[i]+ret;
        }
    }
    else {
        sum += cnt[j][l];
        for(auto i : rem){
            if(i == rem.back()){
                c[i] = (rem.size()+1)*cnt[j][mid] - sum - mid;
                continue;
            }
            string s(n, cha[j]);
            REP(k,0,mid)s[k]=cha[i];
            c[i] = query(s) - n + cnt[j][n];
            sum += c[i];
        }
        for(auto i : rem){
            cnt[i][mid]=cnt[i][0]-c[i]+cnt[j][mid];
        }
    }
    solve(l,mid);
    solve(mid,r);
}

