namespace local{
	bool _init = false;
	string password;	
	int dp[L + 1][L + 1];

	void init(){
		while(password.size() < L)
			password.push_back(letters[rand() % 62]);
		return;

		for(auto c: letters){
			password.push_back(c);
			password.push_back(c);
		}

		while(password.size() < 100)
			password.push_back('a');
		random_shuffle(password.begin(), password.end());
		cerr << password << "\n";
	}

	void calc_dp(string &s){
		int n = password.size(), m = s.size();
		for(int i = 1; i <= m; ++i)
			dp[0][i] = i;
		for(int i = 1; i <= n; ++i)
			dp[i][0] = i;

		for(int i = 1; i <= n; ++i)
			for(int j = 1; j <= m; ++j){
				auto cp = password[i - 1], cs = s[j - 1];
				dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + 1;
				dp[i][j] = min(dp[i][j], dp[i - 1][j - 1] + 1);

				if(cp == cs)
					dp[i][j] = min(dp[i][j], dp[i - 1][j - 1]);
			}
	}

	int ask(string s){
		if(!_init)
			init();
		_init = true;

		calc_dp(s);
		return dp[password.size()][s.size()];
	}
}

