int len;
vector <string> substrs;

void get_len(){
	int s = 1, e = L;
	while(s < e){
		int mid = (s + e) / 2;
		string cur;

		for(int i = 0; i < mid; ++i)
			cur.push_back('a');

		int fa = ask(cur);
		cur.push_back('a');

		if(fa < ask(cur))
			e = mid;
		else
			s = mid + 1;
	}

	len = s;
}

void get(char c){
	string ret;
	while((int)ret.size() < len)
		ret.push_back(c);

	int l = len - ask(ret);
	while((int)ret.size() > l)
		ret.pop_back();

	if(ret.size())
		substrs.push_back(ret);
}

int count(string a, string b, string ret, int it){
	reverse(ret.begin(), ret.end());
	string st;
	for(int i = 0; i < it; ++i)
		st.push_back(a[i]);

	int t = 1;
	while(t <= (int)b.size()){
		string tmp = st;
		for(int i = b.size() - t; i < (int)b.size(); ++i)
			tmp.push_back(b[i]);

		tmp += ret;
		if(len - ask(tmp) < (int)tmp.size())
			break;
		t *= 2;
	}

	int s = t / 2, e = min(t - 1, (int)b.size());
	while(s < e){
		t = (s + e + 1) / 2;
		string tmp = st;
		for(int i = b.size() - t; i < (int)b.size(); ++i)
			tmp.push_back(b[i]);

		tmp += ret;
		if(len - ask(tmp) < (int)tmp.size())
			e = t - 1;
		else
			s = t;
	}

	return s;
}

string Union(string a, string b){
	string ret;
//	cerr << "Union " << a << " " << b << "\n";

	int it = a.size();
	while(it > 0){
		int l = count(a, b, ret, it);
		while(l--){
			ret.push_back(b.back());
			b.pop_back();
		}

		ret.push_back(a[--it]);
	}

	while(b.size()){
		ret.push_back(b.back());
		b.pop_back();
	}

	reverse(ret.begin(), ret.end());
	return ret;
}

