    for (int i = 0; i < 10; i++) alphabet += '0'+i;

    L = 0;
    vector<string> sub(alphabet.size());
    for (int i = 0; i < (int)alphabet.size(); i++) {
        int c = query(string(128, alphabet[i]));
        c = 128-c;
