    for(auto c:chars){
        string all_c(128, c);
        cnt[c] = query(all_c);
        len += cnt[c];
        if(cnt[c])exist.push_back(c);
    }
    ans.resize(len);
    for(auto c:chars){
        memo[c][0][len]=cnt[c];
    }

    solve(exist, 0, len);
    answer(ans);
    return 0;
}

