bool local = false;

string pattern = "Atcod3rIsGreat";
const int INF = (int)1e9;

int get_distance(string a, string b) {
  vector<vector<int>> dp(a.size() + 1, vector<int>(b.size() + 1, INF));
  dp[0][0] = 0;
  for (int i = 0; i <= a.size(); ++i) {
    for (int j = 0; j <= b.size(); ++j) {
      if (i + 1 <= a.size()) {
        relax_min(dp[i + 1][j], dp[i][j] + 1);
      }
      if (j + 1 <= b.size()) {
        relax_min(dp[i][j + 1], dp[i][j] + 1);
      }
      if (i < a.size() && j < b.size()) {
        relax_min(dp[i + 1][j + 1], dp[i][j] + (a[i] != b[j]));
      }
    }
  }
  return dp[a.size()][b.size()];
}

