#define data sdgasdgfs

vector<pair<string, int>> data;

pair<string, int> get_rec(int l, int r) {
  if (l + 1 == r) {
    return data[l];
  }
  int m = (l + r) / 2;
  auto a_item = get_rec(l, m);
  auto a = a_item.first;
  auto prev_dist = a_item.second;
  auto b = get_rec(m, r).first;
  //cout << a << " " << b << endl;
  reverse(all(b));
  int uk = (int)a.size();
  for (char c : b) {
    while (true) {
      if (uk < 0) {
        a.insert(a.begin(), c);
        --prev_dist;
        break;
      }
      auto candy = a;
      candy.insert(candy.begin() + uk, c);
      auto new_dist = query(candy);
      if (new_dist < prev_dist) {
        prev_dist = new_dist;
        a = candy;
        break;
      }
      --uk;
    }
  }
  return {a, prev_dist};
}

void solve(__attribute__((unused)) bool read) {
  string alphabet;
  for (char c = 'a'; c <= 'z'; ++c) {
    alphabet += c;
  }
  for (char c = 'A'; c <= 'Z'; ++c) {
    alphabet += c;
  }
  for (char c = '0'; c <= '9'; ++c) {
    alphabet += c;
  }

  if (local) {
    pattern.clear();
    for (int i = 0; i < 128; ++i) {
      pattern += alphabet[rand() % alphabet.size()];
    }
  }

  n_queries = 0;
  int L = 0, R = 128;
  while (L + 1 < R) {
    int M = (L + R) / 2;
    if (query(string(M + 1, 'a')) > query(string(M, 'a'))) {
      R = M;
    } else {
      L = M;
    }
  }
  int len = R;
  if (local) {
    assert(len == pattern.length());
  }

  //cerr << "n_queries_before: " << n_queries << endl;

  data.clear();
  for (char c : alphabet) {
    int dist = query(string(len, c));
    if (dist < len) {
      data.push_back({string(len - dist, c), dist});
    }
  }
  string res = get_rec(0, data.size()).first;
  cout << "! " << res << endl;
  if (local) {
    assert(res == pattern);
    cerr << "n_queries: " << n_queries << endl;
    assert(n_queries <= 850);
