	for (int i = 1; i <= n; ++i) len = min (len, ask (s[i] + ch[i]) + 1);
	//找出每个字符出现次数
	for (int i = 1; i <= n; ++i)
		while (ask (s[i] + ch[i]) + s[i].size() + 1 == len) s[i] += ch[i];
