i64 char_to_id(char c){
    if('a'<=c and c<='z') return c-'a';
    else if('A'<=c and c<='Z') return c-'A'+26;
    else return c-'0'+52;
}

char id_to_char(i64 id){
    if(id<26) return 'a'+id;
    else if(id<52) return 'A'+id-26;
    else return '0'+id-52;
}

constexpr i64 L=128,Q=850;
