int query(const string &s) {
#ifdef LOCAL
    vector<vi> dp(si(s)+1, vi(si(ANS)+1));
    dforsn(i,0,si(s)+1) dforsn(j,0,si(ANS)+1) {
        if (i == si(s)) dp[i][j] = si(ANS)-j;
