int len;

string merge(const string &s, const string &t) {
    string ans;
    int i = 0, j = 0;
    while (i < si(s) && j < si(t)) {
        auto query_string = ans + t[j] + s.substr(i);
        if (query(query_string) > len - si(query_string)) {
            ans += s[i];
            i++;
        }
        else {
            ans += t[j];
            j++;
        }
    }
    ans += s.substr(i);
    ans += t.substr(j);
    return ans;
}

string go(const vector<string> &seq, int l, int r) {
    if (l+1 == r) return seq[l];
    int m = (l+r)/2;
    auto s = go(seq,l,m), t = go(seq,m,r);
    return merge(s,t);
}

