	for(i=0;i<62;i++)
	{
		s="";
		if(i<26) cw='a'+i;
		else if(i<52) cw='A'+(i-26);
		else cw='0'+(i-52);
		for(j=0;j<128;j++) s+=cw;
		num=128-qry(s);
		len+=num;
		if(num==0) continue;
		s="";
		for(j=0;j<num;j++) s+=cw;
		prq.push((Node){s,num});
	}
	while(prq.size()>=2)
	{
