struct Range {
	int l, r, num;
	Range(const int ll, const int rr, const int nn) {
		l = ll, r = rr, num = nn;
	}
};

class XorShift {
	unsigned int x, y, z, w, t;
public:
	XorShift() {
		x = 133553533;
		y = 314867339;
		z = 664298413;
		w = 999999937;
		t = 0;
	}
	unsigned int rand() {
		t = x ^ (x << 11);
		x = y;
		y = z;
		z = w;
		w = (w ^ (w >> 19)) ^ (t ^ (t >> 8));
		return w & 0x7fffffff;
	}
};

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	if(DEBUG)cin >> test;

	XorShift xs;
	string box;
	for (char i = 'a'; i <= 'z'; i++)box.push_back(i);
	for (char i = 'A'; i <= 'Z'; i++)box.push_back(i);
	for (char i = '0'; i <= '9'; i++)box.push_back(i);
	vector<int>num(256);
	for (auto i : box) {
		string s(1, i);
		num[i] = Ask(s);
	}

	int mx = 0, mn = MOD;
	for (auto i : box) {
		mx = max(mx, num[i]);
		mn = min(mn, num[i]);
	}
	if (mx == mn) {
		L = mx + 1;
	}
	else {
		L = mx;
	}
	for (auto i : box) {
		string s(L, i);
		num[i] = L - Ask(s);
		break;
	}

	string ans(L, ' ');
	char dummy = 'a';
	if (num['a']) {
		vector<int>bag(L);
		mn = MOD;
		for (int i = 0; i < L; i++) {
			string s(L, 'b');
			s[i] = 'a';
			bag[i] = Ask(s);
			mn = min(mn, bag[i]);
		}
		for (int i = 0; i < L; i++) {
			if (mn == bag[i]) {
				ans[i] = 'a';
			}
		}
	}
	for (auto i : box) {
		if (i == dummy)continue;
		string st(L, i);
		num[i] = L - Ask(st);
		queue<Range>Q;
		Q.push(Range(0, L, num[i]));
		while (!Q.empty()) {
			auto cr = Q.front();
			Q.pop();
			if (cr.num == 0)continue;
			if (cr.l >= cr.r)continue;
			int space = 0;
			for (int j = cr.l; j < cr.r; j++) {
				if (ans[j] == ' ')space++;
			}
			if (cr.num == space) {
				for (int j = cr.l; j < cr.r; j++) {
					if (ans[j] == ' ')ans[j] = i;
				}
				continue;
			}
			bool ed = false;
			while (!Q.empty()) {
				break;
				auto sndr = Q.front();
				Q.pop();
				if (sndr.num == 0)continue;
				int sndspace = 0;
				for (int j = sndr.l; j < sndr.r; j++) {
					if (ans[j] == ' ')sndspace++;
				}
				if (sndr.num == sndspace) {
					for (int j = sndr.l; j < sndr.r; j++) {
						if (ans[j] == ' ')ans[j] = i;
					}
					continue;
				}
				Range cnxl(cr.l, (cr.l + cr.r) / 2, 0);
				Range cnxr((cr.l + cr.r) / 2, cr.r, 0);
				Range sndnxl(sndr.l, (sndr.l + sndr.r) / 2, 0);
				Range sndnxr((sndr.l + sndr.r) / 2, sndr.r, 0);
				string s(L, dummy);
				for (int j = cnxl.l; j < cnxl.r; j++)s[j] = i;
				for (int j = sndnxl.l; j < sndnxl.r; j++)s[j] = i;
				int lnum = Ask(s);
				for (int j = 0; j < L; j++) {
					if (s[j] == dummy&&ans[j] != s[j])lnum--;
				}
				int nnum = cnxl.r - cnxl.l + sndnxl.r - sndnxl.l - lnum;
				if (cr.num + sndr.num == nnum) {
					cnxl.num = cr.num;
					sndnxl.num = sndr.num;
					Q.push(cnxl);
					Q.push(sndnxl);
				}
				else if (nnum == 0) {
					cnxr.num = cr.num;
					sndnxr.num = sndr.num;
					Q.push(cnxr);
					Q.push(sndnxr);
				}
				else {
					string t(L, dummy);
					for (int j = cnxl.l; j < cnxl.r; j++)t[j] = i;
					int rnum = Ask(t);
					for (int j = 0; j < L; j++) {
						if (t[j] == dummy && ans[j] != t[j])rnum--;
					}
					int mnum = cnxl.r - cnxl.l  - rnum;
					int ll = mnum, lr = cr.num - ll, rl = nnum - ll, rr = sndr.num - rl;
					sndnxl.num = rl, sndnxr.num = rr;
					cnxl.num = ll, cnxr.num = lr;
					Q.push(cnxl);
					Q.push(sndnxl);
					Q.push(cnxr);
					Q.push(sndnxr);
				}
				ed = true;
				break;
			}
			if (ed)continue;
			Range cnxl(cr.l, (cr.l + cr.r) / 2, 0);
			Range cnxr((cr.l + cr.r) / 2, cr.r, 0);
			string s(L, 'a');
			for (int j = cnxl.l; j < cnxl.r; j++)s[j] = i;
			int lnum = Ask(s);
			for (int j = 0; j < L; j++) {
				if (s[j] == dummy&&ans[j] != s[j])lnum--;
			}
			cnxl.num = cnxl.r - cnxl.l - lnum;
			cnxr.num = cr.num - cnxl.num;
			Q.push(cnxl);
			Q.push(cnxr);
		}
	}
	cout << "! " << ans << endl;
	if(DEBUG)cout << cnt << endl;
}

