        int mid = (low + high) >> 1;
        int n_left = mid - low + 1;
        vector<int> left(n);
        int sum = 0, num = 0;
        int best = dis(rng);
        for (int i = 0; i < n; ++i) {
          if (cnt[i] > cnt[best]) {
            best = i;
          }
        }
        for (int i = 0; i < n; ++i) {
          if (total[i] > 0) {
            string s(len, abc[best]);
            for (int j = low; j <= mid; ++j) {
              s[j] = abc[i];
            }
            left[i] = len - ask(s);
            sum += left[i];
            ++num;
          }
        }
        assert((sum - n_left) % num == 0);
        int base = (sum - n_left) / num;
        vector<int> right(n);
        for (int i = 0; i < n; ++i) {
          if (total[i] > 0) {
            left[i] -= base;
            right[i] = total[i] - left[i];
          }
        }
        self(low, mid, left);
        self(mid + 1, high, right);
      });
  solve(0, len - 1, cnt);
  cout << "! " << ans << endl;
  return 0;
}

