	void Solve2(char c, UL n, UL r = ~0u, UL s = 0) {
		if (r == ~0u) { r = unknowns; }
		if (n == 0) return;
		if (r == n) {
			UL t = s;
			rep(i, n) {
				t = ans.find('?', t);
				ans[t] = c;
				unknowns--;
			}
			return;
		}
		UL m = r >> 1;
		UL t = s; rep(i, m) t = ans.find('?', t) + 1;
		string tmp = ans;
		for (UL i = 0; i < L; i++) {
			if (tmp[i] == '?') {
				if (s <= i && i < t) tmp[i] = c;
				else tmp[i] = C[tg[0]];
			}
		}

		printf("? %s\n", tmp.c_str()); fflush(stdout);
		UL res; scanf("%d", &res);
		res = unknowns - res;
		Solve2(c, res, m, s);
		Solve2(c, n - res, r - m, t);
	}

	void Solve() {
		rep(i, KN) {
			printf("? ");
			rep(j, 128) printf("%c", C[i]);
			printf("\n"); fflush(stdout);
			UL res; scanf("%d", &res);
			CN[i] = 128 - res;
			L += 128 - res;
