vector<char> charset;

void solve(int a, int b, vector<int>& f, const vector<int>& ftot, string& ans) {
  vector<pair<int, int>> v;
  for (int i = 0; i < (int)f.size(); ++i) {
    if (f[i] > 0) v.emplace_back(i, f[i]);
  }

  if (v.size() == 0) {
    assert(a == b);
    return;
  }

  if (v.size() == 1) {
    char c = charset[v[0].first];
    for (int i = a; i < b; ++i) ans[i] = c;
    return;
  }

  // random_shuffle(v.begin(), v.end());
  int mn = (b - a) / v.size();
  vector<int> choices;
  for (int i = 0; i < (int)v.size(); ++i) {
    if (v[i].second <= mn) {
      choices.push_back(i);
    }
  }
  assert(choices.size());
  int idx = choices[rand() % choices.size()];
  swap(v[0], v[idx]);

  int x = v[0].first;
  char cx = charset[x];

  int cntsuf = ftot[x];
  for (int i = 0; i < a; ++i)
    if (ans[i] == cx) cntsuf--;
  assert(cntsuf > 0);

  vector<vector<int>> w(v[0].second + 1, vector<int>(f.size(), 0));
  for (int j = 1; j < (int)v.size(); ++j) {
    char c = charset[v[j].first];
    int currCost = ans.size() - a - cntsuf;
    string currQuery = ans.substr(0, a);
    string suf = string(cntsuf, cx);
    for (int i = 0; i <= v[0].second; ++i) {
      while (v[j].second > 0) {
        string q = currQuery;
        q.push_back(c);
        q += suf;

        int r = query(q);
        if (r < currCost) {
          currCost = r;
          v[j].second--;
          w[i][v[j].first]++;
          currQuery.push_back(c);
        } else {
          break;
        }
      }
      if (i < v[0].second) {
        currQuery.push_back(cx);
        suf.pop_back();
      }
    }
  }

  for (int i = 0; i <= v[0].second; ++i) {
    int len = accumulate(w[i].begin(), w[i].end(), 0);
    solve(a, a + len, w[i], ftot, ans);
    a += len;

    if (i < v[0].second) {
      ans[a++] = cx;
    } else {
      assert(a == b);
    }
  }
}

