void init(vector<string> &s, char c, int &len) {
	string que(L, c);
	int ds = ask(que);
	if (ds == L) return;

	string gf(L - ds, c);
	len += gf.size();
	s.push_back(gf);
}

bool cmp(string &s1, string &s2) {
	if (s1.size() == s2.size()) return s1 < s2;
	return s1.size() > s2.size();
}

string merge_strings(string x, string y, int len) {
	string ans;
	while (x.size() && y.size()) {
		string tmp = ans + y[0] + x;
		if (ask(tmp) == L - tmp.size()) {
			ans += y[0];
			y.erase(y.begin());
		} else {
			ans += x[0];
			x.erase(x.begin());
		}
	}
	return ans;
}

signed main() {
	//ios::sync_with_stdio(0); cin.tie(0);

	vector<string> s; int len = 0;
	for (char c = 'a'; c <= 'z'; c++) init(s, c, len);
	for (char c = 'A'; c <= 'Z'; c++) init(s, c, len);
	for (char c = '0'; c <= '9'; c++) init(s, c, len);

	while (s.size() > 1) {
		sort(s.begin(), s.end(), cmp);

		string x = s.back(); s.pop_back();
		string y = s.back(); s.pop_back();

		s.push_back(merge_strings(x, y, len));
	}

	answer(s[0]);

	return 0;
}

