string merge(string &s,string &t)
{
    string ret=s;
    int now=0,i=0;
    while(i<(int)t.size())
    {
        if(now==(int)s.size())
        {
            ret=ret+t.substr(i);
            break;
        }
        int num=now+i;
        string tmp=ret.substr(0,num)+t[i]+ret.substr(num);
        if(is_subsequence(tmp)) {ret=tmp; i++;} else now++;
    }
    return ret;
}
