int med(string s) {
	static string t = "ACBBCBBBABBAACABBBAAA";
	int n = s.size(), m = t.size();
	vector< vector<int> > f(n, vector<int>(m, n + m + 1));
	auto get = [&](int x, int y) {
		if(x == -1) return y + 1;
		else if(y == -1) return x + 1;
		else return f[x][y];
	};
	for(int i = 0; i < n; ++i)
		for(int j = 0; j < m; ++j) {
			chmin(f[i][j], get(i - 1, j) + 1);
			chmin(f[i][j], get(i, j - 1) + 1);
			if(s[i] == t[j]) chmin(f[i][j], get(i - 1, j - 1));
		}
	return f.back().back();
}

int query(string q) {
#ifdef LOCAL
	return med(q);
#else
	cout << "? " << q << endl;
	int r; cin >> r;
	return r;
#endif
}

vector<char> bet;
vector<int> occ;
int len;

string solve(int l, int r) {
	if(l == r) return string(occ[l], bet[l]);
	else {
		int m = (l + r) / 2;
		string s1 = solve(l, m), s2 = solve(m + 1, r);
		string s;
		while(s1.size() && s2.size()) {
			string q = s + s2[0] + s1;
			int r = query(q);
			r -= len - (int)q.size();
			if(r == 0) {
				s += s2[0];
				s2 = s2.substr(1);
			} else {
				s += s1[0];
				s1 = s1.substr(1);
			}
		}
		return s + s1 + s2;
	}
}

int main() {
	for(char c = 'a'; c <= 'z'; ++c) bet.push_back(c);
	for(char c = 'A'; c <= 'Z'; ++c) bet.push_back(c);
	for(char c = '0'; c <= '9'; ++c) bet.push_back(c);
	int sigma = bet.size();

	occ.assign(sigma, 0);
	for(int i = 0; i < sigma; ++i) {
		occ[i] = query(string(128, bet[i])) - 128;
	}
	int tot = accumulate(occ.begin(), occ.end(), 0);
	assert(tot % (sigma - 2) == 0);
	len = tot / (sigma - 2);
	for(int i = 0; i < sigma; ++i) {
		occ[i] = (len - occ[i]) / 2;
	}
	cout << "! " << solve(0, sigma - 1) << endl;
	return 0;
}

