int edit_distance(string a, string b) {
	// int cost_replace, cost_insert, cost_erase;
	// cin >> cost_replace >> cost_insert >> cost_erase;
	// memset(dp, -1, sizeof(dp));
	dp[0][0] = 0;
	int A = a.length();
	int B = b.length();
	// for(int i = 0; i <= A; i++) {
		// for(int j = 0; j <= B; j++) {
			// assert(dp[i][j] != -1);
			// if(i < A && j < B)
				// min_self(dp[i+1][j+1], dp[i][j] + (a[i] != b[j]));
			// if(i < A)
				// min_self(dp[i+1][j], dp[i][j] + 1);
			// if(j < B)
				// min_self(dp[i][j+1], dp[i][j] + 1);
		// }
	// }

	dp[0][0] = 0;
	for(int i = 0; i <= A; i++) {
		for(int j = 0; j <= B; j++) {
			if(i == 0 && j == 0) {
				continue;
			}
			dp[i][j] = INT_MAX;
			if(i > 0) {
				min_self(dp[i][j], dp[i-1][j] + 1);
			}
			if(j > 0) {
				min_self(dp[i][j], dp[i][j-1] + 1);
			}
			if(i > 0 && j > 0) {
				min_self(dp[i][j], dp[i-1][j-1] + (a[i-1] != b[j-1]));
			}
		}
	}
	return dp[A][B];
}

