void init(vector<string> &s, char c, int &len) {
	string que(L, c);
	int ds = ask(que);
	if (ds == L) return;

	string gf(L - ds, c);
	len += gf.size();
	s.push_back(gf);
}

bool cmp(string &s1, string &s2) {
	if (s1.size() == s2.size()) return s1 < s2;
	return s1.size() > s2.size();
}

string merge_strings(string x, string y, int len) {
	int n = x.size(), petr1 = 0;
	int m = y.size(), petr2 = 0;

	string ans = x;
	for (char c: y) {
		for (int i = 0; i <= ans.size(); i++) {
			string tmp = ans;
			tmp.insert(tmp.begin() + i, c);

			if (ask(tmp) == (len - tmp.size())) {
				ans = tmp; break;
			}
		}
	}
	return ans;
}

