int len = 0x3f3f3f3f, q[N];
string Merge(string a, string b)
{
	int i = 0, j = 0;
	int la = a.length(), lb = b.length();
	string ret = string();
	while (i < la && j < lb)
	{
		string qr = ret;
		qr += a[i];
		for (int k = j; k < lb; k++)
			qr += b[k];
		if (Query(qr) + qr.length() == len)
			ret += a[i++];
		else
			ret += b[j++];
	}
	while (i < la)
		ret += a[i++];
	while (j < lb)
		ret += b[j++];
	return ret;
}
int main()
{
	for (int i = 0; i < N; i++)
	{
		s[i] += Fix(i);
		q[i] = Query(s[i]) + 1;
		len = min(len, q[i]);
	}
	for (int i = 0; i < N; i++)
	{
		if (q[i] == len)
			while (Query(s[i] + Fix(i)) + s[i].length() + 1 == len)
				s[i] += Fix(i);
		else
			s[i] = string();
	}
	while (1)
	{
		for (int i = 0; i < N; i++)
			for (int j = i + 1; j < N; j++)
				if (s[i].length() > s[j].length())
					swap(s[i], s[j]);
		int t = 0;
		while (!s[t].length())t++;
		if (t + 1 == N)
			break;
		string now = Merge(s[t], s[t + 1]);
		s[t + 1] = now;
		s[t] = string();
	}
	cout << "! "<< s[N - 1] << endl;
	fflush(stdout);
}
