    for (int i = 0; i < k; ++i) {
        sum += cnt[i];
    }
    n = sum;

    for (int i = 0; i < k; ++i) {
        if (cnt[i] == 0) {
            continue;
        }
        string s;
        for (int j = 0; j < cnt[i]; ++j) {
