string concat(string &s,string &t){
    char c = s[0];
    bool flag = 1;
    for(int i=0;i<s.size();i++){
        if(s[i]!=c)flag = 0;
    }
    for(int i=0;i<t.size();i++){
        if(t[i]!=c)flag = 0;
    }
    if(flag){
        return s+t;
    }
    string res = t;
    int n = s.size();
    int id = 0;
    int cur = t.size();
    rep(i,n){
        if(flag)break;
        while(1){
            if(id>=cur){
                flag = 1;
                for(int j=i;j<n;j++){
                    res.push_back(s[j]);
                }
                break;
            }
            string tmp;
            for(int j=0;j<id;j++){
                tmp.push_back(res[j]);
            }
            tmp.push_back(s[i]);
            for(int j=id;j<cur;j++){
                tmp.push_back(res[j]);
            }
            int k = Q(tmp);
            if(k == len-cur-1){
                cur++;
                res = tmp;
                id++;
                break;
            }else{
                while(id<cur&&s[i]==t[id]){
                    id++;
                }
                id++;
            }
        }
    }
    return res;
}


