int lev(const std::string& first, const std::string& second) {
	std::vector<std::vector<int>> dp(first.size() + 1, std::vector<int>(second.size() + 1));
	for (size_t i = 0; i <= first.size(); ++i) {
		for (size_t j = 0; j <= second.size(); ++j) {
			dp[i][j] = first.size() + second.size() + 1;
		}
	}

	dp[0][0] = 0;
	int first_len = first.size();
	int second_len = second.size();

	auto upd = [](int* what, int with) { *what = std::min(*what, with); };

	for (int first_pos = 0; first_pos <= first_len; ++first_pos) {
		for (int second_pos = 0; second_pos <= second_len; ++second_pos) {
			if (first_pos < first_len) {
				upd(&dp[first_pos + 1][second_pos], dp[first_pos][second_pos] + 1);
			}
			if (second_pos < second_len) {
				upd(&dp[first_pos][second_pos + 1], dp[first_pos][second_pos] + 1);
			}
			if (first_pos < first_len && second_pos < second_len) {
				if (first[first_pos] == second[second_pos]) {
					upd(&dp[first_pos + 1][second_pos + 1], dp[first_pos][second_pos]);
				} else {
					upd(&dp[first_pos + 1][second_pos + 1], dp[first_pos][second_pos] + 1);
				}
			}
		}
	}
	return dp[first_len][second_len];
}


