string run(int l, int r) {
	if (l + 1 == r) {
		return string(cnt[l], ch[l]);
	}

	int m = (l + r) >> 1;
	auto sl = run(l, m);
	auto sr = run(m, r);
	int now = 0;
	for (char c : sr) {
		while (now < sl.size() && ask(sl.substr(0, now) + c + sl.substr(now)) != len - sl.size() - 1) {
			++now;
		}
		sl = sl.substr(0, now) + c + sl.substr(now);
		now += 1;
	}

	return sl;
}

