void calc(char c, int le, int ri, int pre, int tot) {
	//cout << c << ' ' << le << ' ' << ri << ' ' << tot << endl;
	Assert(tot >= 0);
	if(tot == 0) return;
	if(le == ri) {
		if(tot == 1) ans[le] = c;
		return;
	}
	//cout << "pre" << pre << endl;
