	for(int i = le; i <= ri; i++) {
		cnt += ans[i] == '!';
	}
	if(cnt == 1) {
		for(int i = le; i <= ri; i++) {
			if(ans[i] == '!') { ans[i] = c;  return;}
		}
	}
	int mid = -1;
	int bak = cnt;
	cnt = 0;
	for(int i = le; i <= ri; i++) {
		cnt += ans[i] == '!';
		if(cnt == bak / 2) {
			mid = i;
			break;
		}
	}
	Assert(bak >= 2);
	Assert(mid != -1);
	//cout << cnt << ' ' << bak << ' ' << mid << endl;
	string t = wr;
