string solve(int l,int r){
	if(l==r){
		string t;
		for(int i=1; i<=ed[l] ;i++) t+=s[l];
		return t;
	}
	int mid=(l+r)/2;
	string p=solve(l,mid);
	string q=solve(mid+1,r);
	int pp=0,qq=0;
	string s;
	while(pp!=p.size() || qq!=q.size()){
		if(pp==p.size()) s+=q[qq++];
		else if(qq==q.size()) s+=p[pp++];
		else{
			cout << "? ";
			cout << s << q[qq];
			for(int i=pp; i<p.size() ;i++) cout << p[i];
			cout << endl;
			int x;cin >> x;
			if(x>=len-(s.size()+p.size()-pp)) s+=p[pp++];
			else s+=q[qq++];
		}
	}
	return s;
}
