const string hidden = "Atcod3rIsGreat";
int getEditDistance(const string &s) {
    int n = s.size(); int m = hidden.size();
    vector< vector< int > >dp(n+1, vector< int >(m+1));
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= m; j++) {
            if (min(i, j)==0) dp[i][j] = max(i, j);
            else {
                dp[i][j] = min(dp[i-1][j], dp[i][j-1])+1;
                dp[i][j] = min(dp[i][j], dp[i-1][j-1]+(s[i-1]!=hidden[j-1]));
            }
        }
    }
    return dp[n][m];
}

