int len;
string combine(string s, string t) {
    string w(s);
    for (int i = 0, j = 0; i < t.size(); i++, j++) {
        bool last = j==w.size();
        w.insert(w.begin()+j, t[i]);
        if (last || ask(w) == len-w.size()) {
            ///fine
        } else {
            ///not fine
            i--;
            w.erase(w.begin()+j);
        }
    }
//    cout << "==> " << w << endl;
    return w;
}

