    while(qu.size() >= 2){
        auto a = qu.top(); qu.pop();
        auto b = qu.top(); qu.pop();
        swap(b, a);
        int idx = 0;
        int cur = L - a.size();
        for(int i=0;i<b.size();i++){
            a.push_back(b[i]);
            for(int j=a.size()-2;j>=idx;j--) swap(a[j], a[j+1]);
            while(true){
                ++idx;
                if(idx == a.size()) break;
                int q = query(a);
                if(q == L - a.size()) break;
                swap(a[idx-1], a[idx]);
            }
        }
        qu.push(a);
    }
    auto res = qu.top();
    cout << "! ";
    for(auto& c : res) cout << char(c);
    cout << endl;
}

