const string Chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
void solve(){
    string bad;
    while (true) {
        bad.clear();
        REP(i, 128) {
            bad.push_back(Chars[xor128() % 62]);
        }
        if (output(bad) == 128) break;
    }
    string ans = bad;
    REP(i, 128) {
        ans[i] = '?';
    }
    int now_cnt = 128;
    REP(i, Chars.size()) {
        int Counts = 0;
        string b;
        vector<int> Maybe;
        REP(q, 128) {
            if (ans[q] != '?') {
                b.push_back(ans[q]);
            }
            else {
                b.push_back(Chars[i]);
                Maybe.push_back(q);
            }
        }
        Counts = now_cnt - output(b);
        REP(q, Counts) {
            int bot = 0;
            int top = Maybe.size();
            while (abs(top - bot) > 1) {
                int mid = (top + bot) / 2LL;
                string b;
                REP(q, 128) {
                    if (ans[q] != '?') {
                        b.push_back(ans[q]);
                        continue;
                    }
                    int ok = 0;
                    for (int j = bot; j < mid; ++j) {
                        if (Maybe[j] == q) {
                            ok = 1;
                            b.push_back(Chars[i]);
                            break;
                        }
                    }
                    if (ok == 0) {
                        b.push_back(bad[q]);
                    }
                }
                if (output(b) != now_cnt) {
                    top = mid;
                }
                else {
                    bot = mid;
                }
            }
            ans[Maybe[bot]] = Chars[i];
            now_cnt--;
            Maybe.erase(Maybe.begin() + bot);
        }
    }
    cout << "! " << ans << endl;
    return;
}
