int edit_distance(string s,string t){
  int n=s.size(),m=t.size();
  vector< vector<int> > dp(n+2,vector<int>(m+2,n+m));
  dp[0][0]=0;
  for(int i=0;i<=n;i++){
    for(int j=0;j<=m;j++){
      chmin(dp[i+1][j],dp[i][j]+1);
      chmin(dp[i][j+1],dp[i][j]+1);
      chmin(dp[i+1][j+1],dp[i][j]+(s[i]!=t[j]));
    }
  }
  return dp[n][m];
}

