    return res;
}
int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    char alpha[62];
    for (int i = 0; i < 26; ++i)
        alpha[i] = 'a' + i;
    for (int i = 0; i < 26; ++i)
        alpha[26 + i] = 'A' + i;
    for (int i = 0; i < 10; ++i)
        alpha[52 + i] = '0' + i;
    int cnt[62];
    for (int i = 0; i < 62; ++i)
        cnt[i] = L - query(std::string(L, alpha[i]));
    int n = std::accumulate(cnt, cnt + 62, 0);
    std::function<std::string(int, int)> work = [&](int l, int r) {
        if (r - l == 1)
            return std::string(cnt[l], alpha[l]);
        int m = (l + r) / 2;
        auto s = work(l, m), t = work(m, r);
        std::string a;
        int i = 0, j = 0;
        while (i < int(s.length()) && j < int(t.length())) {
            if (query(a + s[i]) == n - int(a.length()) - 1) {
                a += s[i++];
            } else {
                a += t[j++];
            }
        }
        return a + s.substr(i, s.length() - i) + t.substr(j, t.length() - j);
    };
    std::cout << "! " << work(0, 26) << std::endl;
    return 0;
}

