  std::ios::sync_with_stdio(false);
  std::cin.tie(nullptr);
  std::cout.precision(12);
  std::cerr.precision(12);
  std::mt19937 rng((std::uint_fast32_t)std::chrono::high_resolution_clock::now()
                       .time_since_epoch()
                       .count());
  constexpr int L = 128;
  constexpr auto comp = [&](const string& a, const string& b) {
    return a.size() > b.size();
  };
  priority_queue<string, vector<string>, decltype(comp)> pq(comp);
  int cnt = 0;
  auto ask = [&](const string& s) {
    if (++cnt > 850) {
      assert(false);
    }
    cout << "? " << s << endl;
    int dist;
    cin >> dist;
    return dist;
  };
  int len = 0;
  for (auto [start, end] : {pair{'a', 'z'}, {'A', 'Z'}, {'0', '9'}}) {
    for (char c = start; c <= end; ++c) {
      int dist = ask(string(L, c));
      if (L - dist > 0) {
        pq.emplace(L - dist, c);
        len += L - dist;
      }
    }
  }
  while (pq.size() > 1) {
    string a = pq.top();
    pq.pop();
    string b = pq.top();
    pq.pop();
    for (int i = 0; !b.empty(); ++i) {
      a.insert(a.begin() + i, b.front());
      int dist = ask(a);
      if (dist == len - (int)a.size()) {
        b.erase(b.begin());
      } else {
        a.erase(a.begin() + i);
      }
    }
    pq.push(a);
  }
  cout << "! " << pq.top() << endl;
  return 0;
}

int main() {
  std::ios::sync_with_stdio(false);
  std::cin.tie(nullptr);
  std::cout.precision(12);
  std::cerr.precision(12);
  std::mt19937 rng((std::uint_fast32_t)std::chrono::high_resolution_clock::now()
                       .time_since_epoch()
                       .count());
  constexpr int L = 128;
  int counter = 0;
  auto ask = [&](const string& s) {
    if (++counter > 850) {
      assert(false);
    }
    cout << "? " << s << endl;
    int dist;
    cin >> dist;
    return dist;
  };
  string abc;
  for (auto [start, end] : {pair{'a', 'z'}, {'A', 'Z'}, {'0', '9'}}) {
    for (char c = start; c <= end; ++c) {
      abc += c;
    }
  }
#ifdef TYLER
  abc = "ab";
#endif
  int n = (int)abc.size();
  uniform_int_distribution<int> dis(0, n - 1);
  int len = 0;
  vector<int> cnt;
  for (char c : abc) {
    int dist = ask(string(L, c));
    cnt.push_back(L - dist);
    len += L - dist;
  }
  string ans(len, '?');
  auto solve = y_combinator(
      [&](auto self, int low, int high, const vector<int>& total) -> void {
        debug(low, high, total);
        if (low == high) {
          for (int i = 0; i < n; ++i) {
            if (total[i] == 1) {
              ans[low] = abc[i];
              return;
            }
          }
          assert(false);
        }
        int mid = (low + high) >> 1;
        int n_left = mid - low + 1;
        vector<int> left(n);
        int sum = 0, num = 0;
        char c = abc[dis(rng)];
        for (int i = 0; i < n; ++i) {
          if (total[i] == 0) {
            c = abc[i];
          }
        }
        for (int i = 0; i < n; ++i) {
          if (total[i] > 0) {
            string s(len, c);
            for (int j = low; j <= mid; ++j) {
              s[j] = abc[i];
            }
            left[i] = len - ask(s);
            sum += left[i];
            ++num;
          }
        }
        assert((sum - n_left) % num == 0);
        int base = (sum - n_left) / num;
        vector<int> right(n);
        for (int i = 0; i < n; ++i) {
          if (total[i] > 0) {
            left[i] -= base;
            right[i] = total[i] - left[i];
          }
        }
        self(low, mid, left);
        self(mid + 1, high, right);
      });
  solve(0, len - 1, cnt);
  cout << "! " << ans << endl;
  return 0;
}

