int cnt[64];
string rec(int l, int r) {
	if (r - l == 1) return string(cnt[l], alpha[l]);
	int mid = (l + r) / 2;
	string s = rec(l, mid);
	string t = rec(mid, r);

	int pos = 0;
	int pot = 0;
	while (pot < t.size()) {
		string q(s);
		q.insert(q.begin() + pos, t[pot]);
		if (includes(q)) {
			s = q;
			++pot;
		}
		++pos;
	}
	return s;
}

