      lef |= 1LL << c;
    } else {
      rs += C[c];
      rig |= 1LL << c;
    }
  }

  string la = solve(lef);
  string ra = solve(rig);
  string res = la;

  for (int k = 0, lp = 0; k < (int)ra.size(); ++k) {
    if (lp == (int)res.size()) {
      res.insert(res.end(), ra[k]);
    } else {
      while (true) {
        res.insert(res.begin() + lp, ra[k]);
        if (query(res) == L - res.size()) {
          ++lp;
          break;
        } else {
          res.erase(res.begin() + lp);
        }
        ++lp;
      }
    }
  }

  return res;
}

