	UL tg[2] = {};

	void Solve2(char c, UL n, UL r = ~0u, UL s = 0) {
		if (r == ~0u) { r = unknowns; }
		if (n == 0) return;
		if (r == n) {
			UL t = s;
			rep(i, n) {
				t = ans.find('?', t);
				ans[t] = c;
				unknowns--;
			}
			return;
		}
		UL m = r >> 1;
		UL t = s; rep(i, m) t = ans.find('?', t) + 1;
		string tmp = ans;
		for (UL i = 0; i < L; i++) {
			if (tmp[i] == '?') {
				if (s <= i && i < t) tmp[i] = c;
				else tmp[i] = C[tg[0]];
			}
		}

		printf("? %s\n", tmp.c_str()); fflush(stdout);
		UL res; scanf("%d", &res);
		res = unknowns - res;
		Solve2(c, res, m, s);
		Solve2(c, n - res, r - m, t);
	}

	void Solve() {
		rep(i, KN) {
			printf("? ");
			rep(j, 128) printf("%c", C[i]);
			printf("\n"); fflush(stdout);
			UL res; scanf("%d", &res);
			CN[i] = 128 - res;
			L += 128 - res;
		}
		ans.assign(L, '?');
		unknowns = L;

		tg[0] = KN; tg[1] = KN;
		rep(i, KN) {
			UL k = i;
			if (CN[k] >= CN[tg[0]]) swap(k, tg[0]);
			if (CN[k] >= CN[tg[1]]) swap(k, tg[1]);
		}

		rep(i, L) {
			printf("? ");
			rep(j, L) printf("%c", (j == i) ? C[tg[1]] : C[tg[0]]);
			printf("\n"); fflush(stdout);
			UL res; scanf("%d", &res);
			if (res > L - CN[tg[0]]) { ans[i] = C[tg[0]]; unknowns--; }
			else if (res < L - CN[tg[0]]) { ans[i] = C[tg[1]]; unknowns--; }
		}

		for (UL i = 0; i < KN; i++) {
			if (i == tg[0]) continue;
			if (i == tg[1]) continue;
			Solve2(C[i], CN[i]);
		}

		printf("! %s\n", ans.c_str());
		fflush(stdout);
	}
};

