string rec(int l, int r) {
  if (l == r - 1) {
    return string(cnt[l], cs[l]);
  }
  int m = (l + r) / 2;
  string s = rec(l, m), t = rec(m, r);
  int j = 0;
  for (int i = 0; i < sz(s); i++) {
    while (j < sz(t)) {
      string ns = s;
      ns.insert(ns.begin() + i, t[j]);
      if (ask(ns) == n - sz(ns)) {
        s = ns;
        i++;
        j++;
      } else {
        break;
      }
    }
  }
  while (j < sz(t)) {
    s += t[j];
    j++;
  }
  return s;
}

