	cin.tie(0);
	ios::sync_with_stdio(0);
	cout<<fixed<<setprecision(20);

	rng(i,'0','9'+1)ls+=char(i);
	rng(i,'a','z'+1)ls+=char(i);
	rng(i,'A','Z'+1)ls+=char(i);
	int t=si(ls);
	assert(t==62);

	#ifdef LOCAL

	{
		int len=128;
		rep(i,len)target+=i2c(rand_int(0,t-1));

		dmp(target);
	}

	#endif

	vi cnt(t);
	rep(i,t){
		cnt[i]=128-ask(string(128,i2c(i)));
	}
	dmp(cnt);
	int len=accumulate(all(cnt),0);

	auto rec=[&](auto self,int l,int r)->string{
		if(r-l>1){
			string x=self(self,l,(l+r)/2);
			string y=self(self,(l+r)/2,r);

			if(x.empty())return y;
			if(y.empty())return x;

			int j=0;

			rep(i,si(x)){
				while(j<si(y)){
					string z=y.substr(0,j)+x[i]+y.substr(j);
					if(ask(z)==len-si(z))break;
					j++;
				}
				y.insert(y.bg+j,x[i]);
				j++;
			}

			return y;
		}else{
			return string(cnt[l],i2c(l));
		}
	};

	string ans=rec(rec,0,t);
	cout<<"! "<<ans<<endl;
	dmp(qs);
	#ifdef LOCAL
	assert(ans==target);
	#endif
