string combine(string s, string t) {
	string ans = "";
	while(SZ(s) and SZ(t)) {
		string test = ans; test.PB(s[0]); test += t;
		if(isSubStr(test)) {
			ans.PB(s[0]);
			s.erase(s.begin());

			debug(test, ans, s, t);

		} else {
			test = ans; test.PB(t[0]); test += s;
			ans.PB(t[0]);
			t.erase(t.begin());

			debug(test, ans, s, t);
		}		
	}
	FOR(i, 0, SZ(s)) ans.PB(s[i]);
	FOR(i, 0, SZ(t)) ans.PB(t[i]);
	return ans;
}

