				int nnum = cnxl.r - cnxl.l + sndnxl.r - sndnxl.l - lnum;
				//	cout <<"nnum "<< nnum << endl;
				if (cr.num + sndr.num == nnum) {
					cnxl.num = cr.num;
					sndnxl.num = sndr.num;
					Q.push(cnxl);
					Q.push(sndnxl);
				}
				else if (nnum == 0) {
					cnxr.num = cr.num;
					sndnxr.num = sndr.num;
					Q.push(cnxr);
					Q.push(sndnxr);
				}
