string solve(Int chs) {
  vector<int> ch;
  for (int i = 0; i < 62; ++i) {
    if (chs & (1LL << i)) {
      ch.push_back(i);
    }
  }
  if (ch.size() == 0) {
    return "";
  } else if (ch.size() == 1) {
    return string(C[ch[0]], CH[ch[0]]);
  }

  int ls = 0,  rs = 0;
  Int lef = 0, rig = 0;
  shuffle(ch.begin(), ch.end(), mt);
  for (const int c : ch) {
    if (ls <= rs) {
      ls += C[c];
      lef |= 1LL << c;
    } else {
      rs += C[c];
      rig |= 1LL << c;
    }
  }

  string la = solve(lef);
  string ra = solve(rig);
  string res = la;

  for (int k = 0, lp = 0; k < (int)ra.size(); ++k) {
    if (lp == (int)res.size()) {
      res.insert(res.end(), ra[k]);
    } else {
      while (true) {
        res.insert(res.begin() + lp, ra[k]);
        if (query(res) == L - res.size()) {
          ++lp;
          break;
        } else {
          res.erase(res.begin() + lp);
        }
        ++lp;
      }
    }
  }

  return res;
}

