inline int edit_distance(const string& a, const string& b) {
	int sza = (int)a.size(), szb = (int)b.size();
	int i, j;

	vector<vector<int>> dp(sza + 1, vector<int>(szb + 1));
	for(i = 0; i <= sza; i++) {
		dp[i][0] = i;
	}
	for(i = 0; i <= szb; i++) {
		dp[0][i] = i;
	}
	for(i = 1; i <= sza; i++) {
		for(j = 1; j <= szb; j++) {
			dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + 1;
			dp[i][j] = min(dp[i][j], dp[i - 1][j - 1] + (a[i - 1] != b[j - 1]));
		}
	}
	//cerr << sza << " " << szb << " " << dp[sza - 1][szb - 1] << "\n";
	return dp[sza][szb];
}

