vector<char> charset;

string solve(int a, int b, const vector<int>& f, int L) {
  if (a == b) return "";
  if (b - a == 1) return string(f[a], charset[a]);

  int m = (a + b) / 2;
  auto A = solve(a, m, f, L);
  auto B = solve(m, b, f, L);

  string ret;
  int j = 0;
  for (int i = 0; i < (int)A.size(); ++i) {
    while (j < (int)B.size()) {
      string q = ret;
      q.push_back(B[j]);
      q += A.substr(i);
      if (query(q) == L - q.size()) {
        ret.push_back(B[j]);
        j++;
      } else {
        break;
      }
    }
    ret.push_back(A[i]);
  }
  ret += B.substr(j);
  return ret;
}

