void solve(string chars, int l, int r){
    if(chars.size() == 1){
        for(int i = l;i < r;i++)ans[i] = chars[0];
        return;
    }
    int mid = (l + r) / 2;
    string tmp(len, chars[0]);
    int out = memo[chars[0]][0][l] + memo[chars[0]][r][len];
    int qsum = memo[chars[0]][l][r];
    for(int i = 1;i < chars.size();i++){
        char c = chars[i];
        for(int j = l;j < mid;j++)tmp[j] = c;
        memo[c][l][mid] = query(tmp) - out;
        qsum += memo[c][l][mid];
    }
    qsum -= mid - l;
    qsum /= chars.size();
    memo[chars[0]][mid][r] = qsum;
    memo[chars[0]][l][mid] = memo[chars[0]][l][r] - qsum;
    for(int i = 1;i < chars.size();i++){
        char c = chars[i];
        memo[c][l][mid] -= qsum;
        memo[c][mid][r] = memo[c][l][r] - memo[c][l][mid];
    }

    string lchars, rchars;

    for(int i = 0;i < chars.size();i++){
        char c = chars[i];
        memo[c][0][mid] = memo[c][0][l] + memo[c][l][mid];
        memo[c][mid][len] = memo[c][mid][r] + memo[c][r][len];
        if(memo[c][l][mid])lchars.push_back(c);
        if(memo[c][mid][r])rchars.push_back(c);
    }
    solve(lchars, l, mid);
    solve(rchars, mid, r);
}

