string unite(const string &s, const string &t) {
    string res = s;

    for (int i = 0, ps = 0; i < sz(t); ++i) {
        while (true) {
            string q = res.substr(0, ps);
            q += t[i];
            q += res.substr(ps, sz(res) - ps);
            if (ask(q) == n - sz(q)) {
                res = q;
                ++ps;
                break;
            } else {
                ++ps;
            }
        }
    }

    return res;
}

void solve() {
    precalc();

    if (TEST) {
        gen();
    }

    int k = sz(ch);

    vector<int> cnt(k);
    for (int i = 0; i < k; ++i) {
        string s;
        for (int j = 0; j < n; ++j) {
            s += ch[i];
        }
        cnt[i] = n - ask(s);
    }

    vector<string> str;

    int sum = 0;
    for (int i = 0; i < k; ++i) {
        sum += cnt[i];
    }
    n = sum;

    for (int i = 0; i < k; ++i) {
        if (cnt[i] == 0) {
            continue;
        }
        string s;
        for (int j = 0; j < cnt[i]; ++j) {
            s += ch[i];
        }
        str.push_back(s);
    }


    while (sz(str) > 1) {
        sort(all(str), [](const string &s, const string &t) {
            return sz(s) < sz(t);
        });

        string s = str[0];
        string t = str[1];
        reverse(all(str));
        str.pop_back();
        str.pop_back();

        str.push_back(unite(s, t));
    }

    cout << "! " << str[0] << endl;

}

