string concat(string a, string b, int n) {
	string cur = "";
	int pa = 0, pb = 0;

	while(pa < a.size() and pb < b.size()) {
		string tar = cur + a[pa] + b.substr(pb);
		if(tar.size() + query(tar) == n) {
			cur += a[pa++];
		} else {
			cur += b[pb++];
		}
	}

	while(pa < a.size()) cur += a[pa++];

	while(pb < b.size()) cur += b[pb++];

	return cur;
}

