int editdist(string& A, string& B){
    int N = A.size(), M = B.size();
    vector<vector<int>> dp(N+1, vector<int>(M+1, 1e9));
    dp[0][0] = 0;
    for(int i=0; i<=N; i++) for(int j=0; j<=M; j++){
