    }
    auto chk = [&](string s) {
        return query(s) == len - s.length();
    };
    while (ans.size() > 1) {
        stable_sort(ans.begin(), ans.end(), [&](string x, string y) {
            return x.size() ^ y.size() ? x.size() < y.size() : x < y;
        });
        string s1 = ans[0], s2 = ans[1], s3;
        ans.erase(ans.begin()), ans.erase(ans.begin());
        int pos1 = 0, pos2 = 0;
        while (pos1 < s1.length() && pos2 < s2.length()) {
            string tmp = s3; tmp.push_back(s1[pos1]);
            for (int i = pos2; i < s2.length(); i++) tmp.push_back(s2[i]);
            if (chk(tmp)) s3.push_back(s1[pos1++]);
            else s3.push_back(s2[pos2++]);
        }
        while (pos1 < s1.length()) s3.push_back(s1[pos1++]);
        while (pos2 < s2.length()) s3.push_back(s2[pos2++]);
