#define tssert(a) if(!(a)) while(1) cerr << "help";

int nq = 0;

int ask(string s){
	tssert(s.size() > 0 && s.size() <= 128);
	nq++;
	tssert(nq <= 849);
	cout << "? " << s << '\n';
	cout << flush;
