int empty_key;
string ch;
string solve(string ch){
	if(ch.length()==1){
		string s1;
		for(int i=0;i<empty_key;++i) 
			s1.push_back(ch[0]);
		int len=empty_key-query(s1);
		return s1.substr(0,len);
	}
	int m=ch.length()/2;
	string sl=solve(ch.substr(0,m));
	string sr=solve(ch.substr(m,ch.length()-m));
	for(int i=0,j=0;i<sr.length();++i){
		string ss;
		while(j<sl.length()&&query(ss=sl.substr(0,j)+sr.substr(i,1)+sl.substr(j,sl.length()-j))>=empty_key-sl.length())
			++j;
		ss=sl.substr(0,j)+sr.substr(i,1)+sl.substr(j,sl.length()-j);
		sl=ss;
		++j;
	}
	return sl;
}
