vector<char> ab;

int L;
int mem[100];
int cnt[100];

string solve(int l,int r)
{
	if (l == r)
	{
		string tmp;
		while (cnt[l]--)
			tmp += ab[l];
		return tmp;
	}
	int mid = l + r >> 1;
	string res = solve(l,mid),add = solve(mid + 1,r);
	for (int i = 0;i < res.size() && add.size();i++)
	{
		string tmp = res;
		tmp.insert(tmp.begin() + i,add[0]);
		if (EditDis(tmp) == L - tmp.size())
		{
			res = tmp;
			add.erase(add.begin());
		}
	}
	return res + add;
}

