    for (auto &ti:t) {
        for (itr = ans.insert(itr, ti) + 1; true; itr++) {
            cout << "? " << ans << endl;
            int resp; cin >> resp;
            if (len - resp == ans.size()) {
                break;
            }
            iter_swap(itr - 1, itr);
        }
