					for (int j = cnxl.l; j < cnxl.r; j++)t[j] = i;
					for (int j = 0; j < L; j++) {
						if (ans[j] != ' ')t[j] = ans[j];
					}
					int rnum = Ask(t);
					for (int j = 0; j < L; j++) {
						if (t[j] != i && ans[j] != t[j])rnum--;
					}
					int mnum = cnxl.r - cnxl.l  - rnum;
					int ll = mnum, lr = cr.num - ll, rl = nnum-mnum , rr = sndr.num - rl;
					sndnxl.num = rl, sndnxr.num = rr;
					cnxl.num = ll, cnxr.num = lr;
					Q.push(cnxl);
					Q.push(cnxr);
					Q.push(sndnxl);
					Q.push(sndnxr);
				}
				ed = true;
				break;
			}
			if (ed)continue;
			Range cnxl(cr.l, (cr.l + cr.r) / 2, 0);
			Range cnxr((cr.l + cr.r) / 2, cr.r, 0);
			string s(L, dummy);
			for (int j = cnxl.l; j < cnxl.r; j++)s[j] = i;
			for (int j = 0; j < L; j++) {
				if (ans[j] != ' ')s[j] = ans[j];
			}
			int lnum = Ask(s);
			for (int j = 0; j < L; j++) {
				if (s[j] != i&&ans[j] != s[j])lnum--;
			}
			cnxl.num = cnxl.r - cnxl.l - lnum;
			cnxr.num = cr.num - cnxl.num;
			Q.push(cnxl);
			Q.push(cnxr);
		}
	}
	cout << "! " << ans << endl;
	if(DEBUG)cout << cnt << endl;
}

