int dp(int i, int j){
	if(i == sa.size())return sb.size()-j;
	if(j == sb.size())return sa.size()-i;
	int& ret = memo[i][j];
	if(ret != -1)return ret;

	if(sa[i] == sb[j]){
		ret = dp(i+1, j+1);
	}else{
		ret = OO;
		// delete i
		ret = min(ret, dp(i+1, j) + 1);
		// insert i
		ret = min(ret, dp(i, j+1) + 1);
		// replace
		ret = min(ret, dp(i+1, j+1) + 1);
	}
	return ret;
}

