int dist(const string &s, const string &t) {
    int n = sz(s);
    int m = sz(t);
    vector<vector<int>> dp(n + 1, vector<int>(m + 1));

    for (int i = 0; i < n; ++i) {
        dp[i + 1][0] = i + 1;
    }
    for (int j = 0; j < m; ++j) {
        dp[0][j + 1] = j + 1;
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (s[i] == t[j]) {
                dp[i + 1][j + 1] = min({dp[i][j + 1] + 1, dp[i + 1][j] + 1, dp[i][j]});
            } else {
                dp[i + 1][j + 1] = min({dp[i][j + 1], dp[i + 1][j], dp[i][j]}) + 1;
            }
        }
    }

    return dp[n][m];
}

