int query(const string &s) {
	cnt++;
	assert(cnt <= Q);
	printf("? %s\n", s.c_str()); fflush(stdout);
	int ans;
	scanf("%d", &ans);
	return ans;
}

int tot;
priority_queue<pair<int, string>> pq;
void prec(char c) {
	string s(L, c);
	int len = L - query(s);
	if(len > 0) {
		s.resize(len);
		tot += len;
		pq.emplace(-len, s);
	}
}

void merge(string a, string b) {
	if(a.size() < b.size()) swap(a, b);

	for(int i = (int)a.size(); i >= 0 and !b.empty(); i--) {
		while(!b.empty()) {
			string tmp = a.substr(0, i) + b.back();
			if(i < (int)a.size()) tmp += a.substr(i);
			if(query(tmp) == tot - (int)tmp.size()) {
				a = tmp;
				b.pop_back();
			}
			else break;
		}
	}
	pq.emplace(-(int)a.size(), a);
}

int main() {

	for(char c = 'a'; c <= 'z'; c++) prec(c);
	for(char c = 'A'; c <= 'Z'; c++) prec(c);
	for(char c = '0'; c <= '9'; c++) prec(c);

	while(pq.size() > 1) {
		string a = pq.top().second; pq.pop();
		string b = pq.top().second; pq.pop();
		merge(a, b);
	}

	string ans = pq.top().second;

	assert(query(ans) == 0);

	printf("! %s\n", ans.c_str());
	fflush(stdout);
}

