 */
using V  = vector<int>;
using VV = vector<V>;

const string resource =
    "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";

int cnt[62];
int times = 0;
namespace forlocal {
    string seq;
    void init() {
        auto rnd = XorShift32();
        int n    = 128;
        // int n = 124;
        seq = string(n, '-');
        for (int i : range(n)) {
            seq[i] = resource[rnd.next_int() % resource.size()];
        }
        seq = resource + resource;
        cerr << "A: " << join(seq, "") << endl;
    }
    int get(string q) {
        VV dp(seq.size() + 1u, V(q.size() + 1, 256));
        dp[0][0] = 0;
        for (size_t i : range(seq.size() + 1)) {
            for (size_t j : range(q.size() + 1)) {
                if (i < seq.size()) {
                    // 削除
                    chmin(dp[i + 1][j], dp[i][j] + 1);
                }
                if (j < q.size()) {
                    // 挿入
                    chmin(dp[i][j + 1], dp[i][j] + 1);
                }
                if (i < seq.size() && j < q.size()) {
                    if (seq[i] == q[j]) {
                        chmin(dp[i + 1][j + 1], dp[i][j]);
                    }
                    else {
                        chmin(dp[i + 1][j + 1], dp[i][j] + 1);
                    }
                }
            }
        }
        cerr << "[" << times << "th query]" << endl;
        cerr << "A: " << join(seq, "") << endl;
        cerr << "Q: " << join(q, "") << endl;
        cerr << ">> " << dp.back().back() << endl;

        return dp.back().back();
    }
