        len += tmp;
        if (tmp) ans.push_back(string(tmp, c));
    }
    auto chk = [&](string s) {
        return query(s) == len - s.size();
    };
    while (ans.size() > 1) {
        stable_sort(ans.begin(), ans.end());
        string s1 = ans[0], s2 = ans[1], s3;
        ans.erase(ans.begin()), ans.erase(ans.begin());
        int pos1 = 0, pos2 = 0;
        while (pos1 < s1.size() || pos2 < s2.size()) {
            if (pos1 < s1.size() && chk(s3 + string(1, s1[pos1]))) {
                s3.push_back(s1[pos1++]);
            } else {
                s3.push_back(s2[pos2++]);
            }
        }
        ans.push_back(s3);
    }
