size_t levenshtein_distance(char* s1, char *s2, int l1, int l2)
{
   int i,j,t,track;
   int dist[130][130];
   //take the strings as input
   // char s1[] = "tutorials";
   // char s2[] = "point";
   //stores the lenght of strings s1 and s2
   // l1 = strlen(s1);
   // l2= strlen(s2);
   for(i=0;i<=l1;i++) {
      dist[0][i] = i;
   }
   for(j=0;j<=l2;j++) {
      dist[j][0] = j;
   }
   for (j=1;j<=l1;j++) {
      for(i=1;i<=l2;i++) {
         if(s1[i-1] == s2[j-1]) {
            track= 0;
         } else {
            track = 1;
         }
         t = min((dist[i-1][j]+1),(dist[i][j-1]+1));
         dist[i][j] = min(t,(dist[i-1][j-1]+track));
      }
   }
   // cout<<"The Levinstein distance is:"<<dist[l2][l1];
   return dist[l2][l1];
}

