inline int read(){
	int x=0,f=1;
	char c=getchar();
	while(c<'0'||c>'9'){
		if(c=='-')f=-1;
		c=getchar();
	}
	while(c>='0'&&c<='9'){
		x=(x<<1)+(x<<3)+c-'0';
		c=getchar();
	}
	return x*f;
}
int cnt=0;
char ch[66];
vector<char> dfs(int l,int r){
	vector<char> myh;
	if(l==r){
		printf("? ");
		for(int i=1;i<=len;++i){
			putchar(ch[l]);
		}
		putchar('\n');
		fflush(stdout);
		int qwq=read();
		while(qwq--)myh.push_back(ch[l]);
		return myh;
	}
	int mid=(l+r)>>1;
	vector<char> L=dfs(l,mid),R=dfs(mid+1,r);
	int j=0;
	for(int i=0;i<(int)L.size();++i){
		while(j<(int)R.size()){
			printf("? ");
			for(auto x:myh)putchar(x);
			putchar(R[j]);
			for(int k=i;k<(int)L.size();++k){
				putchar(L[k]);
			}
			putchar('\n');
			fflush(stdout);
			int qwq=read();
			int o=L.size()+j+1;
			if(len-qwq!=o)break;
			myh.push_back(R[j]);
			++j;
		}
		myh.push_back(L[i]);
	}
	for(;j<(int)R.size();++j)myh.push_back(R[j]);
	return myh;
}
