string Merge(string a, string b)
{
    vector<string> before(a.size() + 1);
    int j = 0;
    for (int i = 0; i < b.size();)
    {
        string s = "";
        for (int k = 0; k < a.size(); k++)
        {
            s += before[k];
            if (j == k) s += b[i];
            s += a[k];
        }
        s += before.back();
        if (j == a.size()) s += b[i];
        int x = query(s);
        if (x == len - s.size())
        {
            before[j] += b[i];
            i++;
        }
        else
        {
            j++;
        }
    }
    string res = "";
    for (int i = 0; i < a.size(); i++) res += before[i], res += a[i];
    res += before.back();
    //cout << "Merge of " << a << " " << b << " = " << res << endl;
    return res;
}

