    for (char c = start; c <= end; ++c) {
      int dist = ask(string(L, c));
      if (L - dist > 0) {
        pq.emplace(L - dist, c);
      }
    }
  }
  while (pq.size() > 1) {
    string a = pq.top();
    pq.pop();
    string b = pq.top();
    pq.pop();
    for (int i = 0; !b.empty(); ++i) {
      a.insert(a.begin() + i, b.front());
      int dist = ask(a);
