const int L = 128, Sig = 62;

inline char itoc(int x) { return x < 10 ? x + '0' : x < 36 ? x - 10 + 'A' : x - 36 + 'a'; }

int nums[Sig], len;

std::string Solve(int l, int r) {
	std::string ret;
	if (r - l == 1) {
		int x = nums[l];
		while (x) ret += itoc(l), --x;
		return ret;
	}
	int mid = (l + r) / 2;
	std::string left = Solve(l, mid);
	std::string right = Solve(mid, r);
	int lp = 0, rp = 0;
	while (lp < (int)left.length() && rp < (int)right.length()) {
		printf("? ");
		std::cout << ret << right[rp] << left.substr(lp);
		putchar('\n'), fflush(stdout);
		int num;
		scanf("%d", &num);
		if (num == len - ((int)left.length() + rp + 1)) ret += right[rp++];
		else ret += left[lp++];
	}
	return ret + left.substr(lp) + right.substr(rp);
}

int main() {
	for (int i = 0; i < Sig; ++i) {
		printf("? ");
		for (int j = 0; j < L; ++j) putchar(itoc(i));
		putchar('\n'), fflush(stdout);
		int num;
		scanf("%d", &num);
		nums[i] = L - num;
		len += nums[i];
	}
	std::string ans = Solve(0, Sig);
	std::cout << "! " << ans << std::endl;
	return 0;
}

