				for (int j = cnxl.l; j < cnxl.r; j++)s[j] = i;
				for (int j = sndnxl.l; j < sndnxl.r; j++)s[j] = i;
				for (int j = 0; j < L; j++) {
					if (ans[j] != ' ')s[j] = ans[j];
				}
				int lnum = L-Ask(s);
				int nnum = lnum;
				for (int j = 0; j < L; j++)nnum -= s[j] == ans[j];
			//	int nnum = sndnxl.r - sndnxl.l - lnum;

				if (cr.num + sndr.num == nnum) {
					cnxl.num = cr.num;
					sndnxl.num = sndr.num;
					Q.push(cnxl);
					Q.push(sndnxl);
				}
				else if (nnum == 0) {
					cnxr.num = cr.num;
					sndnxr.num = sndr.num;
					Q.push(cnxr);
					Q.push(sndnxr);
				}
				else {
					string t(L, dummy);
					for (int j = cnxl.l; j < cnxl.r; j++)t[j] = i;
					for (int j = 0; j < L; j++) {
						if (ans[j] != ' ')t[j] = ans[j];
					}
					int rnum = L-Ask(t);
					int mnum =  rnum;
					for(int j=0;j<L;j++)mnum -= t[j] == ans[j];
					int ll = mnum, lr = cr.num - ll, rl = nnum-mnum , rr = sndr.num - rl;
					sndnxl.num = rl, sndnxr.num = rr;
					cnxl.num = ll, cnxr.num = lr;
					Q.push(cnxl);
					Q.push(cnxr);
					Q.push(sndnxl);
					Q.push(sndnxr);
				}
				ed = true;
				break;
			}
			if (ed)continue;
			Range cnxl(cr.l, (cr.l + cr.r) / 2, 0);
			Range cnxr((cr.l + cr.r) / 2, cr.r, 0);
			string s(L, dummy);
			for (int j = cnxl.l; j < cnxl.r; j++)s[j] = i;
			for (int j = 0; j < L; j++) {
				if (ans[j] != ' ')s[j] = ans[j];
			}
			int lnum = L-Ask(s);
			cnxl.num = lnum;
			for (int j = 0; j < L; j++)cnxl.num -= s[j] == ans[j];
			cnxr.num = cr.num - cnxl.num;
		//	cout << cnxl.num << " " << cnxr.num << endl;
			Q.push(cnxl);
			Q.push(cnxr);
		}
	}
	cout << "! " << ans << endl;
	if(DEBUG)cout << cnt << endl;
}

