	inline bool friend operator < (node a,node b){return a.len>b.len;}
};
inline bool check(node &x){
	printf("? %s\n",x.s);
	fflush(stdout);
	return read()==n-x.len;
}
inline void ins(char *s,int pos,char x,int len){
	for(int i=len;i>pos;--i) s[i]=s[i-1]; s[pos]=x;
}
inline node merge(node &x,node &y){
	node ans; ans=x;
	for(int i=0,j=0;i<y.len;++i){
		++ans.len;
		node rec=ans;
		for(int pos=j;pos<ans.len;++pos){
			ins(ans.s,pos,y.s[i],ans.len);
			if(!check(ans)) ans=rec;
			else{j=pos+1;break;}
		}
	}
	return ans;
}

