int len;

bool contains(string s){
	if(s.size() == 0) return true;
	if(s.size() > 128) return false;
	int r = ask(s);
	if(r == len - (int)s.size()) return true;
	assert(r > len - (int)s.size());
	return false;
}

int main(){
	ios_base::sync_with_stdio(false), cin.tie(nullptr);
	string all;
	for(char c = 'a'; c <= 'z'; c++) all += c;
	for(char c = 'A'; c <= 'Z'; c++) all += c;
	for(char c = '0'; c <= '9'; c++) all += c;
	mt19937 mt(49);
	shuffle(all.begin(), all.end(), mt);
	assert(all.size() == 62);
	all = "abc";
	cerr << all << '\n';
	{
		char c = all.front();
		if(ask(string(128, c)) == 128){
			// does not contain
			len = ask(string(1, c));
		} else {
			len = ask(string(1, c)) + 1;
		}
	}
	string cur = "";
	for(char c : all){
		string pref = cur;
		string suff = "";
		while(true){
			if(!contains(string(1, c) + suff)) break;
			int s = 0;
			int e = (int)pref.size() + 1;
			while(s + 1 < e){
				int m = (s + e) / 2;
				if(contains(pref.substr(0, m) + string(1, c) + suff)){
					s = m;
				} else {
					e = m;
				}
			}
			suff = string(1, c) + pref.substr(s) + suff;
			pref = pref.substr(0, s);
		}
		cur = pref + suff;
	}
	answer(cur);
	assert((int)cur.size() == len);
}

