void searchChar(int cc, int x){
	int leftp = 1;
	for (int i = 0; i < L; ++i) q[i] = cc;
	int found = 0;
	while (found < num[x]){
		int l = leftp, r = L;
		while (l < r){
			for (int i = 0; i < L; ++i) q[i] = cc;
			//cerr << l << ' ' << r << '\n';
			int m = (l+r)/2;
			for (int t = 0; t < m; ++t){
				q[t] = x;
			}
			int a = guess(L);
			if (a < L - cval[m] + found){
				r = m;
			}
			else{
				l = m+1;
			}
		}
		ans[l] = x;
		leftp = l+1;
		found++;
	}
}

