inline void solve(int u,int l,int r){
	if (l==r){
		For(i,1,cnt) if (tot[u][i]) ans[l]=s[i];
		return;
	}
	int mid=l+r>>1,S=0,S2=0,L=0;
	For(i,1,cnt) if (tot[u][i]){
		L=i;break;
	}
	vector<int>ans(cnt+1);
	ans[L]=tot[u][L],S=tot[u][L],S2=1;
