		ans[i]=(n-Query(s))-pre[u][L]-suf[u][i],S+=ans[i],++S2;
	}
	tot[u<<1][L]=(S-(r-mid))/S2;
	For(i,1,cnt) if (tot[u][i]) tot[u<<1^1][i]=ans[i]-tot[u<<1][L];
	For(i,L+1,cnt) if (tot[u][i]) tot[u<<1][i]=tot[u][i]-tot[u<<1^1][i];
	For(i,1,cnt){
		suf[u<<1][i]=suf[u][i]+tot[u<<1^1][i];
		suf[u<<1^1][i]=suf[u][i];
		pre[u<<1^1][i]=pre[u][i]+tot[u<<1][i];
		pre[u<<1][i]=pre[u][i];
	}
	solve(u<<1,l,mid),solve(u<<1^1,mid+1,r);
}
