string merge_sort(int l,int r){
	if(l==r){
		string ret="";
		for(int i=0;i<cnt[l];i++)ret.push_back(rev(l));
		return ret;
	}
	int mid=(l+r)/2;
	string s1=merge_sort(l,mid);
	string s2=merge_sort(mid+1,r);
	int pos=0;
	string ret="";
	if(s1.size()>s2.size())swap(s1,s2);
	for(int i=0;i<s1.size();i++){
		while(pos<s2.size()&&Get(ret,s2,pos,s1[i])==0)
		ret.push_back(s2[pos]),pos++;
		ret.push_back(s1[i]);
	}
	while(pos<s2.size())ret.push_back(s2[pos++]);
	return ret;
}
