		else	qr[tot++]=s[pr++];
	}
	while(pl<=pre[mid]-1)	qr[tot++]=s[pl++];
	while(pr<=r)	qr[tot++]=s[pr++];
	for(int i=0;i<tot;i++)	s[l+i]=qr[i];
}
