string solve(vector<string>& vec, int l, int r) {
    if (l > r) return "";
    if (l == r) return vec[l];
    int m = (l+r)/2;
    string p = solve(vec,l,m), q = solve(vec,m+1,r), res = "";
    while (!p.empty() && !q.empty()) {
        string s = res + q[0] + p;
        if (ask(s) == L-SZ(s)) {
            res += q[0];
            q.erase(q.begin());
        } else {
            res += p[0];
            p.erase(p.begin());
        }
    }
    res += p + q;
    return res;
}

