string merge(string s, string t) {
    string ans = "";
    while (!s.empty() && !t.empty()) {
        string tmp = ans + t[0] + s;
        if (ask(tmp) != len - (int)tmp.size()) {
            ans += s[0];
            s.erase(0, 1);
        } else {
            ans += t[0];
            t.erase(0, 1);
        }
    }
    return ans + s + t;
}

