					int mnum = cnxl.r - cnxl.l + sndnxr.r - sndnxr.l - rnum;
				//	cout << nnum << " " << mnum << endl;
					int rl=0, rr=0;
					if (nnum < mnum)rr = mnum - nnum;
					else rl = nnum - mnum;
					int add = sndr.num - (rr + rl);
					rr += add / 2, rl += add / 2;
					sndnxl.num = rl, sndnxr.num = rr;
					int ll = nnum - rl;
					int lr = cr.num - ll;
					cnxl.num = ll, cnxr.num = lr;
					Q.push(cnxl);
					Q.push(sndnxl);
					Q.push(cnxr);
					Q.push(sndnxr);
				}
				ed = true;
			//	cout << "KO" << endl;
				break;
			}
			if (ed)continue;
			Range cnxl(cr.l, (cr.l + cr.r) / 2, 0);
			Range cnxr((cr.l + cr.r) / 2, cr.r, 0);
			string s(L, 'a');
			for (int j = cnxl.l; j < cnxl.r; j++)s[j] = i;
			int lnum = Ask(s);
			for (int j = 0; j < L; j++) {
				if (s[j] == dummy&&ans[j] != s[j])lnum--;
			}
			cnxl.num = cnxl.r - cnxl.l - lnum;
			cnxr.num = cr.num - cnxl.num;
			Q.push(cnxl);
			Q.push(cnxr);
		}
	}
	cout << "! " << ans << endl;
	if(DEBUG)cout << cnt << endl;
}

