    int ret=(mid+sum)/(num+1);
    edit[0][mid]=edit[0][0]+ret;
    rep(i,sz-1)
    {
      if(edit[i+1][l]==edit[i+1][r]){continue;}
      edit[i+1][mid]=edit[i+1][0]-letter[i+1]+ret;
    }
  }
  else
  {
    sum+=edit[j][l];
