	// 	alphaBet.push_back('0' + i);
	// }
}

vector<string> f;
const int L = 128;
int totalL = 0;
int queryN = 0;
int maxQueryN = 850;

int makeQuery(string s) {
	cout << "? " << s << endl;
	int ans;
	cin >> ans;
	queryN += 1; 
	// if (queryN >= maxQueryN) {
