inline int rd()
{
	int x=0;char ch=getchar();
	for (;ch<'0'||ch>'9';ch=getchar());
	for (;ch>='0'&&ch<='9';ch=getchar()) x=x*10+ch-'0';
	return x;
}

inline void build(int o,int l,int r)
{
	if (l==r) { s[o]=string(len[l],id[l]);return; }
	int mid=(l+r)>>1;
	build(o<<1,l,mid);build(o<<1|1,mid+1,r);
	string res;int now=0;
	for (int i=0;i<s[o<<1|1].length();i++)
	{
		while (now<s[o<<1].length())
		{
			string str=res;str.push_back(s[o<<1|1][i]);
			str=str+s[o<<1].substr(now,s[o<<1].length()-now);
			cout<<"? "<<str<<endl;
			fflush(stdout);
			int hh=rd();
			if (s[o<<1].length()+i+1+hh>n) res.push_back(s[o<<1][now++]);
			else break;
		}
		res.push_back(s[o<<1|1][i]);
	} 
	s[o]=res+s[o<<1].substr(now,s[o<<1].length()-now);
}

