	string s = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ012345678abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ01234567899", t;
	int dp[maxn][maxn];
	int f(int i, int j) {
		if(i == s.size() || j == t.size()) return max(t.size()-j, s.size()-i);
		if(dp[i][j] != -1) return dp[i][j];
		return dp[i][j] = min({f(i+1, j)+1, f(i, j+1)+1, f(i+1, j+1) + (s[i]!=t[j])});
	}
	int query(string _t) {
		t = _t;
		memset(dp, -1, sizeof dp);
		return f(0, 0);
	}
};
int n, left;
string d;
bitset<maxn> g;
char itc(int x) {
	for(auto c : {'a', 'A', '0'})
		if(x < 26) return c+x;
		else x -= 26;
}
map<string, int> meme;
int qry = 0;
int ask(string t) {
	if(meme.count(t)) return meme[t];
	++qry;
	//assert(++qry < 850);
	int x;
	cout << "? " << t << endl;
	if(local::L) x = local::query(t);
	else cin >> x;
	if(local::L) cout << "> " << x << endl;
	return meme[t] = x;
}
string fill(int l, int r, char c, int uwu = 0) {
	string res = uwu ? string(n, '.') : d;
	while(l <= r) {
		if(!g[l]) res[l] = c;
		l++;
	}
	return res;
}
int count(string s) {
	int t = left - ask(s);
	return t;
}
void solve(int l, int r, int cnt, char c) {
	if(cnt == 0) return;
	if(l > r) return;
	if(l == r) {
		if(cnt) {
			g[l] = 1;
			d[l] = c;
			left--;
		}
		return;
	}
	int mid = (l+r)/2;
	int x = count(fill(l, mid, c));
	solve(l, mid, x, c);
	solve(mid+1,r,cnt-x,c);
}
string insert(string a, int p, char c) {
	return a.substr(0, p) + string(1, c) + a.substr(p);
}
int complete(string &t, int p, char x, int v) {
	for(int i = 1<<7; i>>=1;) {
		if(t.size()+i>128) continue;
		string a = t.substr(0, p) + string(i, x) + t.substr(p);
		if(ask(a) == n-v) t = a, p += i;
	}
	g[p] = 1;
	left--;
	return p+1;
}
int main() {
	cin.tie(0)->sync_with_stdio(0);
	n = ask("a");
	if(n != 128 && ask(string(n+1, 'a')) < n+1) n++;
	left = n;
	vector<int> cnt(63);
	cnt[62] = 228;
	int f = 62, s = 62;
	for(int i = 0; i < 62; i++) {
		cnt[i] = count(fill(0, n-1, itc(i), 1));
		if(cnt[f] > cnt[i]) s = f, f = i;
		else if(cnt[s] > cnt[i]) s = i;
	}
	if(cnt[f] == 0) {
		d = string(n, itc(f));
	} else {
		int cf = cnt[f], cs = cnt[s];
		int q = n - cf - cs, v = cf + cs;
		string T(cf, itc(f));
		for(int i = T.size(); i >= 0; i--) {
			while(ask(T) > ask(insert(T, i, itc(s)))) T = insert(T, i, itc(s));
		}
		int i = 0;
		while(i < T.size()) {
			i = complete(T, i, T[i]^itc(f)^itc(s), v);
		}
		d = T;
		while(d.size() < n) d.pb(itc(f));
		for(int i = 0; i < n; i++) if(!g[i]) d[i] = itc(f);
	}
	if(local::L) {
		//cerr << qry << " " << d << endl;
		//for(int i = 0; i < n; i++) cerr << g[i] << " ";cerr << endl;
	}
	char c;
	for(int i = 0; i < 62; i++) {
		if(i != f && i != s)
		c = itc(i), solve(0, n-1, cnt[i], c);
	}
	cout << "! " << d << endl;
	if(local::L) cerr << qry << endl;
	return 0;
}

