	for(int i=0;i<=S.size();i++)
	{
		for(int j=0;j<=T.size();j++)
		{
			if(i<S.size()&&j<T.size())
			{
				dp[i+1][j+1]=min(dp[i+1][j+1],dp[i][j]+(S[i]==T[j]?0:1));
			}
			if(i<S.size())
			{
				dp[i+1][j]=min(dp[i+1][j],dp[i][j]+1);
