struct X {
    int l, r, num;
    X() {}
    X(int _l, int _r, int _num) {
        l   = _l;
        r   = _r;
        num = _num;
    }
};

string getInvalidString(int n) {
    string ret(n, '-');
    int min_i = distance(cnt, min_element(cnt, cnt + 62));
    string q(n, resource[(min_i + 1) % 62]);
    int def = n - query(q);
    for (int i : range(n)) {
        string s    = q;
        s[i]        = resource[min_i];
        int matched = n - query(s);
        if (matched > def) {
            ret[i] = q[i];
        }
        else {
            ret[i] = s[i];
        }
    }
    return ret;
}
int main() {
    init();
    /* write here */

    // 文字数特定 62クエリ
    for (int i : range(62)) {
        cnt[i] = 128 - query(string(128, resource[i]));
        len += cnt[i];
    }
    string result(len, '-');

    string invalid = getInvalidString(len);
    assert(query(invalid) == len);
    vector<int> ord(62);
    iota(ALL(ord), 0);
    sort(ALL(ord), [](int l, int r) { return cnt[l] < cnt[r]; });
    for (int i : ord) {
        stack<X> s;
        s.push(X(0, len, cnt[i]));
        while (s.size() > 0) {
            X cur = s.top();
            s.pop();
            if (cur.num == 0) continue;

            int rest = 0;
            for (int k : range(cur.l, cur.r)) {
                if (result[k] == '-') {
                    rest++;
                }
            }
            if (rest == cur.num) {
                for (int k : range(cur.l, cur.r)) {
                    if (result[k] == '-') {
                        result[k] = resource[i];
                    }
                }
                continue;
            }

            int m    = (cur.l + cur.r) / 2;
            string q = invalid;
            for (int k : range(cur.l, m)) {
                q[k] = resource[i];
            }
            int v = len - query(q);
            s.push(X(cur.l, m, v));
            s.push(X(m, cur.r, cur.num - v));
        }
    }
    for (auto &c : result) {
        if (c == '-') {
            c = resource[ord[61]];
        }
    }
    query(result);
    return 0;
}

