const int N = 128;
int n;
const int m = 62;

bool issub(string s)
{
    return (qry(s) == n - s.size());
}

int q[m];

string rec(int l, int r)
{
    if (l == r)
    {
        string s = "";
        for (int i = 0; i < q[l]; ++i)
            s += itoc(l);
        return s;
    }
    int m = (l + r) / 2;
    string a = rec(l, m);
    string b = rec(m + 1, r);
    string s = "";
    while (!a.empty() && !b.empty())
    {
        reverse(all(a));
        if (issub(s + a.back() + b))
        {
            s += a.back();
            a.pop_back();
            reverse(all(a));
        }
        else
        {
            reverse(all(a));
            reverse(all(b));
            s += b.back();
            b.pop_back();
            reverse(all(b));
        }
    }
    s += a;
    s += b;
    return s;
}

void solv()
{
    for (int i = 0; i < m; ++i)
    {
        string s = "";
        for (int j = 0; j < N; ++j)
            s += itoc(i);
        q[i] = N - qry(s);
    }
    for (int i = 0; i < m; ++i)
        n += q[i];
    cout << "! " << rec(0, m - 1) << endl;
}

