int L = 128;

string join(const vector<string> &v, int l, int r, int n) {
    if (l == r) return v[l];
    int mid = (l+r)/2;

    string a = join(v, l, mid, n);
    string b = join(v, mid+1, r, n);

    string ans = a;
    for (int i=0, cur=0; i<b.size(); cur++) {
        string nw = ans;
        nw.insert(nw.begin()+cur, b[i]);
        if (query(nw) == n-nw.size())   ans = nw, i++;
    }
    return ans;
}

