    for (char c: alphabet) {
        int x = query(string(L, c));
        if (x < L) v.push_back(string(L-x, c));
        sum += L-x;
    }

    string ans = join(v, 0, v.size()-1, sum);
    cout<<"! "<<ans<<endl;
}

