int dis(string s,string t){
    int n = s.size(), m = t.size();
    for(int i=0;i<=n;i++){
        for(int j=0;j<=m;j++){
            if(i==0||j==0){
                f[i][j] = max(i,j); continue;
            }
            f[i][j] = 1e9;
            f[i][j] = min(f[i][j],f[i-1][j-1]+(s[i-1]!=t[j-1]));
            f[i][j] = min(f[i][j],f[i-1][j]+1);
            f[i][j] = min(f[i][j],f[i][j-1]+1);
        }
    }
