node merge(node a,node b){
//  	swap(a,b);
    string s = a.s;
    int pos = 0;
    for(char c: b.s){
        while(1){
            string t = s.substr(0,pos) + c + s.substr(pos);
            pos++;
            if(check(t)){
                s = t;
                break;
            }
        }
    }
    return (node){s};
}
