const int MAXN = 211;
int dp[MAXN][MAXN];

template<class Iter> int levenshtein(Iter s_first, Iter s_last, Iter t_first, Iter t_last, int cost=1) {
    int n = distance(s_first, s_last);
    int m = distance(t_first, t_last);
    REP (i, n+1) dp[i][0] = i;
    REP (j, m+1) dp[0][j] = j;
    REP (i, n) REP (j, m) {
	int c = cost;
	if (*(s_first+i) == *(t_first+j)) c = 0;
	dp[i+1][j+1] = min(dp[i][j] + c, min(dp[i][j+1], dp[i+1][j]) + 1);
    }
    return dp[n][m];
}

int levenshtein(const string &s, const string &t) {
    return levenshtein(s.begin(), s.end(), t.begin(), t.end());
}

