            for (auto &it : fix) q[it.first] = it.second;
            int v = len - query(q) - (int)fix.size();
            s.push(X(cur.l, m, v));
            s.push(X(m, cur.r, cur.num - v));
        }
    }
    query(result);
    return 0;
}

