void initF() {
	makeAlphaBet();
	int n = alphaBet.size();
	f = vector<string>(n);
	for (int i = 0; i < n; ++i) {
		f[i] = "";
	}
	totalL = 0;
	for (int i = 0; i < n; ++i) {
		string query = "";
		for (int j = 0; j < L; ++j) {
			query.push_back(alphaBet[i]);
		}
		int ans = makeQuery(query);
		f[i] = query.substr(0, L - ans);
		totalL += (L - ans);
	}
}

string combine(string a, string b) {
	if (a.length() == 0) {
		return b;
	}
	if (b.length() == 0) {
		return a;
	}
	int curA = 0, curB = 0;
	string res = "";
	int aL = a.length(), bL = b.length();
	while (curA < aL || curB < bL) {
		if (curA >= aL) {
			res.push_back(b[curB]);
			++curB;
			continue;
		}
		if (curB >= aL) {
			res.push_back(b[curA]);
			++curA;
			continue;
		}
		res.push_back(a[curA]);
		res.push_back(b[curB]);
		int ans = makeQuery(res);
		if (ans == totalL - res.length()) {
			++curA; res.pop_back(); continue;
		} else {
			res.pop_back(); res.pop_back();
			res.push_back(b[curB]); ++curB;
			continue;
		}
	}
	return res;
}

string getF(int l, int r) {
	if (l == r) {
		return f[l];
	}
	int mid = (l + r) / 2;
	string left = getF(l, mid);
	string right = getF(mid + 1, r);
	return combine(left, right);
}

int main() {
	initF();
	makeDecision(getF(0, alphaBet.size() - 1));
	return 0;
}

