int ask(const string& s) {
    int ans;

    printf("? %s\n", s.c_str());
    fflush(stdout);

    scanf("%d", &ans);

    return ans;
}

int main() {
    int n = 0, i;
    vector<char> v;
    vector<string> w;

    for (i = 0; i < 26; i++) v.push_back('a' + i);
    for (i = 0; i < 26; i++) v.push_back('A' + i);
    for (i = 0; i < 10; i++) v.push_back('0' + i);

    for (i = 0; i < v.size(); i++) {
        int x = 128 - ask(string(128, v[i]));

        if (x > 0) {
            n += x;
            w.push_back(string(x, v[i]));
        }
    }

    while (w.size() > 1) {
        string s, t, st = "";

        sort(w.begin(), w.end(), [](const string& s1, const string& s2) {return s1.size() > s2.size();});

        s = w.back();
        w.pop_back();
        t = w.back();
        w.pop_back();

        while (s.size() > 0 && t.size() > 0) {
