         }
         t = min((dist[i-1][j]+1),(dist[i][j-1]+1));
         dist[i][j] = min(t,(dist[i-1][j-1]+track));
      }
   }
   // cout<<"The Levinstein distance is:"<<dist[l2][l1];
   return dist[l2][l1];
}

