const int L = 128;
const int Q = 850;

int main() {
	using namespace std;
	ios_base::sync_with_stdio(false), cin.tie(nullptr);

	string chars =
		"ABCDEFGHIJKLMNOPQRSTUVWXYZ"
		"abcdefghijklmnopqrstuvwxyz"
		"0123456789";
	assert(chars.size() == 62);
	const bool TEST = true;

	std::random_device rd;
	mt19937 mt(rd());
	string TEST_ANS;
	for (int i = 0; i < L; i++) {
		TEST_ANS += chars[mt() % chars.size()];
	}

	int QUERY_CNT = 0;

	auto query = [&](string q) -> int {
		QUERY_CNT++;
		cout << '?' << ' ' << q << '\n' << flush;
		int v; cin >> v;
		return v;
	};

	auto is_subseq = [&](string q) -> bool {
		if (TEST) {
			QUERY_CNT++;
			int i = 0;
			for (char c : TEST_ANS) {
				if (c == q[i]) {
					i++;
					if (i == int(q.size())) return true;
				}
			}
			return false;
		}
		return query(q) == L - int(q.size());
	};

	auto get_cnt = [&](char c) -> int {
		if (TEST) {
			QUERY_CNT++;
			int res = 0;
			for (char v : TEST_ANS) {
				res += v == c;
			}
			return res;
		}
		return L - query(string(L, c));
	};

	string ans; ans.reserve(L);
	for (char c : chars) {
		int cnt = get_cnt(c);
		int last = -1;
		for (int i = 0; i < cnt; i++) {
			int mi = last, ma = int(ans.size());
			while (ma - mi > 1) {
				int md = (mi + ma) / 2;
				if (is_subseq(string(i+1, c) + ans.substr(md))) {
					ma = md;
				} else {
					mi = md;
				}
			}
			ans.insert(ans.begin()+ma, c);
			last = ma;
		}
	}

	//cerr << TEST_ANS << '\n';
	//cerr << ans << '\n';
	if (TEST) {
		assert(ans == TEST_ANS);
	}
	cerr << QUERY_CNT << '\n';
	assert(QUERY_CNT <= Q);

	cout << '!' << ' ' << ans << '\n';
	return 0;
}

