			chmin(f[i][j], get(i, j - 1) + 1);
			if(s[i] == t[j]) chmin(f[i][j], get(i - 1, j - 1));
			else chmin(f[i][j], get(i - 1, j - 1) + 1);
		}
	return f.back().back();
}

