string solve(int l, int r) {
	if(l == r) return string(occ[l], bet[l]);
	else {
		int m = (l + r) / 2;
		string s1 = solve(l, m), s2 = solve(m + 1, r);
		string s;
		while(s1.size() && s2.size()) {
			string q = s + s2[0] + s1;
			int r = query(q);
			r -= len - (int)q.size();
			if(r == 0) {
				s += s2[0];
				s2 = s2.substr(1);
			} else {
				s += s1[0];
				s1 = s1.substr(1);
			}
		}
		return s + s1 + s2;
	}
}

