                if (j < q.size()) {
                    // 挿入
                    chmin(dp[i][j + 1], dp[i][j] + 1);
                }
                if (i < seq.size() && j < q.size()) {
                    if (seq[i] == q[j]) {
                        chmin(dp[i + 1][j + 1], dp[i][j]);
                    }
                    else {
                        chmin(dp[i + 1][j + 1], dp[i][j] + 1);
                    }
                }
