string answer;
string alpha;
int n;
int a;
int p[A][N];
int cur[A];

void solve(int l, int r) {
	if (r - l == 1) {
		char add = 0;
		for (int i = 0; i < a; ++i) {
			if (p[i][l] < p[i][r]) {
				assert(!add);
				add = alpha[i];
			}
		}
		assert(add);
		answer += add;
		return;
	}
	int sum = 0;
	int m = (l + r) / 2;
	int z = 0;
	vector<int> ex;
	for (int i = 0; i < a; ++i) {
		if (p[i][l] < p[i][r]) {
			z = i;
			ex.push_back(i);
		} else {
			p[i][m] = p[i][l];
			sum -= p[i][l];
		}
	}
	assert(z);
	for (int i : ex) {
		if (i == z) {
			cur[i] = 0;
			continue;
		}
		string s = string(m, alpha[i]) + string(n - m, alpha[z]);
		sum += cur[i] = query(s) - (n - p[z][n]);
	}
	assert((sum + m) % ex.size() == 0);
	int bad = (sum + m) / (int)ex.size();
	for (int i : ex) {
		p[i][m] = bad - cur[i];
	}
	solve(l, m);
	solve(m, r);
}

