const int N = 128;
int n;
const int m = 62;

bool issub(string s)
{
    if (qry(s) == n - s.size())
        return true;
    return false;
}

int q[m];

string rec(int l, int r)
{
    if (l == r)
    {
        string s = "";
        for (int i = 0; i < q[l]; ++i)
            s += itoc(l);
        return s;
    }
    int m = (l + r) / 2;
    string a = rec(l, m);
    string b = rec(m + 1, r);
    string s = "";
    while (!a.empty() || !b.empty())
    {
        if (a.empty())
        {
            reverse(all(b));
            s += b.back();
            b.pop_back();
            reverse(all(b));
            continue;
        }
        if (b.empty())
        {
            reverse(all(a));
            s += a.back();
            a.pop_back();
            reverse(all(a));
            continue;
        }
        reverse(all(a));
        if (issub(s + a.back() + b))
        {
            s += a.back();
            a.pop_back();
            reverse(all(a));
        }
        else
        {
            reverse(all(a));
            reverse(all(b));
            s += b.back();
            b.pop_back();
            reverse(all(b));
        }
    }
    return s;
}

void solv()
{
    for (int i = 0; i < m; ++i)
    {
        string s = "";
        for (int j = 0; j < N; ++j)
            s += itoc(i);
        q[i] = N - qry(s);
    }
    for (int i = 0; i < m; ++i)
        n += q[i];
    cout << "! " << rec(0, m - 1) << endl;
}

