				if(ans[i-1] == s[j-1]) f[i][j] = f[i-1][j-1];
				else f[i][j] = min(f[i-1][j-1], min(f[i-1][j], f[i][j-1])) + 1;
			}

		cout << "Result: " << f[n][m] << "\n\n";
		return f[n][m];
	}

