                    s += ans[j];
                    s += x[j];
                }
                if (query(s) != l - int(s.size())) {
                    ans[p].pop_back();
                    p++;
                    continue;
                }
                break;
            }
            if (p == xn) ans[p] += y[i];
        }
        string s;
        for (int j = 0; j < xn; j++) {
            s += ans[j];
            s += x[j];
