static inline int ask(int u,int i,int j)
{
  int len=diff;
  printf("? ");rep(k,sz[u]){len--;putchar(decode(pw[u][k]));}len--;putchar(decode(pw[u<<1][i]));
  rep(k,sz[u<<1|1]-j){len--;putchar(decode(pw[u<<1|1][k+j]));}puts("");fflush(stdout);
