#define lch(x) (x << 1)
#define rch(x) (x << 1 | 1)

void build(int l, int r, int o)
{
	if (l == r)
	{
		string s = "";
		for (int i = 0; i < L; i++) s += ch[l];
		str[o] = s.substr(0, L - ask(s));
		return;
	}
	int mid = l + r >> 1;
	build(l, mid, lch(o));
	build(mid + 1, r, rch(o));
	str[o] = merge(lch(o), rch(o));
}

