void solve(int l,int r) {
	if(l==r) {
		for(int i=1;i<=n;i++) s[l][i]=ch[l];
		len[l]=ask(s[l],n); return ;
	}
	int mid=(l+r)>>1;
	solve(l,mid); 
	if(len[l]^n) solve(mid+1,r);
	int a=len[l],b=len[mid+1],i=1,j=1;
	len[l]=0;
	while(i<=a&&j<=b) {
