char base_c = 0;
int base;
int known[128];
string ans_s;

int len = 0;
void sol(char c) {
  assert(cnt[c] > 0);
  dump("sol", c, cnt[c]);
  while(cnt[c] > 0) {
    int unkonwn_total = 0;
    for(int i = 0; i < len; i++) {
      unkonwn_total += !known[i];
    }
    int ok = unkonwn_total;
    int ng = 0;
    while(ok - ng > 1) {
      int mid = (ok + ng) / 2;
      int done = 0;
      string t(len, base_c);
      for(int i = 0; i < len; i++) {
        if(!known[i]) {
          if(done < mid) {
            done++;
            t[i] = c;
          }
        } else {
          t[i] = ans_s[i];
        }
      }
      int diff = ask(t) - base;
      dump(diff);
      assert(diff <= 0);
      if(diff <= -1) ok = mid; else ng = mid;
    }

    int ok_i = -1;
    int un_c = 0;
    for(int i = 0; i < len; i++) {
      if(!known[i]) {
        un_c++;
        if(un_c == ok) {
          ok_i = i;
          break;
        }
      }
    }
    assert(ok_i >= 0 && ok_i < len);
    dump(ok_i);
    known[ok_i] = 1;
    ans_s[ok_i] = c;
    base--;
    cnt[c]--;
  }
}

