int Ask(string s) {
	if (memo.count(s)) { debug() << imie(s); return memo[s]; }
	#ifdef LOCAL
	++nqueries;
	int A = SZ(hidden);
	int B = SZ(s);
	vector<vi> dp(A + 1, vi(B + 1));
	for (int i = 0; i <= B; ++i) { dp[0][i] = i; }
	for (int j = 1; j <= A; ++j) {
		dp[j][0] = j;
		for (int i = 1; i <= B; ++i) {
			dp[j][i] = min({dp[j][i-1], dp[j-1][i], dp[j-1][i-1]}) + 1;
			if (hidden[j-1] == s[i-1]) {
				dp[j][i] = min(dp[j][i], dp[j-1][i-1]);
			}
		}
	}
	int ans = dp.back().back();
	//~ debug() << imie(hidden) << imie(s) << imie(ans);
