int L;
string go(int l, int r) {
	if (l + 1 == r) {
		char c = alpha[l];
		int l = 0;	
		int r = L + 1;
		while (r - l > 1) {
			int m = (l + r) / 2;
			if (ask(string(m, c)) == L - m) {
				l = m;
			} else r = m;
		}
		return string(l, c);
	} else {
		int m = (l + r) / 2;
		string A = go(l, m);
		string B = go(m, r);
		// reverse(A.begin(), A.end());
		// reverse(B.begin(), B.end());
		string C;
		while (!A.empty() && !B.empty()) {
			if (ask(C + A.substr(0, 1) + B) == L - le((C + A.substr(0, 1) + B))) {
				C += A[0];
				A.erase(A.begin());
			} else {
				C += B[0];
				B.erase(B.begin());
			}
		}
		return C + A + B;
	}
}

