void initF() {
	makeAlphaBet();
	int n = alphaBet.size();
	f = vector<string>(n);
	for (int i = 0; i < n; ++i) {
		f[i] = "";
	}
	totalL = 0;
	for (int i = 0; i < n; ++i) {
		string query = "";
		for (int j = 0; j < L; ++j) {
			query.push_back(alphaBet[i]);
		}
		int ans = makeQuery(query);
		f[i] = "";
		if (ans < L) {
			for (int j = 0; j < L - ans; ++j) {
				f[i].push_back(alphaBet[i]);
			}
		}
		totalL += (L - ans);
	}
}

string combine(string a, string b) {
	// cout << "combine " << a << " " << b << endl;
	if (a.length() == 0) {
		return b;
	}
	if (b.length() == 0) {
		return a;
	}
	int curA = 0, curB = 0;
	string res = "", tmp;
	int aL = a.length(), bL = b.length();
	while (curA < aL || curB < bL) {
		if (curA >= aL) {
			res.push_back(b[curB++]);
			continue;
		}
		if (curB >= bL) {
			res.push_back(a[curA++]);
			continue;
		}
		tmp = res;
		tmp.push_back(a[curA]);
		// res.push_back(b[curB]);
		for (int i = curB; i < bL; ++i) {
			tmp.push_back(b[curB]);
		}
		int ans = makeQuery(tmp);
		if (ans + (int)(tmp.size()) == totalL) {
			res.push_back(a[curA++]);
			continue;
		} else {
			res.push_back(b[curB++]);
			continue;
		}
	}
	return res;
}

string getF(int l, int r) {
	if (l == r) {
		return f[l];
	}
	int mid = (l + r) / 2;
	string left = getF(l, mid);
	string right = getF(mid + 1, r);
	return combine(left, right);
}

bool cmp(const string &a, const string &b) {
	return a.length() > b.length();
}

string combineF() {
	while (f.size() > 1) {
		sort(f.begin(), f.end(), cmp);
		int size = f.size();
		string a1 = f[size - 1];
		string a2 = f[size - 2];
		string a = combine(a1, a2);
		f.pop_back(); f.pop_back();
		f.push_back(a);
	}
	return f[0];
}

