    vvi dp(n1+1,vi(n2+1));
    rep(i,1,n1+1) dp[i][0]=i;
    rep(j,1,n2+1) dp[0][j]=j;
    rep(i,1,n1+1) rep(j,1,n2+1) {
        dp[i][j]=min({dp[i-1][j]+1,dp[i][j-1]+1,dp[i-1][j-1]+(s1[i-1]!=s2[j-1])});
    }
    return dp[n1][n2];
}

