string merge(string a,string b){
	string res;res.clear();
	int n=a.length(),m=b.length(),i=0,j=0;
	if (!n) return b;
	if (!m) return a;
	while ((i<n)||(j<m))
	if (i==n) res+=b[j++];
	else if (j==m) res+=a[i++];
	else{
		string t=res+a[i]+b[j];
		for (int k=j+1;k<m;k++) t+=b[k];
		if (ask(t)==len-(int)t.length()) res+=a[i++];
		else res+=b[j++];
	}
	return res;
