int calc(string s, string t) {
	for(int i = 0; i <= (int)s.size(); i++) {
		for(int j = 0; j <= (int)t.size(); j++) {
			if(i == 0 || j == 0) dp[i][j] = max(i, j);
			else {
				dp[i][j] = min(dp[i - 1][j] + 1, dp[i][j - 1] + 1);
				dp[i][j] = min(dp[i][j], dp[i - 1][j - 1] + (s[i - 1] != t[i - 1]));
			}
		}
	}
	return dp[s.size()][t.size()];
}

