    void init() {
        auto rnd = XorShift32();
        // int n    = rnd.next_int() % 120 + 1;
        int n = 128;
        seq   = string(n, '-');
        for (int i : range(n)) {
            seq[i] = resource[rnd.next_int() % resource.size()];
        }
