int check(int l,int r,char c){
	for(int i=l;i<=r;++i) s[a[i]]=c;
	putchar('?'); printf(" %s\n",s+1); fflush(stdout);
	int now; scanf("%d",&now);
	for(int i=l;i<=r;++i) s[a[i]]=p[1];
