void solve(int l,int r,int k,char c){
	if(l==r) return ve.push_back(a[l]),void();
	const int mid=l+r>>1;
	int y=sum-check(l,mid,c);
	if(y) solve(l,mid,y,c);
	if(k-y) solve(mid+1,r,k-y,c);
}
int main(){
	for(int i='a';i<='z';++i) p[++cnt]=i;
	for(int i='A';i<='Z';++i) p[++cnt]=i;
