int levenshtein_distance(const std::string &s, const std::string &t) {
    std::vector<std::vector<int>> dp(s.size() + 1, std::vector<int>(t.size() + 1, s.size() + t.size()));
    for (int i = 0; i < s.size(); ++i) dp[i][0] = i;
    for (int i = 0; i < t.size(); ++i) dp[0][i] = i;
    for (int i = 1; i <= s.size(); ++i) {
        for (int j = 1; j <= t.size(); ++j) {
            int cost = s[i - 1] == t[j - 1] ? 0 : 1;
            dp[i][j] = std::min(dp[i - 1][j - 1] + cost, std::min(dp[i - 1][j], dp[i][j - 1]) + 1);
        }
    }
    return dp[s.size()][t.size()];
}

