string merge(int l, int r) {
	if (l == r) return ss[l];
	int mid = (l + r) >> 1;
	string sl = merge(l, mid), sr = merge(mid + 1, r), s;
	int k = n - sl.size(), i = 0, I = sl.size(), j = 0, J = sr.size();
	while (i < I) {
		while (j < J && ask(s + sr[j] + sl.substr(i)) == k - 1)
			s += sr[j++], --k;
		s += sl[i++];
	}
	while (j < J) s += sr[j++];
	return s;
}

