int len;
string combine(string s, string t) {
    if (randomInt(0, 1)) swap(s, t);
    string w(s);
    for (int i = 0, j = 0; i < t.size(); i++, j++) {
        bool last = j==w.size();
        w.insert(w.begin()+j, t[i]);
        if (last || ask(w) == len-w.size()) {
            ///fine
        } else {
            ///not fine
            i--;
            w.erase(w.begin()+j);
        }
    }
//    cout << "==> " << w << endl;
    return w;
}

int main() {
    alphabet.clear();
    for (char c = 'a'; c <= 'z'; c++) alphabet.push_back(c);
    for (char c = 'A'; c <= 'Z'; c++) alphabet.push_back(c);
    for (char c = '0'; c <= '9'; c++) alphabet.push_back(c);

    shuffle(alphabet.begin(), alphabet.end(), rng);
//    cout << alphabet << endl;

    int mn = L+10;
    vector< int >got(alphabet.size());
    for (int i = 0; i < alphabet.size(); i++) {
        string t = "";
        t += alphabet[i];
        got[i] = ask(t);
        mn = min(mn, got[i]);
    }

    len = mn+1;
    vector< string >z;
    for (int i = 0; i < alphabet.size(); i++) {
        if (got[i] > mn) continue;
        string t = "";
        t += alphabet[i];
        z.push_back(t);
    }

    int covered = z.size();
    vector< string >w;

    while (z.size() > 0 && covered < len) {
        shuffle(z.begin(), z.end(), rng);
        string t = z.back(); z.pop_back();
        t.push_back(t.back());
        if (z.size() > 1 && ask(t) != len-t.size()) {
            t.pop_back();
//            cout << "==> " << t << endl;
            w.push_back(t);
        } else {
            covered++;
            z.push_back(t);
        }
    }

    while (z.size() > 0) {
        w.push_back(z.back());
        z.pop_back();
    }


    while (w.size() > 1) {
        sort(w.begin(), w.end(), [](const string &s, const string &t) {
            return s.size() > t.size();
        });
        string r = combine(w[w.size()-2], w[w.size()-1]);
        w.pop_back(); w.pop_back();
        w.push_back(r);
    }

    cout << "! " << w[0] << endl;

    return 0;
}

