        string s(128,cha[i]);
        c[i]=query(s);
        n += 128 - c[i];
    }
    rep(i,m)cnt[i][n]=128-c[i];
    ans.resize(n, '-');
    solve(0,n);
    if(counter>761){
        cout<<3<<endl;
    }
