bool cmp(string &s1, string &s2) {
	if (s1.size() == s2.size()) return s1 < s2;
	return s1.size() > s2.size();
}

string merge_strings(string x, string y, int len) {
	int n = x.size(), petr1 = 0;
	int m = y.size(), petr2 = 0;

	string ans;
	while (petr1 < n && petr2 < m) {
		ans.push_back(x[petr1]);

		if (ask(ans) == (len - ans.size())) {
			petr1++;
		} else {
			ans.pop_back();
			ans.push_back(y[petr2]);
			petr2++;
		}
	}
	while (petr1 < n) {
		ans.push_back(x[petr1]); petr1++;
	}
	while (petr2 < m) {
		ans.push_back(y[petr2]); petr2++;
	}
	return ans;
}

