/** @author Spheniscine */
fun main() { _writer.solve(); _writer.flush() }
fun PrintWriter.solve() {
    object {
        val n = readInt()
        val P = IntArray(n * n) { readInt() - 1 }

        val occ = Array(n) { BooleanArray(n) { true } }

        val C = Array(n) { i ->
            IntArray(n) { j ->
                minOf(i, n-1-i, j, n-1-j)
            }
        }

        var ans = 0

        inline fun forEachNeighbor(i: Int, j: Int, yield: (ni: Int, nj: Int) -> Unit) {
            if(i > 0) yield(i-1, j)
            if(i < n-1) yield(i+1, j)
            if(j > 0) yield(i, j-1)
            if(j < n-1) yield(i, j+1)
        }

        init {
            val Q = IntDeque()
            for(p in P) {
                val pi = p / n
                val pj = p - n * pi

                ans += C[pi][pj]
                occ[pi][pj] = false

                Q.add(pi)
                Q.add(pj)

                while(Q.isNotEmpty()) {
                    val i = Q.remove()
                    val j = Q.remove()
                    val c = C[i][j] + if(occ[i][j]) 1 else 0

                    forEachNeighbor(i, j) { ni, nj ->
                        if(C[ni].setMin(nj, c)) {
                            Q.add(ni)
                            Q.add(nj)
                        }
                    }
                }

            }

            println(ans)
        }

    }
}

fun minOf(first: Int, vararg rest: Int) = rest.fold(first, ::min)
fun IntArray.setMin(i: Int, v: Int) = if(v < get(i)) { set(i, v); true } else false

class IntDeque(capacity: Int = 12){
    private var arr = IntArray(capacity)
    var size = 0
        private set
    inline val lastIndex get() = size - 1
    inline val indices get() = 0 until size

    private inline val capacity get() = arr.size

    inline fun isEmpty() = size == 0
    inline fun isNotEmpty() = size != 0

    private var head = 0

    private fun grow(minCapacity: Int = 8) {
        val newCapacity = maxOf(minCapacity, capacity + (capacity shr 1))
        val new = IntArray(newCapacity)
        for(i in 0 until size) new[i] = get(i)
        arr = new
        head = 0
    }

    private fun incHead() {
        head++
        if(head == capacity) head = 0
    }

    private fun decHead() {
        if(head == 0) head = capacity - 1
        else head--
    }

    private fun index(i: Int) = (head + i).let { if(it >= capacity) it - capacity else it }

    fun add(index: Int, element: Int) {
        if(size == capacity) grow()
        if(index < size / 2) {
            decHead()
            size++
            for(i in 0 until index) {
                set(i, get(i+1))
            }
        } else {
            size++
            for(i in size - 2 downTo index) {
                set(i+1, get(i))
            }
        }
        set(index, element)
    }

    fun addLast(e: Int) {
        if(size == capacity) grow()
        arr[index(size)] = e
        size++
    }
    inline fun add(e: Int) = addLast(e)

    val first get() = get(0)
    val last get() = get(lastIndex)

    fun removeFirst(): Int {
        val e = get(0)
        incHead()
        size--
        return e
    }
    inline fun remove() = removeFirst()
    fun removeLast(): Int {
        val e = get(lastIndex)
        size--
        return e
    }

    fun addFirst(e: Int) {
        if(size == capacity) grow()
        decHead()
        arr[head] = e
        size++
    }

    operator fun get(index: Int): Int {
        require(index in 0 until size)
        return arr[index(index)]
    }

    fun removeAt(index: Int): Int {
        val e = get(index)
        if(index < size / 2) {
            for(i in index - 1 downTo 0) {
                set(i+1, get(i))
            }
            incHead()
        } else {
            for(i in index until size - 1) {
                set(i, get(i+1))
            }
        }
        size--
        return e
    }

    operator fun set(index: Int, element: Int): Int {
        val old = get(index)
        arr[index(index)] = element
        return old
    }

    operator fun iterator() = object: IntIterator() {
        var i = 0
        override fun hasNext(): Boolean = i < size
        override fun nextInt(): Int = get(i++)
    }
}


