/** @author Spheniscine */
fun main() { _writer.solve(); _writer.flush() }
fun PrintWriter.solve() {
//    val numCases = readInt()
//    for(case in 1..numCases) {
//        //print("Case #$case: ")
//    }

    object {
        var q = 850
        fun ask(t: CharSequence): Int {
            if(q-- == 0) exitProcess(0)
            iprintln("? $t")
            return readInt()
        }

        val que = PriorityQueue<String>(compareBy { it.length })
        var len = 0
        init {
            for(c in alph) {
                val v = L - ask(c.toString().repeat(L))
                len += v
                que.add(c.toString().repeat(v))
            }

            while(que.size > 1) {
                val a = que.remove()
                val b = que.remove()

                val t = StringBuilder(a.length + b.length).append(a)

                var i = 0
                f@ for(j in b.indices) {
                    while(true) {
                        if(i == t.length) {
                            t.append(b.substring(j))
                            break@f
                        }
                        t.insert(i, b[j])
                        if (len - t.length == ask(t)) {
                            i++
                            break
                        } else t.deleteCharAt(i++)
                    }
                }

                que.add(t.toString())
            }

            val ans = que.remove()
            iprintln("! $ans")
        }
    }
}

