class Solver {
  private static final int MAX_LENGTH = 128;
  private static final String ALPHABETS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

  final Judge judge;
  int totalLength;

  Solver(Judge judge) {
    this.judge = judge;
  }

  private int putQuery(String password) {
    judge.putQuery("? " + password);
    return Integer.parseInt(judge.next());
  }

  private String merge(String s1, String s2) {
    String merged = "";
    while (s1.length() > 0 && s2.length() > 0) {
      String password = merged + s1.charAt(0) + s2;
      int editDistance = putQuery(password);
      if (editDistance + password.length() == totalLength) {
        merged += s1.charAt(0);
        s1 = s1.substring(1);
      } else {
        merged += s2.charAt(0);
        s2 = s2.substring(1);
      }
    }
    return merged + s1 + s2;
  }

  public void run() {
    totalLength = 0;
    Comparator<String> shortStringFirstComparator = new Comparator<String>() {
      @Override
      public int compare(String s1, String s2) {
        return s1.length() - s2.length();
      }
    };
    PriorityQueue<String> queue = new PriorityQueue<>(shortStringFirstComparator);
    for (int i = 0; i < ALPHABETS.length(); i++) {
      String s = ALPHABETS.substring(i, i + 1);
      int count = MAX_LENGTH - putQuery(s.repeat(MAX_LENGTH));
      if (count > 0) {
        totalLength += count;
        queue.add(s.repeat(count));
      }
    }
    while (queue.size() >= 2) {
      queue.add(merge(queue.poll(), queue.poll()));
    }
    judge.putQuery("! " + queue.poll());
  }
}

class Solver2 {
  private static final int MAX_LENGTH = 128;
  private static final String ALPHABETS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
  private static final int ALPHABET_SIZE = ALPHABETS.length();

  final Judge judge;
  int passwordLength;
  int[][] countMatrix;
  char[] answerBuffer;

  Solver2(Judge judge) {
    this.judge = judge;
  }

  private int putQuery(String password) {
    judge.putQuery("? " + password);
    return Integer.parseInt(judge.next());
  }

  private void solve(int leftIndex, int rightIndex) {
//    System.err.printf("solve: [%d %d)\n", leftIndex, rightIndex);
    if (leftIndex + 1 == rightIndex) {
      for (int i = 0; i < ALPHABET_SIZE; i++) {
        if (countMatrix[i][leftIndex] != countMatrix[i][rightIndex]) {
          answerBuffer[leftIndex] = ALPHABETS.charAt(i);
          return;
        }
      }
      throw new RuntimeException();
    }

    int midIndex = (leftIndex + rightIndex) / 2;

    int notShownCharIndex = -1;
    int sum = 0;
    List<Integer> shownCharIndexList = new ArrayList<>();
    for (int i = 0; i < ALPHABET_SIZE; i++) {
      if (countMatrix[i][leftIndex] == countMatrix[i][rightIndex]) {
        countMatrix[i][midIndex] = countMatrix[i][leftIndex];
        notShownCharIndex = i;
        sum -= countMatrix[i][midIndex];
      } else {
        shownCharIndexList.add(i);
      }
    }
    if (notShownCharIndex < 0) {
      int[] tempMatchCounts = new int[ALPHABET_SIZE];
      int tempMatchSum = 0;
      for (int i = 1; i < ALPHABET_SIZE; i++) {
        char[] passwordBuffer = new char[passwordLength];
        Arrays.fill(passwordBuffer, midIndex, passwordLength, ALPHABETS.charAt(0));
        Arrays.fill(passwordBuffer, 0, midIndex, ALPHABETS.charAt(i));
        tempMatchCounts[i] = putQuery(new String(passwordBuffer)) + countMatrix[i][passwordLength] - passwordLength;
//        System.err.println(tempMatchCounts[i]);
        tempMatchSum += tempMatchCounts[i];
      }
//      System.err.println(tempMatchSum);
      if ((midIndex + tempMatchSum) % ALPHABET_SIZE != 0) {
        throw new RuntimeException();
      }
      countMatrix[0][midIndex] = (midIndex + tempMatchSum) / ALPHABET_SIZE;
      for (int i = 1; i < ALPHABET_SIZE; i++) {
        countMatrix[i][midIndex] = (midIndex + tempMatchSum) / ALPHABET_SIZE - tempMatchCounts[i];
//        System.err.printf("%d %d %d\n", midIndex, i, countMatrix[i][midIndex]);
      }
    } else {
      sum += countMatrix[notShownCharIndex][midIndex];
      int[] tempMatchCounts = new int[ALPHABET_SIZE];
      for (int i = 1; i < shownCharIndexList.size(); i++) {
        int charIndex = shownCharIndexList.get(i);
        char[] passwordBuffer = new char[passwordLength];
        Arrays.fill(passwordBuffer, midIndex, passwordLength, ALPHABETS.charAt(notShownCharIndex));
        Arrays.fill(passwordBuffer, 0, midIndex, ALPHABETS.charAt(charIndex));
        tempMatchCounts[charIndex] = putQuery(new String(passwordBuffer)) + countMatrix[notShownCharIndex][passwordLength] - passwordLength;
//        System.err.printf()
        sum += tempMatchCounts[charIndex];
      }
      tempMatchCounts[shownCharIndexList.get(0)] = (shownCharIndexList.size() + 1) * countMatrix[notShownCharIndex][midIndex] - sum - midIndex;
      for (int charIndex : shownCharIndexList) {
        countMatrix[charIndex][midIndex] = countMatrix[notShownCharIndex][midIndex] - tempMatchCounts[charIndex];
//        System.err.printf("%d %d %d\n", midIndex, charIndex, countMatrix[charIndex][midIndex]);
      }
    }
    solve(leftIndex, midIndex);
    solve(midIndex, rightIndex);
  }

  public void run() {
    passwordLength = 0;
    int[] counts = new int[ALPHABET_SIZE];
    for (int i = 0; i < ALPHABETS.length(); i++) {
      String s = ALPHABETS.substring(i, i + 1);
      counts[i] = MAX_LENGTH - putQuery(s.repeat(MAX_LENGTH));
      passwordLength += counts[i];
    }
    countMatrix = new int[ALPHABET_SIZE][passwordLength + 1];
    for (int i = 0; i < ALPHABET_SIZE; i++) {
      countMatrix[i][passwordLength] = counts[i];
    }
    answerBuffer = new char[passwordLength];
    Arrays.fill(answerBuffer, '-');
    solve(0, passwordLength);
    judge.putQuery("! " + new String(answerBuffer));
  }
}

class OfflineJudge implements Judge {
  private final char[] secretCharArray;
  private final String secretString;
  private final Deque<String> deque;
  int count = 0;

  public OfflineJudge(String secret) {
    secretString = secret;
    secretCharArray = secret.toCharArray();
    deque = new ArrayDeque<>();
  }

  @Override
  public String next() {
    return deque.pollFirst();
  }

  private int calculateEditDistance(char[] cs) {
    int[][] dptable = new int[cs.length + 1][secretCharArray.length + 1];
    for (int i = 0; i <= cs.length; i++) {
      dptable[i][0] = i;
    }
    for (int j = 0; j <= secretCharArray.length; j++) {
      dptable[0][j] = j;
    }
    for (int i = 1; i <= cs.length; i++) {
      for (int j = 1; j <= secretCharArray.length; j++) {
        int v = dptable[i - 1][j] + 1;
        v = Math.min(v, dptable[i][j - 1] + 1);
        if (cs[i - 1] == secretCharArray[j - 1]) {
          v = Math.min(v, dptable[i - 1][j - 1]);
        } else {
          v = Math.min(v, dptable[i - 1][j - 1] + 1);
        }
        dptable[i][j] = v;
      }
    }
    return dptable[cs.length][secretCharArray.length];
  }

  @Override
  public void putQuery(String query) {
    String[] tokens = query.split(" ");
    if (tokens[0].equals("!")) {
      if (tokens[1].equals(secretString)) {
        System.err.println("AC");
      } else {
        System.err.println("WA");
      }
    } else {
      if (count >= 850) {
        throw new RuntimeException();
      }
      count++;
      char[] cs = tokens[1].toCharArray();
      deque.addLast("" + calculateEditDistance(cs));
    }
  }
}

