class ContestReader {
  private static final int BUFFER_SIZE = 1024;

  private final InputStream stream;
  private final byte[] buffer;
  private int pointer;
  private int bufferLength;

  ContestReader(InputStream stream) {
    this.stream = stream;
    this.buffer = new byte[BUFFER_SIZE];
    this.pointer = 0;
    this.bufferLength = 0;
  }

  private boolean hasNextByte() {
    if (pointer < bufferLength) {
      return true;
    }

    pointer = 0;
    try {
      bufferLength = stream.read(buffer);
    } catch (IOException e) {
      throw new RuntimeException(e);
    }
    return bufferLength > 0;
  }

  private int readByte() {
    if (hasNextByte()) {
      return buffer[pointer++];
    } else {
      return -1;
    }
  }

  private static boolean isPrintableChar(int c) {
    return 33 <= c && c <= 126;
  }

  public boolean hasNext() {
    while (hasNextByte() && !isPrintableChar(buffer[pointer])) {
      pointer++;
    }
    return hasNextByte();
  }

  public String next() {
    if (!hasNext()) {
      throw new NoSuchElementException();
    }
    StringBuilder sb = new StringBuilder();
    while(true) {
      int b = readByte();
      if (!isPrintableChar(b)) {
        break;
      }
      sb.appendCodePoint(b);
    }
    return sb.toString();
  }

  public String nextLine() {
    if (!hasNext()) {
      throw new NoSuchElementException();
    }
    StringBuilder sb = new StringBuilder();
    while(true) {
      int b = readByte();
      if (!isPrintableChar(b) && b != 0x20) {
        break;
      }
      sb.appendCodePoint(b);
    }
    return sb.toString();
  }

  public char nextChar() {
    return next().charAt(0);
  }

  public int nextInt() {
    if (!hasNext()) {
      throw new NoSuchElementException();
    }

    int n = 0;
    boolean minus = false;

    {
      int b = readByte();
      if (b == '-') {
        minus = true;
      } else if ('0' <= b && b <= '9') {
        n = b - '0';
      } else {
        throw new NumberFormatException();
      }
    }

    while(true){
      int b = readByte();
      if ('0' <= b && b <= '9') {
        n *= 10;
        n += b - '0';
      } else if (b == -1 || !isPrintableChar(b)) {
        return minus ? -n : n;
      } else {
        throw new NumberFormatException();
      }
    }
  }

  public long nextLong() {
    if (!hasNext()) {
      throw new NoSuchElementException();
    }

    long n = 0;
    boolean minus = false;

    {
      int b = readByte();
      if (b == '-') {
        minus = true;
      } else if ('0' <= b && b <= '9') {
        n = b - '0';
      } else {
        throw new NumberFormatException();
      }
    }

    while(true){
      int b = readByte();
      if ('0' <= b && b <= '9') {
        n *= 10;
        n += b - '0';
      } else if (b == -1 || !isPrintableChar(b)) {
        return minus ? -n : n;
      } else {
        throw new NumberFormatException();
      }
    }
  }

  public double nextDouble() {
    return Double.parseDouble(next());
  }

  public String[] next(int n) {
    String[] array = new String[n];
    for (int i = 0; i < n; i++) {
      array[i] = next();
    }
    return array;
  }

  public String[] nextLine(int n) {
    String[] array = new String[n];
    for (int i = 0; i < n; i++) {
      array[i] = nextLine();
    }
    return array;
  }

  public char[] nextChar(int n) {
    char[] array = new char[n];
    for (int i = 0; i < n; i++) {
      array[i] = nextChar();
    }
    return array;
  }

  public int[] nextInt(int n) {
    int[] array = new int[n];
    for (int i = 0; i < n; i++) {
      array[i] = nextInt();
    }
    return array;
  }

  public long[] nextLong(int n) {
    long[] array = new long[n];
    for (int i = 0; i < n; i++) {
      array[i] = nextLong();
    }
    return array;
  }

  public double[] nextDouble(int n) {
    double[] array = new double[n];
    for (int i = 0; i < n; i++) {
      array[i] = nextDouble();
    }
    return array;
  }

  public char[] nextCharArray() {
    return next().toCharArray();
  }

  public String[][] next(int n, int m) {
    String[][] matrix = new String[n][m];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        matrix[i][j] = next();
      }
    }
    return matrix;
  }

  public int[][] nextInt(int n, int m) {
    int[][] matrix = new int[n][m];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        matrix[i][j] = nextInt();
      }
    }
    return matrix;
  }

  public char[][] nextChar(int n, int m) {
    char[][] matrix = new char[n][m];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        matrix[i][j] = nextChar();
      }
    }
    return matrix;
  }

  public long[][] nextLong(int n, int m) {
    long[][] matrix = new long[n][m];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        matrix[i][j] = nextLong();
      }
    }
    return matrix;
  }

  public double[][] nextDouble(int n, int m) {
    double[][] matrix = new double[n][m];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        matrix[i][j] = nextDouble();
      }
    }
    return matrix;
  }

  public char[][] nextCharArray(int n) {
    char[][] matrix = new char[n][];
    for (int i = 0; i < n; i++) {
      matrix[i] = next().toCharArray();
    }
    return matrix;
  }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.StringTokenizer;

public class Main {

	static MyScanner sc = new MyScanner();
	static PrintWriter out = new PrintWriter(System.out);
	static int L = 128;
	static char[] vals;

	static {
		vals = new char[62];
		int idx = 0;
		for (char c = 'a'; c <= 'z'; c++) {
			vals[idx++] = c;
		}
		for (char c = 'A'; c <= 'Z'; c++) {
			vals[idx++] = c;
		}
		for (char c = '0'; c <= '9'; c++) {
			vals[idx++] = c;
		}
	}

	static char[] merge(char[] a, char[] b) {
		char[] ret = new char[a.length + b.length];
		int aIdx = 0, bIdx = 0, idx = 0;

		while (aIdx < a.length && bIdx < b.length) {
			char[] tmp = new char[idx + 1 + b.length - bIdx];
			int i;
			for (i = 0; i < idx; i++) {
				tmp[i] = ret[i];
			}
			tmp[i++] = a[aIdx];
			for (int j = bIdx; j < b.length; j++) {
				tmp[i++] = b[j];
			}
			if (subString(tmp)) {
				ret[idx++] = a[aIdx++];
			} else {
				ret[idx++] = b[bIdx++];
			}
		}
		while (aIdx < a.length) {
			ret[idx++] = a[aIdx++];
		}
		while (bIdx < b.length) {
			ret[idx++] = b[bIdx++];
		}
		return ret;
	}

	static char[] joinAll(List<char[]> vals) {
		while (vals.size() > 1) {
			Collections.sort(vals, Comparator.comparingInt(a -> a.length));
			vals.set(0, merge(vals.get(0), vals.get(1)));
			vals.remove(1);
		}
		return vals.get(0);
	}

	static int findSize(char v) {
		return L - query(getRep(v, L));
	}

	static int findSize(char v, int first) {
		int from = first;
		int dif = 1;
		while (subString(getRep(v, from))) {
			from += dif;
			dif *= 2;
		}
		int left = from == first ? 0 : from - dif / 2, right = Math.min(from, L + 1);
		while (left + 1 < right) {
			int med = (left + right) / 2;

			if (subString(getRep(v, med))) {
				left = med;
			} else {
				right = med;
			}
		}
		return left;
	}

	static char[] getRep(char c, int size) {
		char[] ret = new char[size];
		Arrays.fill(ret, c);
		return ret;
	}

	static boolean subString(char[] s) {
		if (s.length > L) return false;
		int val = query(s);
		return val + s.length == L;
	}

	static int query(char[] s) {
		out.println("? " + new String(s));
		out.flush();
		return sc.nextInt();
	}

	public static void main(String[] args) throws IOException {
		List<char[]> subs = new ArrayList<>();
		int rem = L;
		for (int i = 0; i < vals.length && rem > 0 && i < 3; i++) {
			int size = findSize(vals[i]);
			if (size > 0) {
				subs.add(getRep(vals[i], size));
				rem -= size;
			}
		}
		L -= rem;
		char[] ret = joinAll(subs);
		out.println("! " + new String(ret));

		out.flush();
	}

	static class MyScanner {
		private BufferedReader br;
		private StringTokenizer tokenizer;

		public MyScanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		public String next() {
			while (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					tokenizer = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return tokenizer.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

		public long nextLong() {
			return Long.parseLong(next());
		}
	}
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.io.Closeable;
import java.io.Writer;
import java.io.OutputStreamWriter;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) throws Exception {
        Thread thread = new Thread(null, new TaskAdapter(), "", 1 << 27);
        thread.start();
        thread.join();
    }

    static class TaskAdapter implements Runnable {
        @Override
        public void run() {
            InputStream inputStream = System.in;
            OutputStream outputStream = System.out;
            FastInput in = new FastInput(inputStream);
            FastOutput out = new FastOutput(outputStream);
            DGuessThePassword solver = new DGuessThePassword();
            solver.solve(1, in, out);
            out.close();
        }
    }

    static class DGuessThePassword {
        char[] charset;
        int[] cnts;
        int L;
        StringBuilder query = new StringBuilder(128);
        FastInput in;
        FastOutput out;

        {
            StringBuilder charsetBuilder = new StringBuilder();
            for (char i = 'a'; i <= 'z'; i++) {
                charsetBuilder.append(i);
            }
            for (char i = 'A'; i <= 'Z'; i++) {
                charsetBuilder.append(i);
            }
            for (char i = '0'; i <= '9'; i++) {
                charsetBuilder.append(i);
            }
            charset = charsetBuilder.toString().toCharArray();
        }

        public void solve(int testNumber, FastInput in, FastOutput out) {
            this.in = in;
            this.out = out;
            cnts = new int[charset.length];
            for (int i = 0; i < charset.length; i++) {
                query.setLength(0);
                for (int j = 0; j < 128; j++) {
                    query.append(charset[i]);
                }
                cnts[i] = 128 - ask(query);
                L += cnts[i];
            }

            String ans = dac(0, charset.length - 1);
            out.append("! ").println(ans).flush();
        }

        public String dac(int l, int r) {
            if (l == r) {
                query.setLength(0);
                for (int i = 0; i < cnts[l]; i++) {
                    query.append(charset[l]);
                }
                return query.toString();
            }

            int m = (l + r) / 2;
            String left = dac(l, m);
            String right = dac(m + 1, r);

            IntegerDeque ldq = new IntegerRange2DequeAdapter(i -> left.charAt(i), 0, left.length() - 1);
            IntegerDeque rdq = new IntegerRange2DequeAdapter(i -> right.charAt(i), 0, right.length() - 1);

            query.setLength(0);
            while (!ldq.isEmpty() && !rdq.isEmpty()) {
                int len = query.length();
                query.append((char) rdq.peekFirst());
                for (IntegerIterator iterator = ldq.iterator(); iterator.hasNext(); ) {
                    query.append((char) iterator.next());
                }
                if (ask(query) == L - query.length()) {
                    rdq.removeFirst();
                    query.setLength(len + 1);
                } else {
                    query.setLength(len);
                    query.append((char) ldq.removeFirst());
                }
            }

            while (!ldq.isEmpty()) {
                query.append((char) ldq.removeFirst());
            }
            while (!rdq.isEmpty()) {
                query.append((char) rdq.removeFirst());
            }
            return query.toString();
        }

        public int ask(Object s) {
            out.append("? ").println(s).flush();
            return in.readInt();
        }

    }

    static interface IntegerIterator {
        boolean hasNext();

        int next();

    }

    static class IntegerRange2DequeAdapter implements IntegerDeque {
        IntToIntegerFunction function;
        int l;
        int r;

        public IntegerRange2DequeAdapter(IntToIntegerFunction function, int l, int r) {
            this.function = function;
            this.l = l;
            this.r = r;
        }

        public boolean isEmpty() {
            return l > r;
        }

        public int peekFirst() {
            return function.apply(l);
        }

        public int removeFirst() {
            return function.apply(l++);
        }

        public IntegerIterator iterator() {
            return new IntegerIterator() {
                int iter = l;


                public boolean hasNext() {
                    return iter <= r;
                }


                public int next() {
                    return function.apply(iter++);
                }
            };
        }

    }

    static class FastOutput implements AutoCloseable, Closeable, Appendable {
        private StringBuilder cache = new StringBuilder(10 << 20);
        private final Writer os;

        public FastOutput append(CharSequence csq) {
            cache.append(csq);
            return this;
        }

        public FastOutput append(CharSequence csq, int start, int end) {
            cache.append(csq, start, end);
            return this;
        }

        public FastOutput(Writer os) {
            this.os = os;
        }

        public FastOutput(OutputStream os) {
            this(new OutputStreamWriter(os));
        }

        public FastOutput append(char c) {
            cache.append(c);
            return this;
        }

        public FastOutput append(String c) {
            cache.append(c);
            return this;
        }

        public FastOutput append(Object c) {
            cache.append(c);
