class Solver {
  private static final int MAX_LENGTH = 128;
  private static final String ALPHABETS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

  final Judge judge;
  int totalLength;

  Solver(Judge judge) {
    this.judge = judge;
  }

  private int putQuery(String password) {
    judge.putQuery("? " + password);
    return Integer.parseInt(judge.next());
  }

  private String merge(String s1, String s2) {
    String merged = "";
    while (s1.length() > 0 && s2.length() > 0) {
      String password = merged + s1.charAt(0) + s2;
      int editDistance = putQuery(password);
      if (editDistance + password.length() == totalLength) {
        merged += s1.charAt(0);
        s1 = s1.substring(1);
      } else {
        merged += s2.charAt(0);
        s2 = s2.substring(1);
      }
    }
    return merged + s1 + s2;
  }

  public void run() {
    totalLength = 0;
    Comparator<String> shortStringFirstComparator = new Comparator<String>() {
      @Override
      public int compare(String s1, String s2) {
        return s1.length() - s2.length();
      }
    };
    PriorityQueue<String> queue = new PriorityQueue<>(shortStringFirstComparator);
    for (int i = 0; i < ALPHABETS.length(); i++) {
      String s = ALPHABETS.substring(i, i + 1);
      int count = MAX_LENGTH - putQuery(s.repeat(MAX_LENGTH));
      if (count > 0) {
        totalLength += count;
        queue.add(s.repeat(count));
      }
    }
    while (queue.size() >= 2) {
      queue.add(merge(queue.poll(), queue.poll()));
    }
    judge.putQuery("! " + queue.poll());
  }
}

class Solver2 {
  private static final int MAX_LENGTH = 128;
  private static final String ALPHABETS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
  private static final int ALPHABET_SIZE = ALPHABETS.length();

  final Judge judge;
  int passwordLength;
  int[][] countMatrix;
  char[] answerBuffer;

  Solver2(Judge judge) {
    this.judge = judge;
  }

  private int putQuery(String password) {
    judge.putQuery("? " + password);
    return Integer.parseInt(judge.next());
  }

  private List<Integer> calculateCharList(int leftIndex, int rightIndex) {
    List<Integer> list = new ArrayList<>();
    for (int i = 0; i < ALPHABET_SIZE; i++) {
      if (countMatrix[i][leftIndex] < countMatrix[i][rightIndex]) {
        list.add(i);
      }
    }
    return list;
  }

  private String buildPassword(char head, int headCount, char tail, int tailCount) {
    return ("" + head).repeat(headCount) + ("" + tail).repeat(tailCount);
  }

  private void solveWithCompleteAlphabets(int leftIndex, int midIndex, int rightIndex) {
    // countMatrix[i][midIndex] + countMatrix[0][passwordLength] - countMatrix[0][midIndex]
    int[] hitCounts = new int[ALPHABET_SIZE];
    int sumHitCounts = 0;
    for (int i = 1; i < ALPHABET_SIZE; i++) {
      String guessPassword = buildPassword(ALPHABETS.charAt(i), midIndex, ALPHABETS.charAt(0), passwordLength -  midIndex);
      hitCounts[i] = passwordLength - putQuery(guessPassword);
      sumHitCounts += hitCounts[i];
    }

    // (ALPHABET_SIZE - 1) * countMatrix[0][passwordLength] + midIndex - sigma(i 1->ALPHABET_SIZE) { countMatrix[i][midIndex] + countMatrix[0][passwordLength] - countMatrix[0][midIndex] }
    // midIndex - sigma(i 1->ALPHABET_SIZE) { countMatrix[i][midIndex] - countMatrix[0][midIndex] }
    // (ALPHABET_SIZE - 1) * countMatrix[0][midIndex] + midIndex - sigma(i 1->ALPHABET_SIZE) { countMatrix[i][midIndex] }
    // ALPHABET_SIZE * countMatrix[0][midIndex]
    int temp = (ALPHABET_SIZE - 1) * countMatrix[0][passwordLength] + midIndex - sumHitCounts;
    MyAssert.myAssert(temp % ALPHABET_SIZE == 0);

    countMatrix[0][midIndex] = temp / ALPHABET_SIZE;

    for (int i = 1; i < ALPHABET_SIZE; i++) {
      countMatrix[i][midIndex] = hitCounts[i] - countMatrix[0][passwordLength] + countMatrix[0][midIndex];
    }
  }

  private void solveWithPartialAlphabets(int leftIndex, int midIndex, int rightIndex, List<Integer> charIndexList) {
    int otherCharIndex = -1;
    for (int i = 0; i < ALPHABET_SIZE; i++) {
      if (!charIndexList.contains(i)) {
        otherCharIndex = i;
        break;
      }
    }
    MyAssert.myAssert(otherCharIndex >= 0);

    for (int k = 1; k < charIndexList.size(); k++) {
      int i = charIndexList.get(k);

      String guessPassword = buildPassword(ALPHABETS.charAt(i), midIndex, ALPHABETS.charAt(otherCharIndex), passwordLength -  midIndex);
      int editDistance = putQuery(guessPassword);
      countMatrix[i][midIndex] = passwordLength - editDistance - countMatrix[otherCharIndex][passwordLength] + countMatrix[otherCharIndex][midIndex];
    }

    int sumCountMatrix = 0;
    for (int i = 0; i < ALPHABET_SIZE; i++) {
      if (i != charIndexList.get(0)) {
        sumCountMatrix += countMatrix[i][midIndex];
      }
    }
    countMatrix[charIndexList.get(0)][midIndex] = midIndex - sumCountMatrix;
  }

  private void solve(int leftIndex, int rightIndex) {
    List<Integer> charIndexList = calculateCharList(leftIndex, rightIndex);
    int midIndex = (leftIndex + rightIndex) / 2;
    if (charIndexList.size() == 1) {
      Arrays.fill(answerBuffer, leftIndex, rightIndex, ALPHABETS.charAt(charIndexList.get(0)));
      return;
    } else if (charIndexList.size() == ALPHABET_SIZE) {
      solveWithCompleteAlphabets(leftIndex, midIndex, rightIndex);
    } else {
      solveWithPartialAlphabets(leftIndex, midIndex, rightIndex, charIndexList);
    }

    // Fill trivial range.
    for (int i = 0; i < ALPHABET_SIZE; i++) {
      if (countMatrix[i][leftIndex] == countMatrix[i][midIndex]) {
        Arrays.fill(countMatrix[i], leftIndex, midIndex, countMatrix[i][leftIndex]);
      }
      if (countMatrix[i][midIndex] == countMatrix[i][rightIndex]) {
        Arrays.fill(countMatrix[i], midIndex, rightIndex, countMatrix[i][midIndex]);        
      }
    }

    solve(leftIndex, midIndex);
    solve(midIndex, rightIndex);
  }

  public void run() {
    passwordLength = 0;
    int[] counts = new int[ALPHABET_SIZE];
    for (int i = 0; i < ALPHABETS.length(); i++) {
      String s = ALPHABETS.substring(i, i + 1);
      counts[i] = MAX_LENGTH - putQuery(s.repeat(MAX_LENGTH));
      passwordLength += counts[i];
    }
    countMatrix = new int[ALPHABET_SIZE][passwordLength + 1];
    for (int i = 0; i < ALPHABET_SIZE; i++) {
      countMatrix[i][passwordLength] = counts[i];
    }
    answerBuffer = new char[passwordLength];
    Arrays.fill(answerBuffer, '-');
    solve(0, passwordLength);
    judge.putQuery("! " + new String(answerBuffer));
  }
}

class OfflineJudge implements Judge {
  private final char[] secretCharArray;
  private final String secretString;
  private final Deque<String> deque;
  int count = 0;

  public OfflineJudge(String secret) {
    secretString = secret;
    secretCharArray = secret.toCharArray();
    deque = new ArrayDeque<>();
  }

  @Override
  public String next() {
    return deque.pollFirst();
  }

  private int calculateEditDistance(char[] cs) {
    int[][] dptable = new int[cs.length + 1][secretCharArray.length + 1];
    for (int i = 0; i <= cs.length; i++) {
      dptable[i][0] = i;
    }
    for (int j = 0; j <= secretCharArray.length; j++) {
      dptable[0][j] = j;
    }
    for (int i = 1; i <= cs.length; i++) {
      for (int j = 1; j <= secretCharArray.length; j++) {
        int v = dptable[i - 1][j] + 1;
        v = Math.min(v, dptable[i][j - 1] + 1);
        if (cs[i - 1] == secretCharArray[j - 1]) {
          v = Math.min(v, dptable[i - 1][j - 1]);
        } else {
          v = Math.min(v, dptable[i - 1][j - 1] + 1);
        }
        dptable[i][j] = v;
      }
    }
    return dptable[cs.length][secretCharArray.length];
  }

  @Override
  public void putQuery(String query) {
    String[] tokens = query.split(" ");
    if (tokens[0].equals("!")) {
      if (tokens[1].equals(secretString)) {
        System.err.println("AC");
      } else {
        System.err.println("WA");
      }
    } else {
      MyAssert.myAssert(count < 850);
      count++;
      char[] cs = tokens[1].toCharArray();
      deque.addLast("" + calculateEditDistance(cs));
    }
  }
}

