    int ask(String s) {
        out.println("? " + s);
        out.flush();
        return in.nextInt();
    }

    boolean good(String s) {
        int r = ask(s);
        return r == len - s.length();
    }

    String combine(String s1, String s2) {
        int posToPut = 0;
//        System.err.println("combine: " + s1 + " " + s2);
        for (char c : s2.toCharArray()) {
            while (true) {
                String ask = s1.substring(0, posToPut) + c + s1.substring(posToPut);
                if (good(ask)) {
                    s1 = ask;
                    posToPut++;
                    break;
                } else {
                    posToPut++;
                }
            }
        }
        return s1 + s2;
    }

