    public class PriorityQueue<T> {
        private T[] _array = new T[128];
        private int _size = 0;
        private readonly Comparison<T> _compare;

        public PriorityQueue() {
            _compare = Comparer<T>.Default.Compare;
        }

        public PriorityQueue(Comparison<T> comp) {
            _compare = comp;
        }

        public int Count { get { return _size; } }

        private void Swap(int a, int b) {
            var t = _array[a];
            _array[a] = _array[b];
            _array[b] = t;
        }

        private void Expand() {
            var newlist = new T[_array.Length << 1];
            Array.Copy(_array, newlist, _array.Length);
            _array = newlist;
        }

        public bool Any() {
            return _size > 0;
        }

        public void Enqueue(T newValue) {
            int pos = ++_size;
            if (_size >= _array.Length) {
                Expand();
            }
            _array[pos] = newValue;
            while (pos > 1) {
                int parent = pos >> 1;
                if (_compare(_array[parent], _array[pos]) > 0) {
                    Swap(parent, pos);
                    pos = parent;
                } else {
                    break;
                }
            }
