def local_str(query : str) -> int:
    import Levenshtein
    return Levenshtein.distance(query , secret_str)


def query_str(query : str) -> int:
    global count
    count += 1
    if DEBUG:
        ans = local_str(query)
        return ans
    else:
        print("? " + query)
        ans = int(input())
        if ans == 0:
            print("! " + query)
            sys.exit(0)
        return ans

def guess_length() -> int:
    c = "a"
    a = query_str(c)
    if a == 128:
        return 128
    al = query_str(c * a)
    al2 = query_str(c * (a + 1))
    if al >= al2:
        return a + 1
    else:
        return a


def merge(S : str, T : str) -> str:
    t = 0
    len_t = len(T)
    d = query_str(T)
    for s, c in enumerate(S):
        while t < len_t:
            l = T[:t +s]
            r = T[s + t:]
            d2 = query_str(l + c + r)
            if d2 < d:
                T = l + c + r
                d = d2
                break
            t += 1
        if t == len_t:
            T = T + c
    return T

def guessing():
    password_len = guess_length()
    chars = []
    for c in string.ascii_letters + string.digits:
        unmatch_word_num = query_str(c * password_len)
        if password_len - unmatch_word_num > 0:
            chars.append(c * (password_len - unmatch_word_num))
    while len(chars) > 1:
        chars.sort(key=lambda x: len(x))
        m = merge(chars[0], chars[1])
        chars[1] = m
        chars = chars[1:]
    query_str(chars[0])
    return chars[0]


