use std::io::Write;
use std::cmp::*;

fn query(a: &[char]) -> usize {
    static mut CNT: usize = 0;
    unsafe {
        assert!(CNT < 850);
        CNT += 1;
    }
    let ask: String = a.iter().cloned().collect();
    println!("{}", ask);
    std::io::stdout().flush().ok();
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    s.trim().parse().unwrap()
}

fn run() {
    let op: Vec<char> = "qwertyuiopasdfghjklzxcvbnmQWERTYUIOPASDFGHJKLZXCVBNM1234567890".chars().collect();
    let len = 128;
    assert!(op.len() == 26 + 26 + 10);
    let mut h = std::collections::BinaryHeap::new();
    let mut sum = 0;
    for c in op.iter().cloned() {
        let a = vec![c; len];
        let x = query(&a);
        if x < len {
            h.push(Reverse((len - x, vec![c; len - x])));
            sum += len - x;
        }
    }
    let sum = sum;
    while h.len() > 1 {
        let Reverse((x, a)) = h.pop().unwrap();
        let Reverse((y, mut s)) = h.pop().unwrap();
        let mut pos = 0;
        for (i, a) in a.into_iter().enumerate() {
            loop {
                s.insert(pos, a);
                if query(&s) == sum - i - 1 - y {
                    pos += 1;
                    break;
                } else {
                    s.remove(pos);
                    pos += 1;
                }
            }
        }
        h.push(Reverse((x + y, s)));
    }
    let Reverse((_, a)) = h.pop().unwrap();
    let ans: String = a.into_iter().collect();
    println!("! {}", ans);
}

fn main() {
    run();
}

